# ── профили выдачи: канонические имена ЧИТАЮТСЯ ИЗ `data-model.md` §5.11 ────
# Второй литеральный источник правды в инструменте есть тот же дефект, что
# второй источник правды в документах, — и за него отклонили две партии. До v4
# кортеж был вписан в инструмент руками; вердикт Codex (пункт 12) справедливо
# назвал это второй копией enum'а. Теперь enum разбирается из модели, а
# инструмент держит только то, чего модель не выражает: какие из профилей
# КЛИЕНТСКИЕ (префикс `client`) и какие имена похожи на профиль, но им не
# являются. Короткого `clientLive` в enum нет — и именно поэтому по такому
# имени не сопоставляется ни одна политика видимости.
def output_profiles(root):
    """(все профили, клиентские) из `type OutputProfile = …` модели данных.

    Возврат `(None, None)` означает: enum не прочитан. Инструмент обязан
    назвать это вакуумом, а не подставить свою копию по памяти.
    """
    p = pathlib.Path(root) / 'docs/product/data-model.md'
    if not p.exists():
        return None, None
    m = re.search(r'type\s+OutputProfile\s*=\s*(.*?);', p.read_text(encoding='utf-8'), re.S)
    if not m:
        return None, None
    names = tuple(dict.fromkeys(re.findall(r'"([A-Za-z][A-Za-z0-9]*)"', m.group(1))))
    if not names:
        return None, None
    return names, tuple(n for n in names if n.startswith('client'))


# Идентификаторы на `client*`/`internal*`, профилями НЕ являющиеся. Список
# закрытый: любое новое имя вида `clientXxx` обязано быть либо профилем, либо
# объявлено здесь — иначе это опечатка в имени профиля, а её цена — молча
# несопоставленная политика видимости.
PROFILE_VOCAB_OK = ('clientSafe', 'clientSafeTransform', 'clientSafeTransformId',
                    'clientTitle', 'clientPresent', 'clientDelivered',
                    'clientProjection', 'clientTransform',
                    'internalOnly', 'internalUse')

# ── КАРДИНАЛЬНОСТЬ КАК ОБЩИЙ КЛАСС ПРОВЕРОК (v4c) ───────────────────────────
# Codex назвал это классом №8 из отсутствующих и был прав дословно: «`=1`, `≤1`,
# `≥1`, nonempty и pairwise uniqueness должны извлекаться из типов, таблиц и
# инвариантов, а не добавляться отдельным regex после каждого аудита».
#
# Поэтому ниже ОДНА грамматика и ТРИ реестра факта (`DM_CARDINALITY`,
# `OUT_BINDING_CANON`, `OUT_ACTION_POLICY`). Грамматика не знает, откуда пришёл
# фрагмент — из тела типа, из ячейки таблицы или из пункта §9: она читает
# границу. Реестр знает только КАНОН и живёт В ИНСТРУМЕНТЕ, а не выводится из
# проверяемой прозы — потому что M38/M39 испортили ОБЕ копии правила
# согласованно, и сверка копий между собой дала бы зелёный свет: копии
# согласны, обе неверны. Добавление факта стоит одной строки реестра.

RU_CARD_NUM = {
    'ноль': 0, 'нуль': 0, 'нол': 0,
    'один': 1, 'одна': 1, 'одно': 1, 'одного': 1, 'одной': 1, 'одну': 1,
    'одним': 1, 'одном': 1, 'одному': 1,
    'два': 2, 'две': 2, 'двух': 2, 'двум': 2, 'двумя': 2,
    'три': 3, 'трёх': 3, 'трех': 3, 'трём': 3, 'трем': 3,
    'четыре': 4, 'четырёх': 4, 'четырех': 4,
    'пять': 5, 'пяти': 5, 'шесть': 6, 'шести': 6,
    'семь': 7, 'семи': 7, 'восемь': 8, 'восьми': 8,
    'девять': 9, 'девяти': 9, 'десять': 10, 'десяти': 10,
}

# Грамматика границы. Порядок важен: длинные формы раньше коротких, символьные
# раньше словесных. `n…n`/`n..n` — открытая сверху граница (`0…n` ⇒ `≥ 0`).
_CARD_GRAMMAR = (
    (r'(\d+)\s*(?:…|\.\.\.|\.\.)\s*n\b',                       'range-open'),
    (r'(\d+)\s*(?:или|,\s*|-)\s*(\d+)\b(?!\s*(?:…|\.\.))',      'range-closed'),
    (r'≥\s*(\d+)',                                             '≥'),
    (r'≤\s*(\d+)',                                             '≤'),
    (r'(?<![<>≥≤=])=\s*(\d+)',                                 '='),
    (r'не\s+более\s+(\w+)',                                    '≤'),
    (r'не\s+больше\s+(\w+)',                                   '≤'),
    (r'максимум\s+(\w+)',                                      '≤'),
    (r'не\s+менее\s+(\w+)',                                    '≥'),
    (r'минимум\s+(\w+)',                                       '≥'),
    (r'хотя\s+бы\s+(\w+)',                                     '≥'),
    (r'ровно\s+(\w+)',                                         '='),
    (r'непуст\w*',                                             'nonempty'),
    (r'\bни\s+одного\b|\bни\s+одной\b|\bноль\b|\bнет\s+ни\s+одн', 'zero'),
)
_CARD_UNIQUE = re.compile(r'уникал\w*|попарно\s+не\s+пересека\w*|не\s+пересека\w*|'
                          r'без\s+дублик\w*', re.I)


def card_parse(frag: str):
    """Нормализованная граница из ЛЮБОГО фрагмента → `(оператор, n)` или None.

    Один разбор для трёх источников — тела типа, ячейки таблицы и пункта
    инвариантов. Возвращает первую найденную границу: во фрагменте вида
    «не более одного `authoritative`; ноль допустим только при конфликте»
    границей является первое утверждение, а не оговорка после точки с запятой,
    поэтому вызывающая сторона обязана обрезать фрагмент по своей границе
    предложения — реестр это и делает локатором.

    `nonempty` нормализуется в `('≥', 1)`: «непуст» и «хотя бы один» — одно и
    то же утверждение, записанное двумя способами, и различать их означало бы
    ловить формулировку вместо смысла.
    """
    best = None
    for pat, op in _CARD_GRAMMAR:
        m = re.search(pat, frag, re.I)
        if not m:
            continue
        if op == 'nonempty':
            got = ('≥', 1)
        elif op == 'zero':
            got = ('=', 0)
        elif op == 'range-open':
            got = ('≥', int(m.group(1)))
        elif op == 'range-closed':
            lo, hi = int(m.group(1)), int(m.group(2))
            if hi != lo + 1:
                continue
            got = ('≤', hi) if lo == 0 else ('range', (lo, hi))
        else:
            raw = m.group(1)
            n = int(raw) if raw.isdigit() else RU_CARD_NUM.get(raw.lower())
            if n is None:
                continue
            got = (op, n)
        if best is None or m.start() < best[0]:
            best = (m.start(), got)
    return best[1] if best else None


def card_parse_cell(cell: str):
    """Граница из ЯЧЕЙКИ таблицы: читается ведущее выражение, а не вся ячейка.

    В `≥ 1, все делят ровно один Run ID` количеством привязок является `≥ 1`;
    `ровно один` относится там к Run ID, а не к числу привязок, и читать
    ячейку целиком означало бы перепутать два разных факта. Голое число
    (`**0**`) читается как `= 0`: колонка называет количество, других значений
    у неё нет.
    """
    lead = re.sub(r'[*_`]', '', cell).split(',')[0].strip()
    m = re.fullmatch(r'(\d+)', lead)
    return ('=', int(m.group(1))) if m else card_parse(lead)


def card_clauses(text: str):
    """Придаточные фрагмента: границы — `; , .` и союз «и».

    Инвариант вида «существует хотя бы одна привязка `primaryAuthoritative`,
    все такие привязки делят ровно один Run ID, и привязок `preview` ноль»
    несёт ТРИ разных количественных факта в одном предложении. Читать его
    целиком — значит прочитать первый и объявить проверенными все три.
    """
    return [c for c in re.split(r'[;,.]|\s+и\s+', text) if c.strip()]


def card_in_clause(text: str, anchor_rx: str):
    """(граница, придаточное) для первого придаточного с названным предметом."""
    for c in card_clauses(text):
        if re.search(anchor_rx, c, re.I):
            return card_parse(c), c.strip()
    return None, None


def card_fmt(card) -> str:
    """Граница человеческим текстом — для сообщения находки."""
    if card is None:
        return 'граница не названа'
    if card == 'unique':
        return 'попарная уникальность'
    op, n = card
    if op == 'range':
        return f'{n[0]}…{n[1]}'
    return f'{op} {n}'


# Канонические границы модели данных. Каждая запись: ключ находки · локатор
# УТВЕРЖДЕНИЯ (не ответа: границу извлекает грамматика) · канон · почему.
# Локатор находит ВСЕ вхождения: одно и то же правило записано в определении
