# ── кардинальность привязок расчёта к выдаче (`OUT-BINDING`, v4c) ────────────
# Канон держится ЗДЕСЬ. M38/M39 испортили таблицу §6.2 и инварианты OUT-19/20
# СОГЛАСОВАННО: обе копии остались согласны друг с другом и обе — неверны.
# Независимый источник кардинальности — единственное, что такую порчу видит.
#
# Единица счёта названа явно, потому что фактов ДВА, а не один: сколько
# ПРИВЯЗОК и сколько различных RUN ID. «≥ 1 привязка, все делят ровно один
# Run ID» — это `≥ 1` привязок и `= 1` прогонов; спутать их означает объявить
# проверенным то, что не проверялось.
OUT_BINDING_TABLE = {
    # (группа строк §6.2, колонка) → (канон привязок, канон Run ID | None)
    ('client', 'primaryAuthoritative'): (('≥', 1), ('=', 1)),
    ('client', 'preview'):              (('=', 0), None),
    ('live', 'primaryAuthoritative'):   (('≥', 1), ('=', 1)),
    ('live', 'preview'):                (('≤', 1), None),
    ('export', 'primaryAuthoritative'): (('≥', 0), None),
    ('export', 'preview'):              (('≥', 0), None),
}
# Профили, образующие каждую группу строк. Читается из enum'а модели: группа
# `client` — все клиентские профили, КРОМЕ живой конфигурации.
OUT_BINDING_GROUPS = {
    'client': ('clientReadOnly', 'clientPdf', 'clientEmail', 'clientPrint'),
    'live':   ('clientLiveConfiguration',),
    'export': ('internalExport',),
}
