# ── жизненный цикл открытой клиентской сессии (`OUT-SESSION`, v4c) ──────────
# Несущая конструкция принятого прочтения R-07 (§1.4): сессия держит
# ИСТОРИЧЕСКИЙ `entry`-указатель и ДЕЙСТВУЮЩИЙ `current`; ревалидация меняет
# только второй и обязана порождать событие журнала (M-4). M40/M41/M42 сняли
# по одной опоре из трёх, и каждая порча по отдельности выглядит правкой прозы.
#
# Поля сессии: имя → «единственный указатель» (не массив) либо «есть».
OUT_SESSION_FIELDS = {
    'entryPreflightResultId':   ('single', 'исторический вердикт входа'),
    'entryPolicyVersion':       ('single', 'версия политики на входе'),
    'currentPreflightResultId': ('single', 'действующий вердикт — ровно один'),
    'currentPolicyVersion':     ('single', 'действующая версия политики'),
    'lastRevalidatedAt':        ('single', 'когда вердикт пересобирался последний раз'),
    'exitedAt':                 ('any',    'выход — единственный способ закрыть сессию'),
}
# Четыре триггера §12.1.1. Перечислены, а не «по изменению чего-либо»: каждый
# обязан присутствовать И в таблице триггеров, И в инварианте OUT-63.
OUT_SESSION_TRIGGERS = (
    (r'коммит\s+новой\s+`VariantVersion`',
     'коммит новой `VariantVersion` — закоммиченная версия есть субъект '
     'authoritative-прогона проекции'),
    (r'активация\s+другой\s+версии\s+документа|активн\w+\s+`DocumentVersion`',
     'активация другой версии документа — от неё зависят привязки и вложения'),
    (r'переход\s+текущего\s+прогона\s+в\s+`stale`|в\s+`stale`',
     '`stale` текущего прогона — он блокирует все клиентские профили (STALE-001)'),
    (r'смена\s+`policyVersion`',
     'смена `policyVersion` — проекция обязана строиться политиками ровно '
     'одной версии (OUT-17)'),
)
# События журнала сессии (§12.2). Ревалидация меняет три поля сессии и состав
# проекции, поэтому по M-4 обязана иметь СВОЁ событие: сессия, в которой блок
# ушёл из проекции беззвучно, не отличима от сессии, где его не показывали.
OUT_SESSION_EVENTS = (
    ('client_mode.entered',     r'профил',                    'вход в клиентский профиль'),
    ('client_mode.revalidated', r'currentPreflightResultId',
     'ревалидация открытой сессии: событие обязано нести прежний и новый '
     '`currentPreflightResultId`, иначе «что изменилось на экране заказчика» '
     'нечем ответить (M-4)'),
    ('client_mode.exited',      r'причин',                    'выход из профиля'),
)

