# ───────────────────────── проверяльщик ─────────────────────────────────────

class Verifier:
    def __init__(self, root: pathlib.Path):
        self.root = pathlib.Path(root)
        self.new = []      # (cls, where, msg) — валят сборку
        self.known = []    # (cls, where, msg, ref) — известные открытые
        self.warn = []
        self.vacuum = []   # подмножество self.new: «проверка НЕ ВЫПОЛНЕНА»
        self._used_allow = {}    # key → сколько строк подавила запись
        self._used_known = {}
        self._used_known_file = {}
        self._used_known_class = {}
        self._quoted = {}
        self._cache = {}
        self._globs = {}
        self.fx = {}       # величины, вычитанные из фикстуры (см. _arithmetic)
        self._allow_hits = {}    # key → [номера строк]
        self._known_hits = {}
        self._classes = set()    # какие классы реально зарегистрировали вывод
        self._path_scope = RepositoryValidationScope(self.root)
        self._stale_ok = {}
        for rel, (h, _) in STALE_ARTIFACTS.items():
            p = self.root / rel
            self._stale_ok[rel] = (p.exists() and
                hashlib.sha256(p.read_bytes()).hexdigest() == h)

    # -- инфраструктура -------------------------------------------------------
    def read(self, rel):
        if rel in self._cache:
            return self._cache[rel]
        p = self.root / rel
        v = p.read_text(encoding='utf-8') if p.exists() else None
        self._cache[rel] = v
        return v

    def files(self, pattern):
        # Кэш на экземпляр: один и тот же glob перечисляется несколькими
        # проверками, а репозиторий содержит два артефакта по 450 КБ.
        if pattern not in self._globs:
            out = []
            for p in sorted(self.root.rglob(pattern)):
                if not p.is_file():
                    continue
                # Стороннее и производное исключается ПО ПРИРОДЕ, а не
                # разрешением: node_modules — чужой код, dist — вывод
                # сборки, ни то ни другое здесь не авторствуется, и
                # предъявлять к ним правила проекта бессмысленно.
                # Первый прогон после установки зависимостей дал 265
                # нарушений, и все 265 были строками версий пакетов,
                # прочитанными детектором дат как двузначные годы.
                # Основание то же, что у реестра требований: исключение
                # по конструкции, не по каталогу удобства.
                if (self._path_scope.excludes(p) or
                        any(d in p.relative_to(self.root).parts
                            for d in ('dist', '__pycache__', '.vite'))):
                    continue
                if True:
                    rel = p.relative_to(self.root).as_posix()
                    txt = p.read_text(encoding='utf-8', errors='replace')
                    self._cache[rel] = txt
                    out.append((rel, txt))
            self._globs[pattern] = out
        return list(self._globs[pattern])

    @staticmethod
    def _path_key(path: str) -> str:
        """Путь модуля без расширения и необязательного `/index`."""
        key = path.replace('\\', '/')
        for suffix in ('.tsx', '.ts', '.jsx', '.js'):
            if key.endswith(suffix):
                key = key[:-len(suffix)]
                break
        return key[:-len('/index')] if key.endswith('/index') else key

    @classmethod
    def _module_target(cls, importer: str, specifier: str):
        """Разрешает только локальные relative/@ пути в стабильный ключ."""
        if specifier.startswith('@/'):
            target = 'src/' + specifier[len('@/'):]
        elif specifier.startswith('.'):
            target = posixpath.normpath(posixpath.join(
                posixpath.dirname(importer), specifier))
        else:
            return None
        return cls._path_key(target)

    @staticmethod
    def _module_references(text: str):
        """Статические, побочные и динамические module specifier с адресом.

        TypeScript AST здесь не нужен: проверяется контракт пути, а не
        семантика выражения. Темперированный шаблон не пересекает следующую
        import/export-декларацию, поэтому отсутствие `from` не присваивает
        чужой specifier предыдущему `export function`.
        """
        refs = []
        static = re.compile(
            r'(?ms)^[ \t]*(?P<kind>import|export)\s+'
            r'(?!default\b|function\b|class\b|const\b|let\b|var\b)'
            r'(?:(?!^[ \t]*(?:import|export)\b).)*?'
            r'\bfrom\s*(?P<quote>[\'\"])(?P<spec>[^\'\"]+)(?P=quote)')
        side_effect = re.compile(
            r'(?m)^[ \t]*import\s*(?P<quote>[\'\"])(?P<spec>[^\'\"]+)'
            r'(?P=quote)')
        dynamic = re.compile(
            r'\bimport\s*\(\s*(?P<quote>[\'\"])(?P<spec>[^\'\"]+)'
            r'(?P=quote)\s*\)')
        for kind, rx in (('static', static), ('side-effect', side_effect),
                         ('dynamic', dynamic)):
            for match in rx.finditer(text):
                declaration = match.group(0)
                actual_kind = match.groupdict().get('kind') or kind
                refs.append((
                    match.start(),
                    actual_kind,
                    match.group('spec'),
                    text.count('\n', 0, match.start()) + 1,
                    declaration,
                ))
        # Один синтаксический узел не должен давать две находки, но два
        # одинаковых импорта на разных строках обязаны оставаться видимыми.
        unique = {}
        for ref in refs:
            unique[(ref[0], ref[1], ref[2])] = ref
        return sorted(unique.values())

    @staticmethod
    def _mask_comments(text: str, *, line_comments: bool = True) -> str:
        """Убирает комментарии, сохраняя строки и строковые литералы."""
        out = []
        i = 0
        quote = None
        escaped = False
        while i < len(text):
            char = text[i]
            nxt = text[i + 1] if i + 1 < len(text) else ''
            if quote is not None:
                out.append(char)
                if escaped:
                    escaped = False
                elif char == '\\':
                    escaped = True
                elif char == quote:
                    quote = None
                i += 1
                continue
            if char in ('\'', '\"', '`'):
                quote = char
                out.append(char)
                i += 1
                continue
            if char == '/' and nxt == '*':
                out.extend((' ', ' '))
                i += 2
                while i < len(text):
                    if text[i] == '*' and i + 1 < len(text) and text[i + 1] == '/':
                        out.extend((' ', ' '))
                        i += 2
                        break
                    out.append('\n' if text[i] == '\n' else ' ')
                    i += 1
                continue
            if line_comments and char == '/' and nxt == '/':
                out.extend((' ', ' '))
                i += 2
                while i < len(text) and text[i] != '\n':
                    out.append(' ')
                    i += 1
                continue
            out.append(char)
            i += 1
        return ''.join(out)

    def emit(self, cls, rel, lineno, line, msg):
        self._classes.add(cls)
        if cls in QUOTE_EXEMPT and rel in EXTRACTED_SOURCES and RX_REQ_ROW.match(line.strip()):
            # Цитата норматива по форме строки в файле, порождённом
            # экстракцией. Не молчание: считается и печатается сводкой.
            self._quoted[(rel, cls)] = self._quoted.get((rel, cls), 0) + 1
            return
        h = fp(line)
        key = (rel, cls, h)
        if key in ALLOW:
            # Подавление считается: дословный дубль ALLOW-строки, дописанный
            # в файл как новое нарушение, подавлялся бы той же записью.
            # Запись, сработавшая больше одного раза, — нарушение ALLOW-DUP.
            self._allow_hits.setdefault(key, set()).add(lineno)
            self._used_allow[key] = len(self._allow_hits[key])
            return
        if rel in STALE_ARTIFACTS and self._stale_ok.get(rel):
            self.known.append((cls, f'{rel}:{lineno}', msg, STALE_ARTIFACTS[rel][1]))
            return
        if key in KNOWN_OPEN:
            self._known_hits.setdefault(key, set()).add(lineno)
            self._used_known[key] = len(self._known_hits[key])
            self.known.append((cls, f'{rel}:{lineno}', msg, KNOWN_OPEN[key]))
            return
        fkey = (rel, cls)
        if fkey in KNOWN_OPEN_FILE:
            self._used_known_file[fkey] = self._used_known_file.get(fkey, 0) + 1
            self.known.append((cls, f'{rel}:{lineno}', msg, KNOWN_OPEN_FILE[fkey]))
            return
        if cls in KNOWN_OPEN_CLASS:
            self._used_known_class[cls] = self._used_known_class.get(cls, 0) + 1
            self.known.append((cls, f'{rel}:{lineno}', msg, KNOWN_OPEN_CLASS[cls]))
            return
        self.new.append((cls, f'{rel}:{lineno}', f'{msg} (fp={h})'))

    def fail(self, cls, where, msg):
        self._classes.add(cls)
        self.new.append((cls, where, msg))
        # ВАКУУМ УЧИТЫВАЕТСЯ ОТДЕЛЬНО И ГРОМЧЕ. Между «нашёл расхождение» и
        # «не смог проверить» разница принципиальная: первое — дефект в
        # документе, второе — дефект в ИНСТРУМЕНТЕ. Молчаливая сверка хуже
        # отсутствующей, потому что зелёный отчёт по ней читают как
        # доказательство. Вакуум по-прежнему валит сборку — но не растворяется
        # среди обычных находок «одним из пяти».
        if '[вакуум]' in msg:
            self.vacuum.append((cls, where, msg))

    def scan(self, cls, rel, text, pattern, msg, flags=0):
        rx = re.compile(pattern, flags)
        for i, line in enumerate(text.split('\n'), 1):
            if rx.search(line):
                self.emit(cls, rel, i, line, f'{msg} — {line.strip()[:80]}')

    @staticmethod
    def _soften(pattern: str) -> str:
        """Литеральный пробел в шаблоне → «любой пробельный, хотя бы один».

        Класс дефекта, найденный дважды за одну сессию: правка документа по
        вердикту (перенос строки в `components-core.md`, добавление слов
        «точно … показ …» в `calculation-spec.md`) ломала РАЗБОР, и сверка
        превращалась в вакуум. Перенос строки внутри абзаца или ячейки —
        нормальная типографская правка, и ни один `grab` не имеет права от
        неё падать. Преобразование строго расширяющее: пробел остаётся
        обязательным, но теперь им может быть `\\n`, NBSP или U+202F, поэтому
        ни один сегодня работающий шаблон не может от него сломаться.
        Внутри классов `[...]` и после `\\` ничего не меняется.
        """
        out, i, in_class = [], 0, False
        while i < len(pattern):
            ch = pattern[i]
            if ch == '\\' and i + 1 < len(pattern):
                out.append(pattern[i:i + 2])
                i += 2
                continue
            if ch == '[':
                in_class = True
            elif ch == ']':
                in_class = False
            if ch == ' ' and not in_class:
                # квантификатор после пробела означает, что автор уже управляет
                # его количеством — такой пробел не трогаем
                if i + 1 < len(pattern) and pattern[i + 1] in '*+?{':
                    out.append(ch)
                else:
                    out.append('[\\s  ]+')
                i += 1
                continue
            out.append(ch)
            i += 1
        return ''.join(out)

    def grab(self, text, pattern, cls, desc, flags=0):
        m = re.search(self._soften(pattern), text, flags)
        if not m:
            self.fail(cls, desc, f'[вакуум] паттерн не найден: {desc} — проверка не может быть выполнена')
            raise Vacuum(desc)
        return m

    def eq(self, cls, desc, got, exp):
        if got != exp:
            self.fail(cls, desc, f'{desc}: получено {got}, ожидается {exp}')

    # -- 1. Токены: слои, ссылки, точные значения -----------------------------
    def check_tokens(self):
        css = self.read('design-system/tokens.css') or ''
        readme = self.read('design-system/README.md') or ''
        code = re.sub(r'/\*.*?\*/', '', css, flags=re.S)  # без комментариев
        decls = dict(re.findall(r'(--[\w-]+)\s*:\s*([^;]+);', code))

        # TOKEN-LAYER: литеральные цвета только в primitive-слое;
        # semantic-цвета — только ссылки на primitive.
        for name, val in decls.items():
            v = val.strip()
            if re.search(r'#[0-9A-Fa-f]{3,8}\b|rgba?\(', v) and not name.startswith('--primitive-color-'):
                self.fail('TOKEN-LAYER', 'tokens.css',
                          f'{name}: литеральный цвет «{v[:40]}» вне primitive-слоя')
            if name.startswith('--color-') and not re.fullmatch(r'var\(--primitive-[\w-]+\)', v):
                self.fail('TOKEN-LAYER', 'tokens.css',
                          f'{name}: semantic-цвет обязан ссылаться на primitive, найдено «{v[:40]}»')

        def resolve(name, depth=0):
            if depth > 10 or name not in decls:
                return None
            v = decls[name].strip()
            m = re.fullmatch(r'var\((--[\w-]+)\)', v)
            return resolve(m.group(1), depth + 1) if m else v.upper()

        # R-02: точные значения primary action
        for tok, exp in [('--color-action-primary-bg', '#C94700'),
                         ('--color-action-primary-hover', '#B83F00'),
                         ('--color-action-primary-pressed', '#A63800'),
                         ('--color-action-primary-text', '#FFFFFF')]:
            self.eq('R-02', f'tokens {tok}', resolve(tok), exp)
        # R-03: selection и двухслойный фокус
        self.eq('R-03', 'tokens --color-selection-border', resolve('--color-selection-border'), '#C94700')
        self.eq('R-03', 'tokens --color-focus-ring', resolve('--color-focus-ring'), '#005FCC')
        self.eq('R-03', 'tokens --color-focus-separator', resolve('--color-focus-separator'), '#FFFFFF')
        # R-01: #FD5E00 разрешён только в трёх семантических записях.
        # Третья добавлена ADR-R1-02 (REDESIGN R1, efcbdaf3): оранжевый
        # display-numeral легален также на --color-surface-stage-deep —
        # см. tokens.css §"R1 — CANVAS / PAPER / STAGE".
        for name in decls:
            if name.startswith('--color-') and name not in (
                    '--color-brand-accent', '--color-text-display-accent',
                    '--color-text-display-accent-on-stage-deep'):
                if resolve(name) == '#FD5E00':
                    self.fail('R-01', 'tokens.css', f'{name} разрешается в #FD5E00 — бренд-оранжевый '
                              f'запрещён как семантика (R-01)')

        # TOKEN-001: color-mix не экспортируется
        if 'color-mix' in css:
            self.fail('TOKEN-001', 'tokens.css', 'color-mix() не является exact value (R-25, TOKEN-001/004)')

        # LAYOUT-007: плотность не переопределяется режимом на уровне CSS
        if re.search(r'\.mode-\w+\s+\.density-\w+\s*\{', css):
            self.fail('LAYOUT-007', 'tokens.css', 'Output Profile переопределяет плотность (D-16, TOKEN-004)')

        # LAYOUT-003
        if not re.search(r'--content-max-width:\s*1200px', css):
            self.fail('LAYOUT-003', 'tokens.css', 'content-max-width должен быть 1200px')

        # TOKEN-REF: ссылки/упоминания токенов существуют.
        # CLI-флаги (`--strict`) — не токены: кастом-свойство этой системы
        # всегда ≥ 2 сегментов; однословное `--x` проверяется, только если
        # объявлено (структурное сужение, не словарь исключений).
        declared = set(decls)
        for src, name in ((readme, 'README'), (css, 'tokens.css')):
            for used in set(re.findall(r'var\((--[\w-]+)\)', src)):
                if used not in declared:
                    self.fail('TOKEN-REF', name, f'ссылка на несуществующий токен {used}')
        for mention in set(re.findall(r'`(--[\w-]+)`', readme)):
            multi = '-' in mention[2:]
            if multi and mention not in declared:
                self.fail('TOKEN-REF', 'README', f'в тексте упомянут несуществующий токен {mention}')

        # R-24: реальные пары кегль/интерлиньяж/вес из --type-* токенов
        sizes, lines = {}, {}
        for role, kind, val in re.findall(r'--type-([a-z0-9-]+)-(size|line)\s*:\s*(\d+)px', code):
            (sizes if kind == 'size' else lines)[role] = int(val)
        if not sizes:
            self.fail('R-24', 'tokens.css', '[вакуум] не найдено ни одной пары --type-*-size/-line')
        for role, (es, el) in R24_EXACT.items():
            if role not in sizes or role not in lines:
                self.fail('R-24', 'tokens.css', f'роль R-24 «{role}» не объявлена парой size/line')
                continue
            if (sizes[role], lines[role]) != (es, el):
                self.fail('R-24', 'tokens.css',
                          f'{role}: {sizes[role]}/{lines[role]}, R-24 требует {es}/{el}')
        # Пара обязана быть полной: роль с size без line (или наоборот) прежде
        # молча пропускалась — снятие `--type-input-line` не ловилось ничем.
        for role in set(sizes) | set(lines):
            if role not in sizes or role not in lines:
                self.fail('R-24', 'tokens.css',
                          f'роль «{role}» объявлена неполной парой (size={sizes.get(role)}, '
                          f'line={lines.get(role)}) — R-24 требует обе величины')
                continue
            if role in R24_EXACT:
                continue
            if sizes[role] not in R24_GENERIC:
                self.fail('R-24', 'tokens.css',
                          f'{role}: кегль {sizes[role]}px вне шкалы R-24 '
                          f'{sorted(R24_GENERIC)}')
            elif lines[role] not in R24_GENERIC[sizes[role]]:
                self.fail('R-24', 'tokens.css',
                          f'{role}: {sizes[role]}px с интерлиньяжем {lines[role]} вне матрицы R-24')
        for tok, exp in R24_WEIGHTS.items():
            got = resolve(tok)
            if got != exp:
                self.fail('R-24', 'tokens.css', f'{tok}: вес {got}, R-24 требует {exp}')
        # запасная сетка: инлайн-пары в любых css-фрагментах и в теле спек
        for src, name in ((css, 'tokens.css'), (readme, 'README'),
                          (self.read('design-system/components-core.md') or '', 'components-core')):
            for a, b in re.findall(r'font-size:\s*(\d+)px\s*;?\s*line-height:\s*(\d+)px', src):
                a, b = int(a), int(b)
                if a not in R24_GENERIC:
                    self.fail('R-24', name, f'инлайн-кегль {a}px вне шкалы R-24')
                elif b not in R24_GENERIC[a]:
                    self.fail('R-24', name, f'инлайн-пара {a}/{b} вне матрицы R-24')

    # -- 1a. CSS-текст целиком (не только объявления токенов) -----------------
    def _css_sources(self):
        """Все куски CSS, за которые отвечает эта система.

        v2 разбирал только `--x: y;` в tokens.css. Мимо проходили: цвет в теле
        правила (`.text-display-accent { color: #FD5E00 }`), дописанный в конец
        tokens.css блок `.btn-primary{background:#FD5E00}` и тот же блок в
        fenced-css внутри README. Отгружаемый HTML сюда не входит: он на
        карантине и покрыт ARTIFACT-A11Y.
        """
        css = self.read('design-system/tokens.css')
        if css is None:
            self.fail('CSS-COLOR', 'tokens.css', '[вакуум] design-system/tokens.css отсутствует')
        else:
            yield 'design-system/tokens.css', css, 0
        for rel, text in self.files('*.md'):
            if rel.startswith('tools/'):
                continue
            for m in re.finditer(r'```(?:css|scss|less)\s*\n(.*?)```', text, re.S):
                yield rel, m.group(1), text[:m.start()].count('\n') + 1

    # ── CSS как CSS, а не как строки ────────────────────────────────────────
    # Вердикт Codex, класс 1 и пункт 2: девять мутаций прошли, потому что
    # разбор был построчным. Прошли: `border-radius` с переносом после
    # двоеточия; тень через `filter: drop-shadow()`; кегль в shorthand `font`;
    # отступ в `rem`; зона нажатия через `calc(var(...) - 1px)`; поздний дубль
    # `--content-max-width`, переопределяющий правильное значение; `border: 3px`
    # и `transition: 333ms` сырыми литералами; `overflow-x: visible` у таблицы.
    # Разбор ниже даёт декларации с номером строки, раскрывает shorthand `font`,
    # нормализует единицы и вычисляет `calc()` в объёме сложения/вычитания.

    @staticmethod
    def _css_rules(raw: str, _off: int = 0, _scope: str = ''):
        """[(область, [(свойство, значение, номер строки)])] — по декларациям.

        Комментарии вырезаются с сохранением нумерации, поэтому смещение строк
        совпадает с исходником. Значение склеивается через переносы, поэтому
        `border-radius:\\n  4px` — одна декларация, а не две строки текста.

        ОБЛАСТЬ включает условие at-rule: `@media (prefers-reduced-motion) :root`
        и `:root` — РАЗНЫЕ области, и переопределение длительностей в нулевые
        внутри media-query не является дублем. Без этого различия проверка
        дублей обвиняла бы обязательную реализацию правила 21.
        """
        code = re.sub(r'/\*.*?\*/', lambda m: '\n' * m.group(0).count('\n'), raw, flags=re.S)
        out, i, n = [], 0, len(code)
        while i < n:
            j = code.find('{', i)
            if j < 0:
                break
            sel = ' '.join(code[i:j].split())
            depth, k = 1, j + 1
            while k < n and depth:
                if code[k] == '{':
                    depth += 1
                elif code[k] == '}':
                    depth -= 1
                k += 1
            body = code[j + 1:k - 1]
            scope = (_scope + ' ' + sel).strip()
            if '{' in body:                      # at-rule: разобрать вложенное
                out.extend(Verifier._css_rules(
                    body, _off + code[:j + 1].count('\n'), scope))
            else:
                decls, pos = [], 0
                for part in body.split(';'):
                    if ':' in part:
                        prop, _, val = part.partition(':')
                        ln = _off + code[:j + 1].count('\n') + body[:pos].count('\n') + 1
                        decls.append((prop.strip().lower(), ' '.join(val.split()), ln))
                    pos += len(part) + 1
                out.append((scope, decls))
            i = k
        return out

    # Абсолютные единицы → px. `pt` разрешён только в печатных стилях
    # (требование foundation), и это исключение названо в README §0.
    _UNIT_PX = {'px': D('1'), 'rem': D('16'), 'em': D('16'), 'pt': D('4') / D('3'),
                'cm': D('96') / D('2.54'), 'mm': D('96') / D('25.4'), 'in': D('96')}

    @classmethod
    def _lengths_px(cls, value: str):
        """[(число в px, как записано)] для всех длин значения, включая calc()."""
        out = []
        for m in re.finditer(r'(-?\d+(?:\.\d+)?)(px|rem|em|pt|cm|mm|in)\b', value):
            out.append((D(m.group(1)) * cls._UNIT_PX[m.group(2)], m.group(0)))
        return out

    # ── скругление: запрещён скруглённый ПРЯМОУГОЛЬНИК, не круг ─────────────
    # F01 второй независимой атаки: инструмент запрещал ЛЮБОЕ ненулевое
    # значение и тем самым запрещал конструкцию, которую контракт прямо
    # РАЗРЕШАЕТ (`design-system/README.md` §1.6 «перфект-круг — официальная
    # форма», `provenance-dot` = perfect circle 8 px). Ложное срабатывание
    # дороже пропуска: гейт, который врёт на корректном коде, перестают читать,
    # и вместе с ложной находкой перестают читать настоящие.
    #
    # Правило проекта 4 читается буквально: «прямоугольники и идеальные круги».
    # Значит запрещено ненулевое скругление, которое не даёт окружности.
    # Окружность — это все радиусы `50%` при равных сторонах бокса.
    @staticmethod
    def _radius_kind(value: str) -> str:
        """'zero' · 'circle' · 'bad' — что за скругление объявлено."""
        parts = [p for p in re.split(r'\s*/\s*|\s+', ' '.join(value.split())) if p]
        if not parts:
            return 'bad'
        if all(re.fullmatch(r'0(?:px|rem|em|%|pt|vh|vw)?', p, re.I) for p in parts):
            return 'zero'
        if all(re.fullmatch(r'50%', p) for p in parts):
            return 'circle'
        return 'bad'

    @staticmethod
    def _box_sides(decls):
        """(ширина px, высота px) правила — или (None, None), если не объявлены.

        `border-radius: 50%` даёт окружность только при равных сторонах; на
        прямоугольнике это эллипс, то есть скруглённый прямоугольник другим
        способом. Стороны берутся из ТОГО ЖЕ правила: сравнивать с чужим
        правилом означало бы считать каскад, которого инструмент не считает,
        и молчаливо угадывать вместо проверки.
        """
        box = {}
        for prop, val, _ in decls:
            if prop in ('width', 'inline-size'):
                box['w'] = val
            elif prop in ('height', 'block-size'):
                box['h'] = val
        out = []
        for k in ('w', 'h'):
            px = Verifier._lengths_px(box.get(k, ''))
            out.append(px[0][0] if px else None)
        return tuple(out)

    @staticmethod
    def _expand_font(value: str):
        """shorthand `font` → (кегль px, интерлиньяж px) либо None.

        Аудитор спрятал внеканоническую пару 15/19 в `font: 500 15px/19px …`:
        запасная проверка R-24 знала только соседние longhand.
        """
        m = re.search(r'(-?\d+(?:\.\d+)?)(px|rem|em|pt)\s*/\s*(-?\d+(?:\.\d+)?)(px|rem|em|pt|$|\s)',
                      value)
        if not m:
            m2 = re.search(r'(-?\d+(?:\.\d+)?)(px|rem|em|pt)', value)
            return (D(m2.group(1)) * Verifier._UNIT_PX[m2.group(2)], None) if m2 else None
        u2 = m.group(4).strip() or 'px'
        return (D(m.group(1)) * Verifier._UNIT_PX[m.group(2)],
                D(m.group(3)) * Verifier._UNIT_PX.get(u2, D('1')))

    def check_css_effective(self):
        """Эффективная семантика CSS: каскад, дубли, shorthand, calc(), единицы."""
        raw = self.read('design-system/tokens.css')
        if raw is None:
            self.fail('CSS-EFFECTIVE', 'tokens.css',
                      '[вакуум] tokens.css отсутствует — эффективные декларации не разбираются')
            return
        rules = self._css_rules(raw)
        if not rules:
            self.fail('CSS-EFFECTIVE', 'tokens.css',
                      '[вакуум] ни одного CSS-правила не разобрано — парсер потерял файл')
            return
        rel = 'design-system/tokens.css'
        SCALE = {D(x) for x in (0, 4, 8, 12, 16, 24, 32, 48, 64)}
        TYPE_SIZES = {D(x) for x in (12, 14, 16, 24, 32, 36, 48, 64)}
        # `translate` входит в список потому, что построчный сканер знал его, а
        # эффективный — нет: после снятия дублирующего прохода по `tokens.css`
        # (F01) любое расхождение двух списков стало бы потерей охвата.
        SPACING = ('margin', 'padding', 'gap', 'row-gap', 'column-gap', 'inset',
                   'margin-top', 'margin-right', 'margin-bottom', 'margin-left',
                   'padding-top', 'padding-right', 'padding-bottom', 'padding-left',
                   'top', 'right', 'bottom', 'left', 'outline-offset', 'text-indent',
                   'translate')
        # (1) ДУБЛИ канонических custom properties в одном блоке: эффективным
        # становится ПОСЛЕДНЕЕ объявление, и правильная первая строка ничего
        # не доказывает (T06).
        seen = {}
        for sel, decls in rules:
            for prop, val, ln in decls:
                if not prop.startswith('--'):
                    continue
                key = (sel, prop)
                if key in seen:
                    self.emit('CSS-EFFECTIVE', rel, ln, f'CSS-EFFECTIVE:dup{prop}',
                              f'`{prop}` объявлен в `{sel}` повторно (первый раз — строка '
                              f'{seen[key][0]}, значение «{seen[key][1]}»; здесь «{val}»). '
                              f'Эффективным становится последнее: наличие правильной строки '
                              f'выше ничего не доказывает')
                seen[key] = (ln, val)
        # (2) Зона нажатия: значение обязано быть РОВНО токеном, без арифметики.
        for sel, decls in rules:
            for prop, val, ln in decls:
                if prop not in ('width', 'height', 'min-width', 'min-height'):
                    continue
                if 'hit-target' not in val:
                    continue
                if re.search(r'calc\(|[-+*/]\s*\d', val):
                    px = self._lengths_px(val)
                    self.emit('CSS-EFFECTIVE', rel, ln, 'CSS-EFFECTIVE:hit-calc',
                              f'`{sel} {{ {prop}: {val} }}` — арифметика вокруг токена зоны '
                              f'нажатия. R-04/XSC-07 требуют ровно 44 px; любое уменьшающее '
                              f'выражение{" (" + px[0][1] + ")" if px else ""} делает цель '
                              f'меньше нормы, а проверка подстроки этого не видит')
        # (3) Тень любым свойством, а не только box-shadow/text-shadow (T10),
        # и скругление по РАЗОБРАННОЙ декларации, а не по строке (T09):
        # `border-radius:\n  4px` — одна декларация, разрезанная переносом.
        for sel, decls in rules:
            for prop, val, ln in decls:
                if prop in ('filter', 'backdrop-filter') and 'drop-shadow' in val:
                    self.emit('CSS-SHADOW', rel, ln, 'CSS-SHADOW:filter',
                              f'`{sel} {{ {prop}: {val[:40]} }}` — тень через filter. '
                              f'Правило 4 запрещает тени как эффект, а не одно свойство')
                if prop in ('box-shadow', 'text-shadow'):
                    if not re.match(r'^(none|0\s+0\s+0(\s|$))', val):
                        self.emit('CSS-SHADOW', rel, ln, f'CSS-SHADOW:{prop}:{sel}',
                                  f'`{sel} {{ {prop}: {val[:40]} }}` — тени запрещены '
                                  f'(правило 4); `0 0 0 …` есть кольцо фокуса R-03, '
                                  f'а не тень')
                if prop == 'border-radius' or prop.startswith('border-') and prop.endswith('-radius'):
                    kind = self._radius_kind(val)
                    if kind == 'bad':
                        self.emit('CSS-RADIUS', rel, ln, f'CSS-RADIUS:{sel}:{prop}',
                                  f'`{sel} {{ {prop}: {val[:30]} }}` — правило 4 требует 0 '
                                  f'везде: прямоугольники и идеальные круги, скруглённых '
                                  f'прямоугольников в системе нет. Идеальный круг '
                                  f'записывается ровно как `50%` при равных сторонах '
                                  f'(README §1.6)')
                    elif kind == 'circle':
                        w, h = self._box_sides(decls)
                        if w is not None and h is not None and w != h:
                            self.emit('CSS-RADIUS', rel, ln, f'CSS-RADIUS:{sel}:ellipse',
                                      f'`{sel} {{ {prop}: {val[:30]} }}` при '
                                      f'{w}×{h} px — это эллипс, а не идеальный круг. '
                                      f'Правило 4 разрешает круг как форму, а не `50%` '
                                      f'как способ скруглить прямоугольник')
                if prop == '--radius' and not re.fullmatch(r'0(?:px|rem|%)?', val.strip()):
                    self.emit('CSS-RADIUS', rel, ln, 'CSS-RADIUS:token',
                              f'`--radius: {val}` ≠ 0 (правило 4)')
                if re.search(r'\b(?:linear|radial|conic|repeating-\w+)-gradient\s*\(', val):
                    self.emit('CSS-GRADIENT', rel, ln, f'CSS-GRADIENT:{sel}:{prop}',
                              f'`{sel} {{ {prop}: {val[:40]} }}` — градиент запрещён '
                              f'(правило 4)')
        # (4) Отступы во ВСЕХ абсолютных единицах, не только px (T08).
        for sel, decls in rules:
            for prop, val, ln in decls:
                if prop not in SPACING:
                    continue
                for px, asis in self._lengths_px(val):
                    if abs(px) not in SCALE:
                        self.emit('CSS-SPACING', rel, ln, f'CSS-SPACING:{prop}:{asis}',
                                  f'`{sel} {{ {prop}: {val[:40]} }}` — «{asis}» это {px} px, '
                                  f'вне шкалы 4/8/12/16/24/32/48/64 (LAYOUT-001). Единица '
                                  f'значения роли не играет: шкала задана в пикселях')
        # (5) Кегль/интерлиньяж: каждый эффективный font-size, плюс shorthand
        # `font` (T13, T35). Пары уже проверяет R-24 по токенам — здесь
        # проверяется, что сырое значение вообще принадлежит шкале.
        for sel, decls in rules:
            pair = {}
            for prop, val, ln in decls:
                if prop == 'font':
                    got = self._expand_font(val)
                    if got:
                        pair['font-size'] = (got[0], ln, f'font: {val[:30]}')
                        if got[1] is not None:
                            pair['line-height'] = (got[1], ln, f'font: {val[:30]}')
                elif prop in ('font-size', 'line-height'):
                    px = self._lengths_px(val)
                    if px:
                        pair[prop] = (px[0][0], ln, f'{prop}: {val}')
            if 'font-size' in pair:
                size, ln, asis = pair['font-size']
                if size not in TYPE_SIZES:
                    self.emit('R-24', rel, ln, f'R-24:size{size}',
                              f'`{sel} {{ {asis} }}` — кегль {size} px вне типографической '
                              f'шкалы R-24 ({", ".join(str(int(x)) for x in sorted(TYPE_SIZES))})')
                elif 'line-height' in pair:
                    line = pair['line-height'][0]
                    if int(line) not in R24_GENERIC.get(int(size), set()):
                        self.emit('R-24', rel, ln, f'R-24:pair{size}/{line}',
                                  f'`{sel}` — пара {size}/{line} отсутствует в матрице R-24 '
                                  f'§1.9 (для {size} допустимы '
                                  f'{sorted(R24_GENERIC.get(int(size), set())) or "—"})')
        # (6) Сырые дизайн-литералы там, где устав требует токен (T36).
        LITERAL = (('border-width', r'\d+(?:px|rem|em)'),
                   ('border', r'(?<![\w-])\d+(?:px|rem|em)'),
                   ('border-top', r'(?<![\w-])\d+(?:px|rem|em)'),
                   ('border-bottom', r'(?<![\w-])\d+(?:px|rem|em)'),
                   ('transition', r'\d+m?s\b'),
                   ('transition-duration', r'\d+m?s\b'),
                   ('animation', r'\d+m?s\b'),
                   ('animation-duration', r'\d+m?s\b'))
        for sel, decls in rules:
            for prop, val, ln in decls:
                for p, pat in LITERAL:
                    if prop != p:
                        continue
                    if 'var(' in val:
                        continue
                    m = re.search(pat, val)
                    if m and m.group(0) not in ('0', '0px', '0s'):
                        self.emit('CSS-LITERAL', rel, ln, f'CSS-LITERAL:{prop}:{m.group(0)}',
                                  f'`{sel} {{ {prop}: {val[:40]} }}` — сырое дизайн-значение '
                                  f'«{m.group(0)}» вместо семантического токена (правило 2). '
                                  f'Токен, которого нет, добавляется в tokens.css с пометкой '
                                  f'provisional, а не инлайнится')
        # (7) Таблица обязана скроллиться в своём контейнере (правило 3a, T14).
        #
        # F02 и M06 второй независимой атаки — ОДНА ошибка разбора, давшая
        # одновременно ложное срабатывание и ложный пропуск. `overflow: <x> <y>`
        # объявляет ГОРИЗОНТАЛЬНУЮ ось ПЕРВЫМ значением: `auto hidden` это
        # `overflow-x: auto` (корректно, обвинялось), `hidden auto` —
        # `overflow-x: hidden` (нарушение, проходило). Прежний код брал
        # последнее слово и потому был неправ ровно в обе стороны.
        # Логическое `overflow-inline` в горизонтальном режиме письма — та же
        # ось; `overflow-block`/`overflow-y` к правилу 3a не относятся.
        for sel, decls in rules:
            for prop, val, ln in decls:
                if prop not in ('overflow-x', 'overflow', 'overflow-inline'):
                    continue
                if not re.search(r'table|tabelle|kostentabelle|\bdata-table\b', sel, re.I):
                    continue
                eff = val.split()[0] if prop == 'overflow' else val
                if eff.strip() not in ('auto', 'scroll'):
                    axis = ('первое значение shorthand' if prop == 'overflow'
                            else 'значение свойства')
                    self.emit('CSS-LAYOUT', rel, ln, f'CSS-LAYOUT:{sel}:{eff.strip()}',
                              f'`{sel} {{ {prop}: {val} }}` — горизонтальная ось '
                              f'({axis}) равна `{eff.strip()}`. Таблица обязана лежать в '
                              f'контейнере `overflow-x: auto` (правило 3a): смена шрифта '
                              f'меняет естественную ширину, и `{eff.strip()}` обрезает '
                              f'колонки либо ломает страницу горизонтальным скроллом')
        # (8) Эффективный контейнер контента: единственное значение (T06, T07).
        eff_max = [(sel, val, ln) for sel, decls in rules for prop, val, ln in decls
                   if prop == '--content-max-width']
        if not eff_max:
            self.fail('LAYOUT-003', rel, '[вакуум] `--content-max-width` не объявлен — '
                                         'ограничение контента не проверяется')
        else:
            for sel, val, ln in eff_max:
                px = self._lengths_px(val)
                if px and px[0][0] != D('1200'):
                    self.emit('LAYOUT-003', rel, ln, f'LAYOUT-003:token{px[0][1]}',
                              f'`--content-max-width: {val}` = {px[0][0]} px, LAYOUT-003 '
                              f'требует 1200 px')
        for sel, decls in rules:
            for prop, val, ln in decls:
                if prop != 'max-width' or 'var(' in val:
                    continue
                px = self._lengths_px(val)
                if px and px[0][0] > D('1200'):
                    self.emit('LAYOUT-003', rel, ln, f'LAYOUT-003:{sel}:{px[0][1]}',
                              f'`{sel} {{ max-width: {val} }}` = {px[0][0]} px обходит токен '
                              f'`--content-max-width` (1200 px, LAYOUT-003)')
        # (9) Правильный токен в неправильной роли (T11, T12).
        # R-01 проверял, во что разрешаются объявления; куда токен ПРИМЕНЁН —
        # не проверялось вовсе, и валидный `--color-brand-accent` проходил
        # фоном выделения.
        ACCENT = ('--color-brand-accent', '--color-text-display-accent',
                  '--primitive-color-brand-orange-500')
        for sel, decls in rules:
            for prop, val, ln in decls:
                if prop.startswith('--') or not any(a in val for a in ACCENT):
                    continue
                tok = next(a for a in ACCENT if a in val)
                bad_prop = prop in ('background', 'background-color', 'border-color',
                                    'border', 'border-top-color', 'border-bottom-color',
                                    'outline-color', 'fill', 'accent-color')
                bad_role = re.search(r'selected|selection|checked|focus|status|error|'
                                     r'success|warning|action|btn|button', sel, re.I)
                if bad_prop or bad_role:
                    how = 'фон/бордер' if bad_prop else 'семантика состояния'
                    self.emit('R-01', rel, ln, f'R-01:role:{sel}:{prop}',
                              f'`{sel} {{ {prop}: {val[:40]} }}` — бренд-оранжевый `{tok}` '
                              f'применён как {how}. R-01 запрещает оранжевый как цвет '
                              f'действия, выделения, фокуса и статуса независимо от того, '
                              f'через какой токен он записан. Разрешён единственный случай: '
                              f'`color` героя №1 DC-38 на `--color-surface-default`')

    def check_css(self):
        SCALE = {0, 4, 8, 12, 16, 24, 32, 48, 64}
        SPACING = (r'margin|margin-top|margin-right|margin-bottom|margin-left|'
                   r'padding|padding-top|padding-right|padding-bottom|padding-left|'
                   r'gap|row-gap|column-gap|inset|top|right|bottom|left|'
                   r'outline-offset|translate|text-indent')
        found_any = False
        for rel, raw, base in self._css_sources():
            found_any = True
            # ДУБЛИРУЮЩАЯ ДИАГНОСТИКА — отдельный дефект, не мелочь (F01).
            # `check_css_effective()` разбирает `tokens.css` как CSS (каскад,
            # shorthand, `calc()`, нормализация единиц) и покрывает те же четыре
            # класса строго шире. Построчный проход по тому же файлу давал
            # ВТОРУЮ находку на ту же декларацию: две записи об одной строке
            # читаются как два дефекта, и партия ищет второй, которого нет.
            # Здесь построчный проход остаётся тем, чем он единственно нужен, —
            # покрытием fenced-css внутри `.md`, куда эффективный разбор не
            # заходит. `CSS-COLOR` дублем не является: его нет в эффективном.
            effective_covers = (rel == 'design-system/tokens.css')
            # комментарии выкусываются с сохранением нумерации строк
            code = re.sub(r'/\*.*?\*/', lambda m: '\n' * m.group(0).count('\n'), raw, flags=re.S)
            for i, line in enumerate(code.split('\n'), 1):
                ln = base + i
                is_primitive = re.match(r'\s*--primitive-[\w-]+\s*:', line) is not None
                for m in re.finditer(r'#[0-9A-Fa-f]{3,8}\b|\brgba?\(|\bhsla?\(|\blab\(|\boklch\(', line):
                    if not is_primitive:
                        self.emit('CSS-COLOR', rel, ln, line,
                                  f'литеральный цвет «{m.group(0)}» вне primitive-слоя '
                                  f'(правило 2: только семантические токены)')
                if effective_covers:
                    continue
                for m in re.finditer(r'border-radius\s*:\s*([^;{}]+)', line):
                    # Идеальный круг разрешён контрактом (README §1.6) — см.
                    # `_radius_kind`. Строчный сканер обязан судить по тому же
                    # правилу, иначе один и тот же CSS проходит в одном месте
                    # и падает в другом.
                    if self._radius_kind(m.group(1)) == 'bad':
                        self.emit('CSS-RADIUS', rel, ln, line,
                                  f'border-radius: {m.group(1).strip()} — правило 4 требует 0 '
                                  f'(идеальный круг записывается ровно как `50%`)')
                if re.search(r'--radius\s*:(?!\s*0(?:px|rem|%)?\s*[;}])', line):
                    self.emit('CSS-RADIUS', rel, ln, line, '--radius ≠ 0 (правило 4)')
                if re.search(r'\b(linear|radial|conic|repeating-\w+)-gradient\s*\(', line):
                    self.emit('CSS-GRADIENT', rel, ln, line, 'градиент запрещён (правило 4)')
                for m in re.finditer(r'\b(box-shadow|text-shadow)\s*:\s*([^;{}]+)', line):
                    val = m.group(2).strip()
                    # `0 0 0 …` — это кольцо фокуса R-03, а не тень: у него нет
                    # ни смещения, ни размытия. Всё остальное — тень.
                    if not re.match(r'^(none|0\s+0\s+0(\s|$))', val):
                        self.emit('CSS-SHADOW', rel, ln, line,
                                  f'{m.group(1)}: {val[:40]} — тени запрещены (правило 4)')
                for m in re.finditer(r'(?<![-\w])(' + SPACING + r')\s*:\s*([^;{}]+)', line):
                    for v in re.findall(r'(-?\d+(?:\.\d+)?)px', m.group(2)):
                        if abs(float(v)) not in SCALE:
                            self.emit('CSS-SPACING', rel, ln, line,
                                      f'{m.group(1)}: {v}px вне шкалы отступов '
                                      f'4/8/12/16/24/32/48/64 (правило 2, LAYOUT-001)')
        if not found_any:
            self.fail('CSS-COLOR', 'css', '[вакуум] не найдено ни одного источника CSS')

    # -- 1b. Контраст: числа документов против формулы WCAG -------------------
    def check_contrast(self):
        # реестр палитры обязан совпадать с tokens.css
        css = self.read('design-system/tokens.css') or ''
        decls = dict(re.findall(r'(--[\w-]+)\s*:\s*([^;]+);',
                                re.sub(r'/\*.*?\*/', '', css, flags=re.S)))
        for tok, key in CLR_TOKEN.items():
            got = (decls.get(tok) or '').strip().upper()
            if got != CLR[key].upper():
                self.fail('CONTRAST', 'tokens.css',
                          f'{tok} = {got or "не объявлен"}, реестр контраста ожидает '
                          f'{CLR[key]} — реестр и токены разошлись')

        rx_ratio = re.compile(r'(?<![\d,.])(\d{1,2})(?:[.,](\d{1,2}))?\s*:\s*1(?![\d])')
        # НОРМАТИВНОЕ НЕРАВЕНСТВО ≠ ИЗМЕРЕНИЕ. Прежняя редакция выбрасывала из
        # разбора ЛЮБОЕ `3:1`, `4,5:1`, `7:1`, если на строке стояло слово о
        # пороге, — и создавала этим ровно ту слепоту, за которую партию
        # эскалировали в Batch 1: исключение ПО ЗНАЧЕНИЮ вместо разбора по
        # структуре. Аудитор показал цену: ложное измерение accent/canvas,
        # объявленное «ровно 3:1, проходит», не доходило до формулы вовсе,
        # тогда как соседнее `3,01:1` ловилось. Три мутации T01–T03.
        #
        # Теперь различие структурное и по месту в строке: числом ПОРОГА
        # считается только величина, у которой непосредственно перед ней стоит
        # знак сравнения (`≥ 4,5:1`, `>= 3:1`, `не проходит 4,5:1`). Всё
        # остальное — измерение, и оно ВСЕГДА пересчитывается формулой,
        # каким бы круглым ни было.
        # Маркер порога стоит ПЕРЕД числом («ниже 3:1», «не проходит 4,5:1»),
        # маркер прохождения — ПОСЛЕ («3:1, проходит R-01»). Разница в позиции
        # и есть разница между нормативом и измерением: именно так выглядели
        # мутации T01–T03, где слово стояло после числа.
        rx_thresh_at = re.compile(
            r'(?:≥|≤|>=|<=|больше|меньше|ниже|выше|минимум|максимум|порог\w*|'
            r'(?:не\s*[*_]*\s*)?проход\w*|требуе\w*|гейт\w*|gate|'
            r'достига\w*|обязан\w*)'
            r'[\s*_`:,—–-]*$', re.I)

        def claims_on(line):
            """Измерения строки. Порог опознаётся по знаку ПЕРЕД числом."""
            out = []
            for m in rx_ratio.finditer(line):
                if rx_thresh_at.search(line[:m.start()]):
                    continue          # нормативное неравенство, не измерение
                whole, frac = m.group(1), m.group(2)
                val = float(f'{whole}.{frac}') if frac else float(whole)
                dec = len(frac) if frac else 0
                out.append((m.group(0), val, dec))
            return out

        def matches(val, dec, pairs):
            """Совпадает ли записанное число с контрастом хотя бы одной пары."""
            for fg, bg in pairs:
                if abs(round(contrast(fg, bg), dec) - val) < 10 ** (-dec) / 2 + 1e-9:
                    return True
            return False

        # Разрешение цветов, названных прямо на строке: hex, `--токен`,
        # каноническое имя раздела 13 (`text.muted`, `surface.selected`).
        def resolve_tok(name, depth=0):
            v = (decls.get(name) or '').strip()
            if not v or depth > 8:
                return None
            r = re.fullmatch(r'var\((--[\w-]+)\)', v)
            return resolve_tok(r.group(1), depth + 1) if r else v

        def colors_on(line):
            out = []
            for h in re.findall(r'#[0-9A-Fa-f]{6}\b|#[0-9A-Fa-f]{3}\b', line):
                out.append(h.upper())
            for t in re.findall(r'--[\w-]+', line):
                v = resolve_tok(t)
                if v and re.fullmatch(r'#[0-9A-Fa-f]{3,8}', v):
                    out.append(v.upper())
            for d in re.findall(r'\b([a-zA-Z]+(?:\.[a-zA-Z0-9]+)+)\b', line):
                v = resolve_tok('--color-' + d.replace('.', '-'))
                if v and re.fullmatch(r'#[0-9A-Fa-f]{3,8}', v):
                    out.append(v.upper())
            # «голые» имена токенов в прозе: `text-muted`, `surface-selected`
            for d in re.findall(r'\b([a-z]+(?:-[a-z0-9]+)+)\b', line):
                for cand in ('--color-' + d, '--' + d):
                    v = resolve_tok(cand)
                    if v and re.fullmatch(r'#[0-9A-Fa-f]{3,8}', v):
                        out.append(v.upper())
            return out

        # Подложки по умолчанию: белая поверхность документа, канва, основной
        # текст и бренд-акцент. Это не «список исключений», а фактический
        # набор поверхностей системы: любое утверждение о контрасте в этих
        # документах говорит об одной из них.
        # Только фактические ПОВЕРХНОСТИ. Текст и акцент из набора убраны:
        # с ними пул давал столько величин, что перестановка двух
        # зарегистрированных чисел внутри файла проходила насквозь.
        IMPLICIT = [CLR['white'], CLR['canvas']]

        # Проверка каждого числа: пара выводится структурно из блока, и
        # только то, что структура дать не может, берётся из реестра
        # «(файл, число) → пара». Ни одного якоря по формулировке прозы.
        used_reg = set()
        for rel in CONTRAST_SWEEP_FILES:
            text = self.read(rel)
            if text is None:
                self.fail('CONTRAST-UNREG', rel, '[вакуум] файл отсутствует')
                continue
            rows = text.split('\n')
            for i, line in enumerate(rows, 1):
                claims = claims_on(line)
                if not claims:
                    continue
                # Блок = абзац смежных непустых строк. Исключение: строка
                # markdown-таблицы блокируется САМА СОБОЙ — иначе «блоком»
                # становится вся таблица, её пул цветов покрывает все величины
                # файла, и перестановка двух чисел между строками проходит.
                if line.lstrip().startswith('|'):
                    block = line
                else:
                    a = b = i - 1
                    while a > 0 and rows[a - 1].strip() and not rows[a - 1].lstrip().startswith('|'):
                        a -= 1
                    while b + 1 < len(rows) and rows[b + 1].strip() \
                            and not rows[b + 1].lstrip().startswith('|'):
                        b += 1
                    block = '\n'.join(rows[a:b + 1])
                cols = colors_on(block)
                pool = list(dict.fromkeys(cols + IMPLICIT))
                pairs = [(x, y) for n, x in enumerate(pool) for y in pool[n + 1:]]
                for raw, val, dec in claims:
                    # ИЗМЕРЕНИЕ БЕЗ ДЕСЯТИЧНЫХ ЗНАКОВ НЕ ЯВЛЯЕТСЯ ИЗМЕРЕНИЕМ.
                    # `3:1` покрывает всё от 2,50 до 3,49 — а порог R-01 лежит
                    # внутри этого интервала, поэтому фактические 2,60:1
                    # «совпадали» с заявленным 3:1 при округлении до целого.
                    # Именно так проходила мутация T01. Пороги здесь уже
                    # отсеяны по позиции знака сравнения.
                    if dec == 0:
                        self.emit('CONTRAST', rel, i, line,
                                  f'измерение контраста {raw} записано без десятичных знаков: '
                                  f'интервал {val - 0.5:.2f}…{val + 0.49:.2f} накрывает порог, '
                                  f'и утверждение непроверяемо. Система пишет измерения двумя '
                                  f'знаками ({fmt_ratio(contrast(CLR["accent"], CLR["white"]))}'
                                  f':1); одно целое — это порог, а не измерение')
                        continue
                    if matches(val, dec, pairs):
                        continue
                    key = (rel, raw.replace(' ', ''))
                    reg = CONTRAST_VALUE_PAIRS.get(key)
                    if reg:
                        used_reg.add(key)
                        if matches(val, dec, [(CLR[reg[0]], CLR[reg[1]])]):
                            continue
                        self.emit('CONTRAST', rel, i, line,
                                  f'записано {raw}, но зарегистрированная пара '
                                  f'{reg[0]}/{reg[1]} даёт по формуле WCAG '
                                  f'{fmt_ratio(contrast(CLR[reg[0]], CLR[reg[1]]), max(dec, 2))}')
                        continue
                    if not cols:
                        self.emit('CONTRAST-UNREG', rel, i, line,
                                  f'утверждение о контрасте {raw}: в блоке не назван ни один '
                                  f'цвет и пара не зарегистрирована — контраст без названной '
                                  f'пары не является утверждением (назовите оба цвета hex-ами '
                                  f'прямо в строке)')
                    else:
                        self.emit('CONTRAST', rel, i, line,
                                  f'записано {raw}; ни одна пара из цветов блока '
                                  f'({", ".join(sorted(set(cols)))}) и поверхностей системы '
                                  f'не даёт этой величины по формуле WCAG')
        for key in CONTRAST_VALUE_PAIRS:
            if key not in used_reg and (self.root / key[0]).exists():
                self.warn.append(f'CONTRAST: запись реестра пар {key} не сработала '
                                 f'(число исчезло или стало выводимым структурно)')

        # Акцентный текст допустим только на белом (3,10:1); на канве 2,60:1.
        acc_w = contrast(CLR['accent'], CLR['white'])
        acc_c = contrast(CLR['accent'], CLR['canvas'])
        if acc_w < 3.0:
            self.fail('A11Y-ACCENT-BG', 'tokens.css',
                      f'--color-text-display-accent на surface-default даёт {fmt_ratio(acc_w)}:1 < 3:1')
        if acc_c >= 3.0:
            self.fail('A11Y-ACCENT-BG', 'tokens.css',
                      f'расчёт не воспроизводит запрет: акцент на канве даёт {fmt_ratio(acc_c)}:1')
        # Фон документа. Правил с селектором `body` может быть несколько
        # (например отдельно шрифт и отдельно фон) — проверяются все.
        bgs = []
        for m in re.finditer(r'([^{}@]+)\{([^}]*)\}', re.sub(r'/\*.*?\*/', '', css, flags=re.S)):
            sels = [s.strip().split()[0].lower() for s in m.group(1).split(',') if s.strip()]
            if 'body' not in sels and 'html' not in sels:
                continue
            for b in re.finditer(r'background(?:-color)?\s*:\s*([^;]+)', m.group(2)):
                bgs.append(b.group(1).strip())
        if not bgs:
            self.fail('A11Y-ACCENT-BG', 'tokens.css',
                      'ни одно правило html/body не задаёт background — правило проекта 6 '
                      'требует белый фон явно, а акцентный текст читаем только на белом')
        for val in bgs:
            if 'var(--color-surface-default)' not in val:
                self.fail('A11Y-ACCENT-BG', 'tokens.css',
                          f'body {{ background: {val} }} — правило проекта 6 требует '
                          f'var(--color-surface-default); на канве герой-число DC-38 даёт '
                          f'{fmt_ratio(acc_c)}:1 вместо {fmt_ratio(acc_w)}:1')
        # ни одно правило не сажает акцентный текст на канву
        for m in re.finditer(r'\{([^}]*)\}', css):
            blk = m.group(1)
            if re.search(r'color\s*:\s*var\(--color-text-display-accent\)|color\s*:\s*#FD5E00', blk, re.I) \
               and re.search(r'background(?:-color)?\s*:\s*(var\(--color-surface-canvas\)|#E8ECE9)', blk, re.I):
                self.fail('A11Y-ACCENT-BG', 'tokens.css',
                          'акцентный текст на канве в одном правиле — запрещено (2,60:1)')

    # -- 1c. Гейты требований, объявленных закрытыми --------------------------
    def check_gates(self):
        css = self.read('design-system/tokens.css') or ''
        readme = self.read('design-system/README.md') or ''
        code = re.sub(r'/\*.*?\*/', '', css, flags=re.S)
        decls = dict(re.findall(r'(--[\w-]+)\s*:\s*([^;]+);', code))

        def resolve(name, depth=0):
            if depth > 10 or name not in decls:
                return None
            v = decls[name].strip()
            m = re.fullmatch(r'var\((--[\w-]+)\)', v)
            return resolve(m.group(1), depth + 1) if m else v.upper()

        # R-04 / XSC-07: цель нажатия 44×44 — величина и её применение
        if (decls.get('--size-hit-target-default') or '').strip() != '44px':
            self.fail('GATE-HIT', 'tokens.css',
                      f'--size-hit-target-default = {decls.get("--size-hit-target-default")}, '
                      f'R-04/XSC-07 требуют 44px')
        m = re.search(r'\.hit-target::before\s*\{([^}]*)\}', code)
        if not m:
            self.fail('GATE-HIT', 'tokens.css',
                      '[вакуум] правило .hit-target::before не найдено — расширение зоны нажатия отсутствует')
        else:
            blk = m.group(1)
            for prop in ('width', 'height'):
                v = re.search(prop + r'\s*:\s*([^;]+)', blk)
                if not v:
                    self.fail('GATE-HIT', 'tokens.css', f'.hit-target::before без {prop}')
                elif 'var(--size-hit-target-default)' not in v.group(1):
                    self.fail('GATE-HIT', 'tokens.css',
                              f'.hit-target::before {prop}: {v.group(1).strip()} — зона нажатия '
                              f'обязана читаться из --size-hit-target-default (R-04)')

        # R-15: business state / policy / domain не бывают токенами
        # R-15 проверяется БЕЛЫМ списком префиксов, а не чёрным списком имён:
        # чёрный список ловил только те business-состояния, которые уже успели
        # побывать в файле. Любое имя вне визуальных семейств раздела 13 —
        # нарушение до доказательства обратного.
        ALLOWED_PREFIXES = (
            '--primitive-', '--color-', '--type-', '--font-', '--paragraph-',
            '--space-', '--size-', '--border-', '--radius', '--layer-',
            '--motion-', '--stagger-', '--enter-', '--control-', '--row-',
            '--cell-', '--content-', '--measure-', '--gutter-', '--panel-',
        )
        BUSINESS = re.compile(r'output-profile|workflow|policy|domain|permission|'
                              r'data-quality|version-state|delivery-state|variant-role|'
                              r'coverage-state|option-state|accuracy-zone|mode-|'
                              r'regionalfaktor|profile', re.I)
        for name in decls:
            if BUSINESS.search(name) or not name.startswith(ALLOWED_PREFIXES):
                self.fail('GATE-R15', 'tokens.css',
                          f'{name}: не визуальный токен раздела 13 (R-15) — business state, '
                          f'policy и domain живут в data/policy-контрактах, не в tokens.css')
            if name.startswith('--component-'):
                self.fail('GATE-R25', 'tokens.css',
                          f'{name}: component-слой не реализуется без ADR (R-25/TOKEN-005)')

        # Правило 19/20: длительности зафиксированы, а не «примерно такие».
        # Читаются из :root — общий словарь перекрыт блоком reduced-motion,
        # где те же токены законно равны 0ms.
        root_blk = re.search(r':root\s*\{(.*?)\n\}', code, re.S)
        root_decls = dict(re.findall(r'(--[\w-]+)\s*:\s*([^;]+);',
                                     root_blk.group(1) if root_blk else ''))
        if not root_blk:
            self.fail('GATE-MOTION', 'tokens.css', '[вакуум] блок :root не найден')
        for tok, exp in (('--motion-value-change', '400ms'), ('--stagger-wave', '80ms'),
                         ('--motion-duration-fast', '120ms'), ('--stagger-row', '30ms')):
            got = (root_decls.get(tok) or '').strip()
            if got != exp:
                self.fail('GATE-MOTION', 'tokens.css',
                          f'{tok} = {got or "не объявлен"}, правило 19/20 требует {exp}')
        if (root_decls.get('--enter-shift') or '').strip() not in ('var(--space-2)', '8px'):
            self.fail('GATE-MOTION', 'tokens.css',
                      f'--enter-shift = {root_decls.get("--enter-shift")}, правило 20 требует подъём 8 px')

        # Шкала отступов — в самих токенах, не только в прозе README.
        for name, val in decls.items():
            if re.fullmatch(r'--space-\d+', name):
                px = re.fullmatch(r'\s*(\d+)px\s*', val)
                if not px or int(px.group(1)) not in (4, 8, 12, 16, 24, 32, 48, 64):
                    self.fail('GATE-SCALE', 'tokens.css',
                              f'{name} = {val.strip()} вне канонической шкалы 4/8/12/16/24/32/48/64')

        # Правило 7: числа — табличные цифры и вправо.
        num = re.search(r'\.numeric\s*\{([^}]*)\}', code)
        if not num:
            self.fail('GATE-NUMERIC', 'tokens.css', '[вакуум] правило .numeric не найдено (правило 7)')
        else:
            if 'font-feature-settings' not in num.group(1) or 'font-numeric' not in num.group(1):
                self.fail('GATE-NUMERIC', 'tokens.css',
                          '.numeric без табличных цифр (tnum) — правило 7')
            if not re.search(r'text-align\s*:\s*right', num.group(1)):
                self.fail('GATE-NUMERIC', 'tokens.css', '.numeric без выравнивания вправо — правило 7')

        # Слои: порядок обязан быть строго возрастающим по назначению.
        order = ['--layer-header', '--layer-popover', '--layer-tooltip',
                 '--layer-dialog-backdrop', '--layer-dialog', '--layer-toast']
        vals = []
        for nm in order:
            v = (decls.get(nm) or '').strip()
            if not re.fullmatch(r'\d+', v):
                self.fail('GATE-LAYER', 'tokens.css', f'{nm} не объявлен числом (найдено {v!r})')
                vals = None
                break
            vals.append(int(v))
        if vals and any(a >= b for a, b in zip(vals, vals[1:])):
            self.fail('GATE-LAYER', 'tokens.css',
                      f'порядок слоёв не строго возрастающий: {dict(zip(order, vals))} — '
                      f'коллизия перекрытий (TOKEN-005)')

        # R-03: двухслойный индикатор фокуса — толщина зафиксирована.
        for tok, exp in (('--border-width-focus', '2px'), ('--border-width-strong', '2px'),
                         ('--border-width-default', '1px')):
            got = (decls.get(tok) or '').strip()
            if got != exp:
                self.fail('R-03', 'tokens.css', f'{tok} = {got or "не объявлен"}, требуется {exp}')

        # Точные визуальные высоты контролов (README §1.3) и длительности.
        for tok, exp in (('--size-control-visual-sm', '32px'),
                         ('--size-control-visual-md', '40px'),
                         ('--size-control-visual-lg', '48px'),
                         ('--motion-duration-base', '200ms'),
                         ('--motion-duration-slow', '240ms')):
            got = (root_decls.get(tok) or '').strip()
            if got != exp:
                self.fail('GATE-DENSITY' if tok.startswith('--size') else 'GATE-MOTION',
                          'tokens.css', f'{tok} = {got or "не объявлен"}, требуется {exp}')

        # Кросс-сверка ширины правой панели: токен против прозы README §1.2.
        # SIDEBAR 01 (backlog eda1e221) ADR revision: the token may now be a
        # responsive `clamp(min, base + slope*vw, max)` instead of a bare
        # px integer — README's "520 px" names the clamp's UPPER bound
        # (unchanged since TASK-15), so a clamp() token is compared against
        # its own third (max) argument rather than requiring string equality
        # with the whole declaration.
        rp = re.search(r'правая панель S3 — (\d+) px', readme)
        if not rp:
            self.fail('GATE-DENSITY', 'README', '[вакуум] README §1.2 не называет ширину правой панели')
        else:
            got = (root_decls.get('--panel-right-width') or '').strip()
            clamp_m = re.fullmatch(
                r'clamp\(\s*[\d.]+px\s*,\s*[^,]+,\s*(\d+)px\s*\)', got)
            upper = (clamp_m.group(1) + 'px') if clamp_m else got
            if upper != rp.group(1) + 'px':
                self.fail('GATE-DENSITY', 'tokens.css',
                          f'--panel-right-width = {got} (верхняя граница {upper}), '
                          f'README §1.2 называет {rp.group(1)} px')

        # R-01: бренд-акцент существует ровно одним значением.
        if resolve('--color-brand-accent') != '#FD5E00':
            self.fail('R-01', 'tokens.css',
                      f'--color-brand-accent = {resolve("--color-brand-accent")}; бренд-оранжевый '
                      f'#FD5E00 существует только здесь и в text-display-accent (R-01)')
        if resolve('--color-text-display-accent') != '#FD5E00':
            self.fail('R-01', 'tokens.css',
                      f'--color-text-display-accent = {resolve("--color-text-display-accent")}, '
                      f'требуется #FD5E00 (R-01, DC-38)')

        # R-24: применяемый вес body — Regular (решение PO, CONFLICT-C).
        wb = (decls.get('--font-weight-body') or '').strip()
        if wb not in ('var(--font-weight-regular)', '400'):
            self.fail('R-24', 'tokens.css',
                      f'--font-weight-body = {wb or "не объявлен"}; применяемый вес body обязан '
                      f'быть Regular (R-24, решение PO CONFLICT-C)')

        # DENSITY-007: точные минимумы строк
        root = re.search(r':root\s*\{(.*?)\n\}', code, re.S)
        comp = re.search(r'\.density-compact\s*\{([^}]*)\}', code)
        for what, blk, exp in (('Komfortabel (:root)', root, '52px'),
                               ('Kompakt (.density-compact)', comp, '44px')):
            if not blk:
                self.fail('GATE-DENSITY', 'tokens.css', f'[вакуум] блок {what} не найден')
                continue
            for tok in ('--row-height-financial', '--row-height'):
                v = re.search(re.escape(tok) + r'\s*:\s*([^;]+)', blk.group(1))
                if not v:
                    self.fail('GATE-DENSITY', 'tokens.css', f'{what}: {tok} не задан')
                elif v.group(1).strip() != exp:
                    self.fail('GATE-DENSITY', 'tokens.css',
                              f'{what}: {tok} = {v.group(1).strip()}, DENSITY-007 требует {exp}')

        # R-21: prefers-reduced-motion гасит движение
        rm = re.search(r'@media\s*\(\s*prefers-reduced-motion\s*:\s*reduce\s*\)\s*\{(.*?)\n\}\s*\n',
                       css, re.S)
        if not rm:
            self.fail('GATE-MOTION', 'tokens.css',
                      '[вакуум] @media (prefers-reduced-motion: reduce) отсутствует (R-21, правило 21)')
        else:
            zeroed = set(re.findall(r'(--[\w-]+)\s*:\s*0m?s', rm.group(1)))
            for need in ('--motion-duration-fast', '--motion-duration-base',
                         '--motion-duration-slow', '--motion-value-change',
                         '--motion-emphasis', '--stagger-row', '--stagger-wave'):
                if need in decls and need not in zeroed:
                    self.fail('GATE-MOTION', 'tokens.css',
                              f'{need} не обнуляется при prefers-reduced-motion (R-21)')

        # §1.8: три обязательных правила подключения шрифта
        fam = {}
        for m in re.finditer(r'([^{}@]+)\{([^}]*)\}', code):
            sel, blk = m.group(1).strip(), m.group(2)
            if re.search(r'(?<![-\w])font-family\s*:', blk):
                for part in re.split(r',', sel):
                    fam[part.strip().split()[0].lower() if part.strip() else ''] = True
        for need in ('html', 'body'):
            if need not in fam:
                self.fail('GATE-FONT', 'tokens.css',
                          f'font-family не объявлен на `{need}` (README §1.8 правило 1: внешний reset '
                          f'на body перебьёт наследование от html)')
        for need in ('input', 'select', 'textarea', 'button', 'kbd'):
            if need not in fam:
                self.fail('GATE-FONT', 'tokens.css',
                          f'font-family не объявлен на `{need}` — элементы форм шрифт не наследуют (§1.8)')
        faces = re.findall(r'@font-face\s*\{([^}]*)\}', code)
        if not faces:
            self.fail('GATE-FONT', 'tokens.css', '[вакуум] ни одного @font-face')
        for blk in faces:
            for u in re.findall(r'url\(\s*([^)]*)\)', blk):
                if not re.match(r'''^\s*['"]''', u):
                    self.fail('GATE-FONT', 'tokens.css',
                              f'url({u.strip()[:40]}) без кавычек (§1.8 правило 2)')
            d = re.search(r'font-display\s*:\s*([\w-]+)', blk)
            if not d:
                self.fail('GATE-FONT', 'tokens.css', '@font-face без font-display (§1.8 правило 3)')
            elif d.group(1).strip() != 'block':
                self.fail('GATE-FONT', 'tokens.css',
                          f'font-display: {d.group(1)} — §1.8 правило 3 требует block')

    # -- 1d. R-24 в телах компонентных описаний -------------------------------
    def check_r24_prose(self):
        # `(44/32 px)` — это высоты строк, не типографика: пара с единицей px
        # к матрице R-24 отношения не имеет.
        rx = re.compile(r'(?<![\d/])(\d{2})\s*/\s*(\d{2})(?!\d)(?!\s*(?:px|%|м|m))'
                        r'(?:\s*\**\s*(Bold|Medium|Regular))?')
        for rel in ('design-system/README.md', 'design-system/components-core.md'):
            text = self.read(rel)
            if text is None:
                self.fail('R-24', rel, '[вакуум] файл отсутствует')
                continue
            for i, line in enumerate(text.split('\n'), 1):
                for m in rx.finditer(line):
                    size, lh = int(m.group(1)), int(m.group(2))
                    weight = m.group(3)
                    prefix = line[max(0, m.start() - 34):m.start()].lower()
                    role, best = None, -1
                    for pat, name in R24_ROLE_KEYS:
                        for k in re.finditer(pat, prefix):
                            if k.end() > best:
                                best, role = k.end(), name
                    if role:
                        es, el = R24_EXACT[role]
                        if (size, lh) != (es, el):
                            self.emit('R-24', rel, i, line,
                                      f'роль «{role}» набрана {size}/{lh}, R-24 требует {es}/{el}')
                        ew = R24_WORD.get(R24_WEIGHTS.get(f'--type-{role}-weight')
                                          or R24_WEIGHTS.get('--type-heading-weight'))
                        if weight and role in R24_EXACT and f'--type-{role}-weight' in R24_WEIGHTS \
                           and weight != ew:
                            self.emit('R-24', rel, i, line,
                                      f'роль «{role}» набрана {weight}, R-24 требует {ew}')
                    else:
                        if size not in R24_GENERIC:
                            self.emit('R-24', rel, i, line,
                                      f'кегль {size}px вне шкалы R-24')
                        elif lh not in R24_GENERIC[size]:
                            self.emit('R-24', rel, i, line,
                                      f'пара {size}/{lh} вне матрицы R-24')

    # -- 1e. Единицы, NBSP, площади, даты, полный label -----------------------
    def check_units(self):
        SEP = {' ': 'U+0020 (обычный пробел)',
               ' ': 'U+00A0 (неразрывный)',
               ' ': 'U+202F (узкий неразрывный)',
               ' ': 'U+2009 (узкий, разрывный)'}
        REQUIRED = ' '
        nbsp_rx = re.compile(r'(\d)([    ])(€|%|m²|m2|Monate|Wochen|WE)(?![\w])')
        cyr_rx = re.compile(r'[мМ]²|[мМ]2(?![\w])')
        date_hyphen = re.compile(r'(?<![\d-])\d{2}-\d{2}-\d{4}(?![\d-])')
        date_short = re.compile(r'(?<![\d.])\d{2}\.\d{2}\.\d{2}(?!\d)')
        area_rx = re.compile(
            r'€\s*/\s*m²\s*[`*]*\s*(WFL|NUF|BGF)(?![\w-])'
            r'(?!\s*[`*]*\s*(?:nach\s+WoFlV|nach\s+DIN\s*277|oberirdisch|unterirdisch|'
            r'R\s*\+\s*S|\(R\)|UG\b|R\b))')
        # `Anteil an Zwischensumme` — самостоятельный корректный label
        # (COSTTABLE-002, динамический заголовок процентной колонки).
        # Полный label требуется только там, где слово стоит ПОДПИСЬЮ ИТОГА,
        # то есть в строке с денежной величиной.
        zwi_rx = re.compile(r'(?<!Anteil an )Zwischensumme(?!\s+der\s+kalkulierten\s+Positionen)')
        money_rx = re.compile(r'\d[\d.\u00a0\u202f]{2,}|€')
        seen_units = False
        # Код приложения проверяется теми же копирайт-классами, что документы.
        # Пока обходились только `*.md`/`*.json`, эти правила были слепы к
        # ЕДИНСТВЕННОМУ месту, где текст доходит до клиента, — к разметке.
        # Дыра доказана предметно: пять усечённых «Zwischensumme» жили в
        # `src/` незамеченными и всплыли лишь тогда, когда две из них
        # переписали в проверяемый markdown. Правило, не покрывающее
        # носитель, охраняет описание вместо объекта.
        for glob in ('*.md', '*.json', '*.tsx', '*.ts'):
            for rel, text in self.files(glob):
                if rel.startswith('tools/'):
                    continue
                # Тесты цитируют нарушения намеренно: тест на усечённую метку
                # обязан её содержать. Исключение по конструкции, как у
                # реестра требований, а не по каталогу удобства.
                if '__tests__' in rel:
                    continue
                # Датированный вердикт второго инструмента (`codex-*-ГГММДД.md`)
                # — свидетельство, а не проектная копия: его формулировки
                # координатор не контролирует, а править задним числом значило
                # бы подделывать протокол проверки. PROTOCOL.md §2a объявляет
                # это исключение по ФОРМЕ ИМЕНИ; до 06.08 объявление жило
                # только в протоколе, а инструмент его не знал — правило и
                # его реализация разошлись ровно так же, как расходятся два
                # артефакта об одной сущности. Исключение узкое: каталог
                # `verdicts/` целиком НЕ исключается, поэтому задания,
                # протокол и поставки содержимого проверяются полностью.
                if RX_CODEX_VERDICT.match(rel.rsplit('/', 1)[-1]):
                    continue
                # В коде проверяется ТЕКСТ ПРОДУКТА, а не рассуждения о нём:
                # комментарии гасятся пробелами (номера строк сохраняются).
                # Без этого правило оказывается шире долга — оно ловило бы
                # «завышенное на 160 €» в объяснении дефекта, то есть прозу,
                # которая клиенту никогда не показывается.
                if rel.endswith(('.ts', '.tsx')):
                    text = _blank_code_comments(text)
                seen_units = True
                # NBSP агрегируется по (файл, фактический разделитель): в
                # документе их сотни, построчный реестр превратился бы в шум.
                # Сообщение НАЗЫВАЕТ фактический символ — противоречие
                # CLAUDE.md §7 / README §1.9 (предписан U+202F) против
                # фактических U+0020/U+00A0 не решается инструментом, оно
                # зарегистрировано как открытое (KNOWN_OPEN_FILE).
                # Псевдокод формул (fenced-блок) — определение ставки, а не
                # отображаемая клиенту метрика: знаменатель там появляется при
                # применении к площади. AREA-SCOPE внутрь блоков не заходит;
                # остальные классы заходят (ASCII-макеты — это UI-копия).
                fenced, inside = set(), False
                for i, line in enumerate(text.split('\n'), 1):
                    if line.lstrip().startswith('```'):
                        inside = not inside
                        fenced.add(i)
                    elif inside:
                        fenced.add(i)
                agg = {}
                for i, line in enumerate(text.split('\n'), 1):
                    for m in nbsp_rx.finditer(line):
                        ch = m.group(2)
                        if ch == REQUIRED:
                            continue
                        agg.setdefault(ch, []).append((i, line, m.group(0)))
                for ch, rows in sorted(agg.items()):
                    i, line, sample = rows[0]
                    where = ', '.join(str(r[0]) for r in rows[:6]) + ('…' if len(rows) > 6 else '')
                    self.emit('NBSP', rel, i, line,
                              f'{len(rows)} мест: число и единица разделены {SEP[ch]}, '
                              f'CLAUDE.md §7 и README §1.9 предписывают U+202F (узкий '
                              f'неразрывный). Пример «{sample}». Строки: {where}. '
                              f'ПРОТИВОРЕЧИЕ ПРАВИЛА И ФАКТА НЕ РАЗРЕШЕНО — решение владельца')
                for i, line in enumerate(text.split('\n'), 1):
                    for m in cyr_rx.finditer(line):
                        self.emit('CYRILLIC-UNIT', rel, i, line,
                                  f'кириллическая «{m.group(0)}» в латинской единице — читается '
                                  f'как единица, не является ею')
                    for m in date_hyphen.finditer(line):
                        self.emit('DATE-FORMAT', rel, i, line,
                                  f'дата «{m.group(0)}» дефисами (анти-паттерн XSC-09); '
                                  f'немецкий формат — 14.05.2027, машинное значение — ISO')
                    for m in date_short.finditer(line):
                        self.emit('DATE-FORMAT', rel, i, line,
                                  f'двузначный год в «{m.group(0)}» (XSC-09)')
                    for m in (() if i in fenced else area_rx.finditer(line)):
                        self.emit('AREA-SCOPE', rel, i, line,
                                  f'«€/m² {m.group(1)}» без нормативного типа и scope — требуется '
                                  f'`nach WoFlV` / `nach DIN 277` / `oberirdisch` / `R+S` '
                                  f'(правило 33/39, R-11)')
                    for m in (zwi_rx.finditer(line) if money_rx.search(line) else ()):
                        self.emit('R-18-LABEL', rel, i, line,
                                  'усечённое «Zwischensumme»; R-18/COPY-008 требуют полный label '
                                  '«Zwischensumme der kalkulierten Positionen»')
        if not seen_units:
            self.fail('NBSP', 'repo', '[вакуум] не найдено ни одного документа для проверки единиц')

    # -- 2. README: копирайт и роли -------------------------------------------
    def check_readme(self):
        rel = 'design-system/README.md'
        readme = self.read(rel) or ''
        # пред-R-24 пары
        for bad in ('14/19', '16/21'):
            if bad in readme:
                self.fail('R-24', rel, f'пред-R-24 пара {bad} осталась в тексте')
        # числовые герои не набираются ролью heading.1
        self.scan('R-24', rel, readme, r'(€/m²|Bauzeit|Gesamt)[^|\n]*\|\s*48/56',
                  'число набрано ролью heading.1 (48/56); для чисел только 64/68 и 48/52')
        # шкала отступов
        m = re.search(r'База \*\*8 px\*\*[^\n]*?((?:\d+\s*·\s*)+\d+)', readme)
        if m:
            vals = {v.strip() for v in re.split(r'[·,]', m.group(1)) if v.strip()}
            for v in sorted(vals - {'4', '8', '12', '16', '24', '32', '48', '64'}):
                self.fail('LAYOUT-001', rel, f'значение {v} px вне канонической шкалы')
        else:
            self.fail('LAYOUT-001', rel, '[вакуум] строка шкалы отступов не найдена')
        # LAYOUT-003
        for src_rel in (rel, 'docs/product/screen-map.md'):
            src = self.read(src_rel) or ''
            if '1600 px' in src or '1600px' in src:
                self.fail('LAYOUT-003', src_rel, 'осталось 1600 px, требуется 1200 px')
        # положительное утверждение: величина названа, а не только не-запрещена
        if not re.search(r'Контент ограничен \*\*1200 px\*\*', readme):
            self.fail('LAYOUT-003', rel,
                      'README §1.2 не называет ограничение контента 1200 px (LAYOUT-003)')
        # DC-38: строка героя №1 обязана быть набрана 64/68 — проверяется
        # сама строка, а не наличие подстроки где-нибудь в файле.
        hero = [l for l in readme.split('\n')
                if l.lstrip().startswith('|') and 'Gesamt netto' in l
                and re.search(r'\d{2}\s*/\s*\d{2}', l)]
        if not hero:
            self.fail('R-24', rel, '[вакуум] строка героя DC-38 «Gesamt netto … NN/NN» не найдена')
        for l in hero:
            pair = re.search(r'(\d{2})\s*/\s*(\d{2})', l)
            if (int(pair.group(1)), int(pair.group(2))) != (64, 68):
                self.fail('R-24', rel,
                          f'DC-38: герой №1 набран {pair.group(1)}/{pair.group(2)}, правило 31 '
                          f'и R-24 требуют 64/68 (единственный оранжевый, display.numeric.desktop)')
        # R-24-CAPTION: caption для запрещённых ролей (RU+EN словарь ролей,
        # исключения — только точные строки из ALLOW)
        cap = re.compile(r'(caption|подпись)\s*1?2\s*(px)?\s*(Regular|/16)', re.I)
        ban = re.compile(r'(source|источник|scope|status|статус|blocker|блокер|конфликт|'
                         r'происхожден|workflow|знаменател|допущени|исключени|ошибк|error|'
                         r'assumption|exclusion)', re.I)
        for i, line in enumerate(readme.split('\n'), 1):
            if cap.search(line) and ban.search(line):
                self.emit('R-24-CAPTION', rel, i, line,
                          f'caption для запрещённой роли — {line.strip()[:70]}')
        # R-01-PROSE: оранжевый как семантика в прозе.
        # Слово «orange» больше не обязательно: обход шёл через имя токена
        # (`--color-brand-accent`), немецкое «Aktionsfarbe» и голый hex.
        trig = re.compile(r'(оранжев|(?<![-\w])orange(?![-\w])|brand-accent|brand\.accent|'
                          r'Aktionsfarbe|#FD5E00|orange-500)', re.I)
        role = re.compile(r'(selected|selection|выделен|статус|status|warning|фокус|focus|'
                          r'checked|чек|бар\b|действ|action)', re.I)
        for i, line in enumerate(readme.split('\n'), 1):
            if trig.search(line) and role.search(line):
                self.emit('R-01-PROSE', rel, i, line,
                          f'оранжевый рядом с семантической ролью — {line.strip()[:70]}')
        # R-20: percentage readiness. Слово «кольцо» перестало быть условием —
        # запрещён сам процент готовности, каким бы виджетом он ни рисовался.
        for src_rel in (rel, 'docs/product/screen-map.md', 'docs/product/decisions.md',
                        'docs/product/guidance-system.md', 'docs/product/product-brief.md',
                        'design-system/components-core.md', 'CLAUDE.md'):
            src = self.read(src_rel) or ''
            self.scan('R-20', src_rel, src, r'(Bereitschafts-Ring|кольцо готовности)',
                      'готовность как кольцо/процент запрещена (R-20/READY-001)')
            for i, line in enumerate(src.split('\n'), 1):
                if re.search(r'(Bereitschaft|готовност)', line, re.I) and \
                   re.search(r'\d{1,3}\s*[  ]?%', line):
                    self.emit('R-20', src_rel, i, line,
                              'процент готовности (READY-001/R-20): score запрещён независимо '
                              f'от виджета — {line.strip()[:70]}')
        # R-09: фиксированный e-mail-флоу присутствует, одноклик отсутствует
        if 'Compose → Preflight → Confirm & Send → Delivery status' not in readme:
            self.fail('R-09', rel, 'DC-41 не описывает фиксированный флоу '
                      '«Compose → Preflight → Confirm & Send → Delivery status» (EMAIL-001)')
        self.scan('R-09', rel, readme, r'«Senden»\s*→\s*`offer\.emailed`',
                  'одноклик-отправка без preflight (R-09/EMAIL-001)')
        # CALC-014: label сессионной дельты. Проверяются ВСЕ места, где label
        # приводится, а не «встречается ли он в файле»: у DC-12 их два —
        # видимая подпись и доступное имя, — и верная копия во втором месте
        # закрывала порчу первого (класс 7 вердикта Codex).
        want_label = 'Preisänderung gegenüber'
        base_rx = re.compile(r'(?:Preis|Gesamt|Kosten|Wert)änderung\s+gegenüber')
        spots = [(i, l) for i, l in enumerate(readme.split('\n'), 1) if base_rx.search(l)]
        if not spots:
            self.fail('CALC-014', rel, '[вакуум] DC-12 не задаёт label '
                                       '«Preisänderung gegenüber <Vergleichsbasis>» — '
                                       'сессионная дельта без baseline не проверяется')
        for i, l in spots:
            if want_label not in l:
                self.emit('CALC-014', rel, i, l,
                          f'label сессионной дельты записан не канонически: CALC-014 требует '
                          f'«{want_label} <Vergleichsbasis>». Каждое место, где label '
                          f'приводится, обязано совпадать — видимая подпись и доступное имя '
                          f'не бывают разными')
        self.scan('CALC-014', rel, readme, r'Änderungen\s*·\s*\+',
                  'сессионная дельта без baseline/расшифровки (CALC-014)')

    # -- 2b. Контракты README: матрица против тел, семь осей, причины ---------
    RX_CONTRACT_HEAD = re.compile(r'^###\s+(?:(DC-\d+)\s*·\s*)?`([A-Za-z][A-Za-z0-9]*)`')
    RX_AXIS_DECL = re.compile(r'`(' + '|'.join(DATA_AXES) + r')`\s*(?:—|–|-)\s')
    RX_NAR = re.compile(r'notApplicableReason:\s*(.*?)(?=`[a-zA-Z]+`\s*(?:—|–|/)|\Z)', re.S)
    # Тавтология: причина повторяет вывод («неприменимо», «не применяется»,
    # «не предполагает данного состояния») вместо основания.
    RX_TAUTOLOGY = re.compile(
        r'не\s*применим|неприменим|не\s+предполагает|не\s+поддерживает\s+это|'
        r'отсутствует\s+как\s+состояние|данного\s+состояния\s+нет|'
        r'этого\s+состояния\s+не\s+бывает', re.I)
    # НАЗВАННЫЙ ОБЪЕКТ, а не связка. Связка («поскольку», «потому что») сама
    # причиной не является: аудитор построил тавтологию именно со связкой —
    # «неприменимо, поскольку компонент не предполагает данного состояния».
    # Причина обязана назвать ОБЪЕКТ: где состояние живёт вместо этого, какой
    # компонент его объявляет, каким утверждением оно стало бы.
    RX_CAUSAL = re.compile(
        r'DC-\d+|R-\d+|`[A-Za-z][\w.-]*`|принадлежит|живёт|объявля\w+\s+там|'
        r'прочит\w+\s+как|было\s+бы|стал\w+\s+бы|означал\w+\s+бы|'
        r'вместо\s+(?:неё|него|них|этого)\s+\w+', re.I)

    def _contracts(self, readme, rows):
        """[(dc, имя, первая строка, тело)] для каждого контракта §2.6.

        Границы берутся структурно: от `### 2.6` до `### 2.7`, контракт — от
        своего заголовка до следующего. Отсутствие границ — вакуум.
        """
        try:
            a = next(i for i, l in enumerate(rows) if l.startswith('### 2.6'))
            b = next(i for i, l in enumerate(rows) if l.startswith('### 2.7'))
        except StopIteration:
            return None
        heads = []
        for i in range(a, b):
            m = self.RX_CONTRACT_HEAD.match(rows[i])
            if m:
                heads.append((i, m.group(1) or '', m.group(2)))
        heads.append((b, '', ''))
        out = []
        for k in range(len(heads) - 1):
            i, dc, name = heads[k]
            out.append((dc, name, i + 1, '\n'.join(rows[i:heads[k + 1][0]])))
        return out

    def _state_block(self, body, label):
        m = re.search(r'\*\*Состояния\s*—\s*' + label + r'[^*]*\*\*(.*?)(?=\n\*\*[А-ЯA-Z])',
                      body, re.S)
        return m.group(1) if m else None

    def check_readme_contracts(self):
        rel = 'design-system/README.md'
        readme = self.read(rel) or ''
        rows = readme.split('\n')
        contracts = self._contracts(readme, rows)
        if not contracts:
            self.fail('RM-AXES', rel, '[вакуум] раздел контрактов §2.6…§2.7 не найден — '
                                      'ни один контракт не проверяется')
            return
        if len(contracts) < 40:
            self.fail('RM-AXES', rel, f'[вакуум] в §2.6 распознано {len(contracts)} контрактов; '
                                      f'реестр §2.2 объявляет 45 доменных плюс два '
                                      f'документационных — парсер потерял границы')

        # --- матрица §2.4 как ДАННЫЕ, а не как проза -------------------------
        try:
            ms = next(i for i, l in enumerate(rows) if l.startswith('### 2.4'))
            me = next(i for i, l in enumerate(rows) if l.startswith('### 2.5'))
        except StopIteration:
            self.fail('RM-MATRIX', rel, '[вакуум] матрица §2.4 не найдена')
            return
        matrix, mat_line = {}, {}
        for i in range(ms, me):
            line = rows[i]
            if not line.startswith('|'):
                continue
            cells = [c.strip() for c in line.strip('|').split('|')]
            if len(cells) != len(DATA_AXES) + 1 or cells[1] not in ('●', '○'):
                continue
            m = re.match(r'^(?:(DC-\d+)\s+)?`([A-Za-z][A-Za-z0-9]*)`', cells[0])
            if not m:
                self.emit('RM-MATRIX', rel, i + 1, f'RM-MATRIX:row-{i}',
                          f'строка матрицы §2.4 не называет компонент распознаваемо: '
                          f'«{cells[0][:40]}»')
                continue
            key = (m.group(1) or '', m.group(2))
            if key in matrix:
                self.emit('RM-MATRIX', rel, i + 1, f'RM-MATRIX:dup-{key[1]}',
                          f'компонент {key[1]} встречается в матрице §2.4 дважды')
            matrix[key] = cells[1:]
            mat_line[key] = i + 1
        if len(matrix) < 40:
            self.fail('RM-MATRIX', rel, f'[вакуум] в матрице §2.4 распознано {len(matrix)} строк '
                                        f'— парсер потерял таблицу, сверка стала бы вакуумной')
            return

        bodies = {}
        for dc, name, ln, body in contracts:
            key = (dc, name)
            bodies[key] = (ln, body)
            blk = self._state_block(body, 'данные')
            if blk is None:
                self.emit('RM-AXES', rel, ln, f'RM-AXES:noblock-{dc or name}',
                          f'{dc or name} `{name}`: блок «Состояния — данные» отсутствует — '
                          f'компонент без пяти состояний плюс двух осей в прототип '
                          f'не попадает (правило проекта 30, STATE-001)')
                continue
            decl = {}
            for m in self.RX_AXIS_DECL.finditer(blk):
                decl.setdefault(m.group(1), m.start())
            for axis in DATA_AXES:
                if axis not in decl:
                    self.emit('RM-AXES', rel, ln, f'RM-AXES:{dc or name}.{axis}',
                              f'{dc or name} `{name}`: ось `{axis}` не объявлена в теле '
                              f'контракта. Семь осей — `{" · ".join(DATA_AXES)}` — '
                              f'обязательны каждая (правило проекта 30, STATE-001)')
            # сегменты: от объявления оси до объявления следующей
            order = sorted(decl.items(), key=lambda x: x[1])
            segs = {}
            for idx, (axis, pos) in enumerate(order):
                nxt = order[idx + 1][1] if idx + 1 < len(order) else len(blk)
                segs[axis] = blk[pos:nxt]
            # --- матрица против тела: каждая ячейка выводится, а не заявляется
            if key not in matrix:
                self.emit('RM-MATRIX', rel, ln, f'RM-MATRIX:missing-{dc or name}',
                          f'{dc or name} `{name}` имеет контракт, но отсутствует строкой '
                          f'в матрице §2.4 — индекс не покрывает источник')
            else:
                cells = matrix[key]
                for idx, axis in enumerate(DATA_AXES):
                    if axis not in segs:
                        continue
                    want = '○' if 'notApplicableReason' in segs[axis] else '●'
                    if cells[idx] != want:
                        self.emit('RM-MATRIX', rel, mat_line[key],
                                  f'RM-MATRIX:{dc or name}.{axis}',
                                  f'матрица §2.4 ставит {cells[idx]} для {dc or name} `{name}` '
                                  f'по оси `{axis}`, а тело контракта (строка {ln}) объявляет '
                                  f'{want}: {"причина неприменимости" if want == "○" else "живое состояние"}. '
                                  f'Сводная таблица, не сверяемая с источником, — заготовка '
                                  f'для расхождения (§2.3: «`○` действителен ровно настолько, '
                                  f'насколько в контракте стоит названная причина»)')
            # --- причина неприменимости несёт причину, а не слово ------------
            self._reasons(rel, dc or name, name, ln, segs.items(), 'данные', 12, 3)
            blk_i = self._state_block(body, 'взаимодействие')
            if blk_i is None:
                self.emit('RM-AXES', rel, ln, f'RM-AXES:nointeraction-{dc or name}',
                          f'{dc or name} `{name}`: блок «Состояния — взаимодействие» '
                          f'отсутствует — вторая ось STATE-001 не документирована')
            else:
                self._reasons(rel, dc or name, name, ln,
                              [('взаимодействие', blk_i)], 'взаимодействие', 10, 2)
            # RM-TRANSITION: граф переходов, а не только наличие имён (T22).
            # Прежде проверялось присутствие осей и совпадение ●/○; сам порядок
            # не разбирался, и `default → ready → loading` проходил насквозь.
            mt2 = re.search(r'\*\*Переходы[^*\n]{0,40}\*\*(.*?)(?=\n\*\*[А-ЯA-Z]|\Z)', body, re.S)
            if not mt2:
                self.emit('RM-TRANSITION', rel, ln, f'RM-TRANSITION:none-{dc or name}',
                          f'{dc or name} `{name}`: блок «Переходы» отсутствует — разрешённые '
                          f'переходы не объявлены, и любая реализация допустима')
                continue
            chains = re.findall(r'`([^`]*(?:→|->)[^`]*)`', mt2.group(1))
            if not chains:
                continue
            steps = re.split(r'\s*(?:→|->)\s*', chains[0])
            seq = [{w for w in re.split(r'[|\s]+', s.strip('` ')) if w in DATA_AXES}
                   for s in steps]
            pos = {}
            for idx, st in enumerate(seq):
                for w in st:
                    pos.setdefault(w, idx)
            if 'loading' in pos and 'ready' in pos and pos['loading'] > pos['ready']:
                self.emit('RM-TRANSITION', rel, ln, f'RM-TRANSITION:order-{dc or name}',
                          f'{dc or name} `{name}`: в цепочке «{chains[0][:60]}» `loading` '
                          f'стоит ПОСЛЕ `ready`. Готовое значение не уходит в загрузку само: '
                          f'обратный переход существует только через названную причину '
                          f'(изменение authoritative-входа → `stale → loading`, R-10, '
                          f'STALE-001), и она обязана быть в цепочке названа')
            if seq and seq[0] and not (seq[0] & {'default', 'empty', 'loading'}):
                self.emit('RM-TRANSITION', rel, ln, f'RM-TRANSITION:start-{dc or name}',
                          f'{dc or name} `{name}`: цепочка начинается с {sorted(seq[0])} — '
                          f'начальным состоянием может быть только `default`, `empty` '
                          f'или `loading`')

        for key, cells in sorted(matrix.items()):
            if key not in bodies:
                self.emit('RM-MATRIX', rel, mat_line[key], f'RM-MATRIX:orphan-{key[1]}',
                          f'матрица §2.4 объявляет состояния для {key[0] or key[1]} '
                          f'`{key[1]}`, у которого нет контракта в §2.6 — индекс утверждает '
                          f'о том, чего нет')

        # --- §2.3 обязана объявлять все семь осей поимённо -------------------
        # Собственная мутация: удаление `stale` из объявления прошло, потому что
        # семь осей были константой ИНСТРУМЕНТА, а не читались из документа.
        # Константа осталась (она нормативна), но документ обязан её называть:
        # правило, которого нет в тексте, восстанавливается первой же правкой.
        m23 = re.search(r'^###\s*2\.3(.*?)(?=^###\s|\Z)', readme, re.S | re.M)
        if not m23:
            self.fail('RM-AXES', rel, '[вакуум] раздел §2.3 «Пять состояний данных плюс две '
                                      'оси» не найден — общий контракт осей не объявлен')
        else:
            s23, ln23 = m23.group(1), readme[:m23.start()].count('\n') + 1
            # (а) таблица §2.3 — по строке на каждую ось, ровно один раз
            trows = re.findall(r'^\|\s*`([a-z]+)`\s*\|', s23, re.M)
            for axis in DATA_AXES:
                if trows.count(axis) != 1:
                    self.emit('RM-AXES', rel, ln23, f'RM-AXES:§2.3-table:{axis}',
                              f'таблица §2.3 содержит ось `{axis}` {trows.count(axis)} раз '
                              f'вместо одного: значение оси в доменных терминах объявляется '
                              f'здесь ровно однажды')
            # (б) объявление двух НЕЗАВИСИМЫХ осей обязано называть обе поимённо.
            # Присутствия имени где-нибудь в разделе недостаточно: собственная
            # мутация убрала `stale` из объявления, а строка таблицы осталась —
            # и проверка «есть в разделе» прошла насквозь.
            md = re.search(r'(?:независим\w+\s+ос\w+|дву[хм]\s+ос\w+)([^\n.]{0,120})', s23)
            if not md:
                self.fail('RM-AXES', rel, '[вакуум] §2.3 не содержит объявления двух '
                                          'независимых осей STATE-001 — состав семи осей '
                                          'не выводится')
            else:
                for axis in ('stale', 'permission'):
                    if f'`{axis}`' not in md.group(1):
                        self.emit('RM-AXES', rel, ln23, f'RM-AXES:§2.3-decl:{axis}',
                                  f'объявление независимых осей §2.3 не называет `{axis}`: '
                                  f'«{md.group(1).strip()[:60]}». Ось, исчезнувшая из '
                                  f'объявления, исчезнет и из следующего контракта — на этом '
                                  f'отклонили партию примитивов (STATE-001/003/008)')
            # (в) пять обязательных состояний правила проекта 30 названы группой
            mfive = re.search(r'пяти\s+обязательных\s+состояний[^\n]{0,80}?'
                              r'((?:`[a-z]+`\s*[·,]?\s*){3,})', s23)
            if mfive:
                named = set(re.findall(r'`([a-z]+)`', mfive.group(1)))
                for axis in ('loading', 'empty', 'partial', 'ready', 'error'):
                    if axis not in named:
                        self.emit('RM-AXES', rel, ln23, f'RM-AXES:§2.3-five:{axis}',
                                  f'перечень пяти обязательных состояний правила проекта 30 '
                                  f'не называет `{axis}`')

        # --- ведущая метрика уровня Gesamt: знаменатель совпадает с подписью -
        # Правило проекта 39: ведущая метрика комплекса в клиентских выдачах —
        # `€/m² BGF oberirdisch`. Подмена знаменателя на R+S складывает
        # надземную и подземную площадь под подписью «oberirdisch» (DATA-001).
        LEAD = '€/m² BGF oberirdisch'
        mg = re.search(r'[Нн]а\s+уровне\s+`?Gesamt`?[^\n]{0,80}?герой\s*№?\s*2\s*—\s*'
                       r'\*{0,2}`([^`]+)`', readme)
        if not mg:
            self.fail('RM-FIXTURE', rel, '[вакуум] README не называет ведущую метрику уровня '
                                         '`Gesamt` — правило проекта 39 не проверяется')
        elif mg.group(1).strip() != LEAD:
            self.emit('RM-FIXTURE', rel, readme[:mg.start()].count('\n') + 1,
                      f'RM-FIXTURE:lead-{mg.group(1).strip()}',
                      f'ведущая метрика уровня `Gesamt` названа `{mg.group(1).strip()}`, '
                      f'правило проекта 39 требует `{LEAD}`: знаменатель обязан совпадать '
                      f'с подписью, и складывать надземную с подземной под подписью '
                      f'«oberirdisch» запрещено (DATA-001, R-11)')

        # --- минимумы плотности §1.3 против DENSITY-007 ----------------------
        # Прозаические минимумы не сверялись ни с чем: 52 → 48 px проходило,
        # хотя DENSITY-007 объявлен закрытым и «не подлежит уменьшению».
        m13 = re.search(r'Строка\s+финансовых/табличных\s+данных\s*\|\s*\*\*≥\s*(\d+)\s*px\*\*'
                        r'\s*\|\s*\*\*≥\s*(\d+)\s*px\*\*', readme)
        if not m13:
            self.fail('GATE-DENSITY', rel, '[вакуум] строка минимумов плотности §1.3 '
                                           '(«Строка финансовых/табличных данных») не найдена — '
                                           'DENSITY-007 в прозе не проверяется')
        else:
            ln13 = readme[:m13.start()].count('\n') + 1
            for got, want, which in ((int(m13.group(1)), 52, 'Komfortabel'),
                                     (int(m13.group(2)), 44, 'Kompakt')):
                if got != want:
                    self.emit('GATE-DENSITY', rel, ln13, f'GATE-DENSITY:prose-{which}',
                              f'§1.3: минимум строки финансовых данных в плотности {which} '
                              f'записан {got} px, DENSITY-007 требует {want} px и «не '
                              f'подлежит уменьшению». Прежние высоты обеих плотностей лежали '
                              f'ниже нормы и были исправлены — ослабление возвращает дефект')

        # --- таблица мощностей §2.2 против фактического состава --------------
        # Раздел сам объявляет четыре множества и их мощности — именно та
        # форма, которую можно и обязано выводить. Собственная мутация
        # («47 доменных, из них 45» → 46/44 и удаление строки реестра) прошла
        # насквозь: числа не сверялись ни с чем.
        dc_nums = sorted({int(x) for x in re.findall(r'\bDC-(\d+)\b', readme)})
        reg_rows = [l for l in rows[
            next((i for i, l in enumerate(rows) if l.startswith('### 2.2')), 0):
            next((i for i, l in enumerate(rows) if l.startswith('### 2.3')), len(rows))]
            if re.match(r'^\|\s*(?:DC-\d+|—)\s*\|', l)]
        dc_contracts = [c for c in contracts if c[0]]
        facts = {
            'номера серии': (max(dc_nums) if dc_nums else 0),
            'контракты доменных': len(dc_contracts),
            'тела контрактов': len(contracts),
            'строки реестровой': len(reg_rows),
        }
        card_rx = (
            (r'номера\s+серии\s*`?DC-\*`?\s*\|\s*\*\*(\d+)\*\*', 'номера серии'),
            (r'контракты\s+доменных\s+компонентов\s*\|\s*\*\*(\d+)\*\*', 'контракты доменных'),
            (r'тела\s+контрактов[^|]*\|\s*\*\*(\d+)\*\*', 'тела контрактов'),
            (r'строки\s+реестровой\s+таблицы[^|]*\|\s*\*\*(\d+)\*\*', 'строки реестровой'),
        )
        seen_card = 0
        for pat, key in card_rx:
            m = re.search(pat, readme)
            if not m:
                continue
            seen_card += 1
            declared, ln = int(m.group(1)), readme[:m.start()].count('\n') + 1
            if declared != facts[key]:
                self.emit('RM-CARD', rel, ln, f'RM-CARD:{key}',
                          f'§2.2 объявляет мощность множества «{key}» = {declared}, '
                          f'фактически {facts[key]}. Раздел сам предупреждает, что четыре '
                          f'числа описывают четыре разных множества и не являются '
                          f'источником — тогда каждое обязано выводиться скриптом')
        if seen_card < len(card_rx):
            self.fail('RM-CARD', rel, f'[вакуум] таблица мощностей §2.2 распознана на '
                                      f'{seen_card} из {len(card_rx)} строк — числа компонентов '
                                      f'не сверяются с составом')
        # непрерывность серии DC-*: пропуск номера означает потерянный компонент
        if dc_nums:
            gaps = [n for n in range(1, max(dc_nums) + 1) if n not in dc_nums]
            if gaps:
                self.emit('RM-CARD', rel, 1, 'RM-CARD:gaps',
                          f'в серии `DC-*` пропущены номера {gaps}: реестр §2.2 объявляет '
                          f'«DC-1…DC-{max(dc_nums)} без пропусков»')

        # --- акцентный оранжевый только на `--color-surface-default` ---------
        # Подложка — часть условия R-01, а не контекст: на канве та же краска
        # даёт 2,60:1. Перенос героя на канву прошёл, потому что README нигде
        # не связывал акцент с поверхностью машинно.
        acc = contrast(CLR['accent'], CLR['white'])
        canv = contrast(CLR['accent'], CLR['canvas'])
        seen_accent = False
        for dc, name, ln, body in contracts:
            mt = re.search(r'\*\*Токены:\*\*(.*?)(?=\n\*\*[А-ЯA-Z]|\Z)', body, re.S)
            if not mt or '--color-text-display-accent' not in mt.group(1):
                continue
            seen_accent = True
            who = dc or name
            # Привязка выражается КВАЛИФИКАТОРОМ в скобках прямо у токена, а не
            # соседством в перечислении: `--color-surface-default` встречается
            # в списке токенов и сам по себе, поэтому проверка «есть рядом»
            # проходила при полностью снятом квалификаторе.
            mq = re.search(r'`--color-text-display-accent`\s*\(([^)]*)\)', mt.group(1), re.S)
            if not mq:
                self.emit('RM-ACCENT', rel, ln, f'RM-ACCENT:unbound-{who}',
                          f'{who} `{name}`: `--color-text-display-accent` перечислен без '
                          f'квалификатора поверхности. Акцент без названной подложки не '
                          f'является утверждением: {fmt_ratio(acc)}:1 на '
                          f'`--color-surface-default` против {fmt_ratio(canv)}:1 на '
                          f'`--color-surface-canvas` (R-01)')
            elif '--color-surface-canvas' in mq.group(1):
                self.emit('RM-ACCENT', rel, ln, f'RM-ACCENT:{who}',
                          f'{who} `{name}`: акцентный текст объявлен на '
                          f'`--color-surface-canvas` — {fmt_ratio(canv)}:1, ниже порога R-01 '
                          f'(3:1). Допустима только `--color-surface-default` '
                          f'({fmt_ratio(acc)}:1); подложка — часть условия, а не контекст')
            elif '--color-surface-default' not in mq.group(1):
                self.emit('RM-ACCENT', rel, ln, f'RM-ACCENT:unnamed-{who}',
                          f'{who} `{name}`: квалификатор акцента «{mq.group(1)[:50]}» не '
                          f'называет `--color-surface-default` — порог R-01 достигается '
                          f'только на ней')
            # Запрет обязан быть сформулирован в «Запретах» ТОГО КОНТРАКТА,
            # который применяет акцент. Прежняя редакция искала формулировку по
            # всему файлу — и перекрёстная ссылка из §1.5 («полный запрет —
            # DC-38, „Запреты“») закрывала снятие самого запрета.
            mb = re.search(r'\*\*Запреты:\*\*(.*?)(?=\n---|\n\*\*[А-ЯA-Z]|\Z)', body, re.S)
            if not mb:
                self.emit('RM-ACCENT', rel, ln, f'RM-ACCENT:noban-{who}',
                          f'{who} `{name}` применяет акцентный цвет, но не имеет блока '
                          f'«Запреты» — условие подложки нигде не зафиксировано')
            elif not re.search(r'акцентн\w+[^\n]{0,40}`?--color-surface-canvas', mb.group(1)):
                self.emit('RM-ACCENT', rel, ln, f'RM-ACCENT:ban-{who}',
                          f'{who} `{name}`: в «Запретах» нет запрета акцентного героя на '
                          f'`--color-surface-canvas`. Правило, которое соблюдается, но не '
                          f'записано, восстанавливается первой же правкой')
        if not seen_accent:
            self.fail('RM-ACCENT', rel,
                      '[вакуум] ни один контракт не перечисляет '
                      '`--color-text-display-accent` — условие подложки R-01 не проверяется')

    def _reasons(self, rel, who, name, ln, blocks, axis_label, min_chars, min_words):
        """`notApplicableReason` несёт причину, а не слово.

        Порог измерен по файлу: у оси данных самая короткая причина — 49 знаков
        и 6 слов, у оси взаимодействия — 20 знаков и 3 слова. Пороги ниже
        измеренных минимумов с запасом, поэтому ловят `notApplicableReason: нет`
        и не спорят с законной краткой формулировкой.
        """
        for axis, seg in blocks:
            for m in self.RX_NAR.finditer(seg):
                why = re.sub(r'\s+', ' ', m.group(1)).strip().strip('·').strip()
                words = [w for w in re.split(r'[\s·]+', why) if len(w) > 1]
                if len(why) < min_chars or len(words) < min_words:
                    self.emit('RM-NAREASON', rel, ln, f'RM-NAREASON:{who}.{axis_label}.{axis}',
                              f'{who} `{name}`, ось {axis_label} `{axis}`: '
                              f'`notApplicableReason: {why[:40]}` — {len(why)} знаков, '
                              f'{len(words)} слов. Запись без текста причины состояние не '
                              f'объявляет; это тот самый пропуск, из-за которого отклонили '
                              f'партию примитивов (§2.3)')
                    continue
                # СОДЕРЖАТЕЛЬНОСТЬ, а не длина (вердикт Codex, класс 9 и T21).
                # Длинная тавтология проходила счётчик знаков: «состояние
                # неприменимо к этому компоненту, поскольку компонент не
                # предполагает данного состояния» — 90 знаков и ноль причины.
                # Причина обязана называть ПРИЧИННЫЙ ОБЪЕКТ: чем состояние
                # заменено, где живёт, почему невозможно, что было бы неверным.
                if self.RX_TAUTOLOGY.search(why) and not self.RX_CAUSAL.search(why):
                    self.emit('RM-NAREASON', rel, ln,
                              f'RM-NAREASON:tautology:{who}.{axis_label}.{axis}',
                              f'{who} `{name}`, ось {axis_label} `{axis}`: причина '
                              f'самоописательна — «{why[:60]}». Она повторяет вывод '
                              f'(«неприменимо») вместо основания. Причина обязана называть '
                              f'причинный объект: где состояние живёт вместо этого, что его '
                              f'делает невозможным или каким утверждением оно стало бы. '
                              f'Длина доказательством не является')
                # Требовать причинную связку у КАЖДОЙ причины оказалось шире
                # долга: формулировки вида «бейдж не является выбором» называют
                # субъект и отрицают состояние — это причина, а не тавтология.
                # Порог оставлен там, где его назвал аудитор: самоописание.

    # -- 2b2. Контракты примитивов: components-core.md был вне охвата ---------
    # Вердикт Codex, класс 3: семь осей разбирались ТОЛЬКО из README, и удаление
    # оси из контракта примитива не ловилось ничем (T18), как и снятый keyboard
    # contract (T19) и разрешение icon-only без доступного имени (T20).
    # Формат контрактов там другой (`*Данные*:` вместо `**Состояния — данные:**`,
    # оси группируются `loading / empty / partial / error`), поэтому парсер свой,
    # но правило то же: семь осей у каждого из 22 контрактов.
    def check_core_contracts(self):
        rel = 'design-system/components-core.md'
        txt = self.read(rel)
        if txt is None:
            self.fail('CORE-AXES', rel, '[вакуум] components-core.md отсутствует — '
                                        '22 контракта примитивов не проверяются')
            return
        rows = txt.split('\n')
        try:
            a = next(i for i, l in enumerate(rows) if re.match(r'^## 2\.', l))
            b = next(i for i, l in enumerate(rows) if re.match(r'^## 9\.', l))
        except StopIteration:
            self.fail('CORE-AXES', rel, '[вакуум] границы разделов контрактов (## 2 … ## 9) '
                                        'не найдены — ни один контракт не разобран')
            return
        heads = [(i, rows[i][4:].strip()) for i in range(a, b) if rows[i].startswith('### ')]
        heads.append((b, ''))
        if len(heads) - 1 < 20:
            self.fail('CORE-AXES', rel, f'[вакуум] распознано {len(heads) - 1} контрактов '
                                        f'примитивов; раздел 7 аудита объявляет 22')
        contracts = {}
        for k in range(len(heads) - 1):
            i, name = heads[k]
            contracts[name] = (i + 1, '\n'.join(rows[i:heads[k + 1][0]]))
        complete = set()
        for name, (ln, body) in contracts.items():
            m = re.search(r'\*Данные\*\s*:?(.*?)(?=\n\*\*[А-ЯA-Z]|\n\*[А-ЯA-Z]|\Z)', body, re.S) \
                or re.search(r'\*\*Состояния:\*\*(.*?)(?=\n\*\*[А-ЯA-Z]|\Z)', body, re.S)
            if not m:
                self.emit('CORE-AXES', rel, ln, f'CORE-AXES:noblock-{name}',
                          f'`{name}`: блок состояний по оси данных отсутствует. Компонент '
                          f'без пяти состояний плюс двух осей в прототип не попадает '
                          f'(правило проекта 30, STATE-001)')
                continue
            blk = m.group(1)
            # НАСЛЕДОВАНИЕ — законная форма объявления, и она проверяемая:
            # родитель обязан существовать и сам объявлять все семь осей.
            inh = re.search(r'наследу\w*\s+от\s+`?([A-Z][A-Za-z0-9]*)|'
                            r'все\s+семь\s+состояний\s+`?([A-Z][A-Za-z0-9]*)', blk)
            if inh:
                parent = inh.group(1) or inh.group(2)
                if parent not in contracts:
                    self.emit('CORE-AXES', rel, ln, f'CORE-AXES:parent-{name}',
                              f'`{name}` наследует оси состояний от `{parent}`, которого '
                              f'в разделе контрактов нет — висячее наследование')
                else:
                    complete.add((name, parent))
                continue
            found = set()
            for span in re.findall(r'`([^`]*)`', blk):
                found |= {w for w in re.split(r'[\s/·,]+', span) if w in DATA_AXES}
            for axis in DATA_AXES:
                if axis not in found:
                    self.emit('CORE-AXES', rel, ln, f'CORE-AXES:{name}.{axis}',
                              f'`{name}`: ось `{axis}` не объявлена. Семь осей — '
                              f'`{" · ".join(DATA_AXES)}` — обязательны каждая; на этом '
                              f'отклонили партию примитивов (STATE-001)')
            # причина неприменимости — та же семантическая проверка, что в README
            self._reasons(rel, name, name, ln, [('данные', blk)], 'данные', 12, 3)
        # наследование обязано вести к полному контракту
        for name, parent in complete:
            pln, pbody = contracts[parent]
            pm = re.search(r'\*Данные\*\s*:?(.*?)(?=\n\*\*[А-ЯA-Z]|\n\*[А-ЯA-Z]|\Z)', pbody, re.S)
            if not pm:
                continue
            pfound = set()
            for span in re.findall(r'`([^`]*)`', pm.group(1)):
                pfound |= {w for w in re.split(r'[\s/·,]+', span) if w in DATA_AXES}
            gaps = [x for x in DATA_AXES if x not in pfound]
            if gaps:
                self.emit('CORE-AXES', rel, contracts[name][0], f'CORE-AXES:inherit-{name}',
                          f'`{name}` наследует оси от `{parent}`, у которого сами не объявлены '
                          f'{gaps} — наследование неполноты остаётся неполнотой')
        # CORE-A11Y: обязательные разделы доступности и доступное имя icon-only
        for name, (ln, body) in contracts.items():
            for need, why in ((r'\*+Клавиатура[^*\n]{0,60}\*+|\*Клавиатура\*',
                               'клавиатурный контракт (правило 22, раздел 10 аудита)'),
                              (r'Screen\s*reader',
                               'контракт screen reader: роль, доступное имя, объявление '
                               'состояния')):
                if not re.search(need, body):
                    self.emit('CORE-A11Y', rel, ln, f'CORE-A11Y:{name}:{need[:14]}',
                              f'`{name}`: отсутствует {why}. Контракт без него не проверяем '
                              f'вручную и не проверяем машиной — он просто не существует')
        allow_icon = re.compile(
            r'(?:icon-only|nur\s+Icon|иконк\w*)[^\n]{0,120}?'
            r'(?:aria-label|доступное\s+имя|accessible\s+name)[^\n]{0,60}?'
            r'(?:не\s+обязат\w*|не\s+требу\w*|можно\s+опуст\w*|допустимо\s+без|'
            r'вправе\s+обойтись|необязат\w*)', re.I)
        rev = re.compile(
            r'(?:aria-label|доступное\s+имя)[^\n]{0,80}?(?:не\s+обязат\w*|не\s+требу\w*|'
            r'необязат\w*)[^\n]{0,80}?(?:icon-only|иконк\w*)', re.I)
        for i, line in enumerate(rows, 1):
            if allow_icon.search(line) or rev.search(line):
                self.emit('CORE-A11Y', rel, i, f'CORE-A11Y:icon-name:{i}',
                          f'контролу без видимой подписи разрешено обходиться без доступного '
                          f'имени — «{line.strip()[:70]}». ICON-002 и gate 15: иконка никогда '
                          f'не единственный носитель смысла, а контрол без имени не существует '
                          f'для screen reader')

    # -- 2c. Числа README сводятся с фикстурой и несут провенанс --------------
    def check_readme_numbers(self):
        rel = 'design-system/README.md'
        readme = self.read(rel) or ''
        rows = readme.split('\n')
        self._specimens('RM-FIXTURE', rel, readme)
        self._sched_d17(rel, readme)
        if not self.fx:
            return
        # Скидка считается от ТОЧНОГО итога, никогда от отображаемого.
        # Разбор позиционный, не по словам: после ставки скидки идут три
        # денежные величины — база, точный результат, показ. Порядок задан
        # арифметикой, а не формулировкой, и потому переживает правку прозы.
        rab = self.fx['rabatt']
        mult = 1 - rab / 100
        found_rabatt = False
        for dc, name, ln, body in (self._contracts(readme, rows) or []):
            m = re.search(r'`?Rabatt\s*([\d,]+)\s*[  ]?%`?', body)
            if not m:
                continue
            found_rabatt = True
            if de(m.group(1)) != rab:
                self.emit('RM-FIXTURE', rel, ln, 'RM-FIXTURE:rabatt-rate',
                          f'{dc or name} называет Rabatt {m.group(1)} %, фикстура — {rab} %')
            nums = [de(x) for x in re.findall(
                r'(?<![\d.,])(\d{1,3}(?:\.\d{3})+(?:,\d+)?)\s*[  ]?€', body[m.end():])]
            if len(nums) < 3:
                self.fail('RM-FIXTURE', rel, f'[вакуум] {dc or name}: после ставки скидки '
                                             f'найдено {len(nums)} денежных величин, нужны три '
                                             f'(база · точный результат · показ)')
                continue
            base, res, shown = nums[0], nums[1], nums[2]
            if base != self.fx['A']:
                self.emit('RM-FIXTURE', rel, ln, f'RM-FIXTURE:rabatt-base-{base}',
                          f'{dc or name}: база скидки {base} € не равна ТОЧНОМУ итогу '
                          f'{self.fx["A"]} € — CALC-007 и инвариант 14.1 запрещают участие '
                          f'отображаемых значений во внутренних расчётах: округление базы '
                          f'до {r1000(self.fx["A"])} завышает цену на '
                          f'{r2((r1000(self.fx["A"]) - self.fx["A"]) * mult)} €')
            elif res != base * mult:
                self.emit('RM-FIXTURE', rel, ln, 'RM-FIXTURE:rabatt-product',
                          f'{dc or name}: {base} × {mult} = {base * mult}, '
                          f'README пишет {res}')
            elif shown != r1000(res):
                self.emit('RM-FIXTURE', rel, ln, 'RM-FIXTURE:rabatt-display',
                          f'{dc or name}: показ {shown} ≠ округления точного {res} '
                          f'до 1.000 € ({r1000(res)})')
        if not found_rabatt:
            self.fail('RM-FIXTURE', rel, '[вакуум] ни один контракт не называет ставку '
                                         'Rabatt — база скидки не проверяется')
        # Агрегация комплекса — от СУММ, никогда как среднее из средних
        # (правило проекта 39). Якорь структурный и нормативный: подписи
        # `Σ BGF oberirdisch` и `Σ BGF R+S` заданы правилом, а не вёрсткой,
        # поэтому переформатирование абзаца проверку не ломает. Знаменатель
        # обязан совпадать с подписью — складывать надземную и подземную
        # площадь под подписью «oberirdisch» запрещено (DATA-001).
        for label, exp in (('oberirdisch', self.fx['sum_ober']),
                           (r'R\+S', self.fx['sum_rs'])):
            hits = list(re.finditer(r'Σ\s*BGF\s*(?:\*\*)?' + label + r'(?:\*\*)?\s*'
                                    r'([\d.]+(?:,\d+)?)\s*[  ]?m²', readme))
            if not hits:
                self.fail('RM-FIXTURE', rel,
                          f'[вакуум] README не называет `Σ BGF {label} <N> m²` ни разу — '
                          f'агрегация комплекса не проверяется (правило проекта 39)')
                continue
            for m in hits:
                got = de(m.group(1))
                if got == exp:
                    continue
                self.emit('RM-FIXTURE', rel, readme[:m.start()].count('\n') + 1,
                          f'RM-FIXTURE:agg-{label}-{m.group(1)}',
                          f'`Σ BGF {label}` = {m.group(1)} m², фикстура даёт {exp} m² '
                          f'(сумма зданий, проверенная классом CALC-FIXTURE) — удельные '
                          f'величины считаются от сумм, знаменатель обязан совпадать '
                          f'с подписью (правило проекта 39, DATA-001)')
        # СПЕСИМЕН КОНФЛИКТА ССЫЛАЕТСЯ НА СОСТОЯНИЕ, А НЕ НА ДВА ЧИСЛА.
        # Вердикт Codex: DC-32 заменил несуществовавшие числа существующими, но
        # не существующим состоянием — оба значения объявлены в фикстуре
        # независимо, а описываемого конфликта в ней нет. Проверка сходимости
        # каждого числа по отдельности такой спесимен пропускает по построению.
        conflicts = self.fx.get('conflicts') or {}
        for dc, name, ln, body in (self._contracts(readme, rows) or []):
            # Только контракт конфликт-резолвера: «конфликт» упоминают многие
            # контракты, а спесимен состояния есть у одного.
            if 'Conflict' not in name:
                continue
            if not conflicts:
                self.fail('RM-FIXTURE', rel,
                          f'[вакуум] {dc or name} описывает конфликт значений, а фикстура '
                          f'не объявляет ни одного `DEMO-CONF-nnnn` — сверять состояние '
                          f'не с чем')
                break
            named = set(re.findall(r'`?(DEMO-CONF-\d+)`?', body))
            if not named:
                self.emit('RM-FIXTURE', rel, ln, f'RM-FIXTURE-CONFLICT:noref-{dc or name}',
                          f'{dc or name} `{name}`: спесимен конфликта не ссылается ни на один '
                          f'объявленный `Conflict` фикстуры ({", ".join(sorted(conflicts))}). '
                          f'Два независимо объявленных числа изображают конфликт, а не '
                          f'воспроизводят его: описываемого СОСТОЯНИЯ в фикстуре нет, и '
                          f'посверочная проверка каждого числа по отдельности это пропускает')
                continue
            for cid in sorted(named):
                if cid not in conflicts:
                    self.emit('RM-FIXTURE', rel, ln, f'RM-FIXTURE-CONFLICT:dangling-{cid}',
                              f'{dc or name}: ссылка на `{cid}`, которого фикстура '
                              f'не объявляет')
                    continue
                want = conflicts[cid]
                got = {de(x) for x in re.findall(r'([\d.]+,\d+)\s*[\u00a0\u202f ]?m²', body)}
                missing = [str(w) for w in want if w not in got]
                if missing:
                    self.emit('RM-FIXTURE', rel, ln, f'RM-FIXTURE-CONFLICT:cand-{cid}',
                              f'{dc or name}: спесимен ссылается на `{cid}`, но не приводит '
                              f'его кандидатов {missing}: конфликт обязан быть показан теми '
                              f'значениями, которыми он объявлен')

        # провенанс: денежный блок обязан называть прогон или сценарий фикстуры
        contracts = self._contracts(readme, rows) or []
        for dc, name, ln, body in contracts:
            if not (self.RX_MONEY.search(body) or self.RX_RATE.search(body)):
                continue
            if not re.search(r'DEMO-(?:SC|RUN)-\d+', body):
                self.emit('RM-FIXTURE', rel, ln, f'RM-FIXTURE-PROV:{dc or name}',
                          f'{dc or name} `{name}` показывает денежные или удельные величины, '
                          f'но не называет ни `scenarioId` (`DEMO-SC-nn`), ни '
                          f'`calculationRunId` (`DEMO-RUN-nnnn`) — §2.1 требует провенанс '
                          f'у любого денежного, площадного, ставочного и срочного блока '
                          f'(CALC-002, XSC-05)')

    # -- 3. Копирайт-инварианты по всем документам ----------------------------
    def check_copy(self):
        # Каждый паттерн переписан после того, как аудитор обошёл все восемь
        # однословной правкой: скобка, дефис, артикль, предлог.
        # `*.json` теперь проходит те же проверки: до v3 туда ходил только
        # XSC-10, и живая UI-строка `ab Decke` в каталоге параметров
        # проходила насквозь.
        rules = [
            ('DATA-005', r'WFL[\s*_`(\[]*inkl', 'живое «WFL inkl. …» (DATA-005)'),
            ('R-18', r'Gesamt netto(?!\s*[`*]*\s*·\s*[^\s|`*])',
             'тотал без непустого Declared Pricing Scope (R-18)'),
            ('XSC-10', r'KfW[\s\-*_·]*(40|55)(?![\d])',
             'термин программы вместо EH-стандарта в UI-копии (XSC-10)'),
            ('COPY-007', r'\bab[\s*_]+(?:der[\s*_]+|die[\s*_]+|OK[\s*_]+)?Decke\b(?!\s+über\s+UG)',
             'сокращение «ab Decke» запрещено (раздел 1.4 аудита, COPY-007)'),
            ('COPY-004', r'Genauigkeit[^\n±]{0,20}±|Genauigkeits?[\s-]*(Badge|Anzeige|Wert)',
             'термин «Genauigkeit ±» запрещён; production-термин Schätzunsicherheit (COPY-004)'),
        ]
        for glob in ('*.md', '*.json'):
            for rel, text in self.files(glob):
                if rel.startswith('tools/'):
                    continue
                for cls, pat, msg in rules:
                    self.scan(cls, rel, text, pat, msg)
        # LAYOUT-007: плотность привязана к режиму (DE/ASCII/RU написания)
        for rel in ('design-system/README.md', 'CLAUDE.md'):
            text = self.read(rel) or ''
            for i, line in enumerate(text.split('\n'), 1):
                low = line.lower()
                if ('praesentation' in low or 'präsentation' in low or 'презентац' in low
                        or 'клиентск' in low):
                    if re.search(r'(только|физически не может|запрещ\w*|ausschließlich|'
                                 r'ausschliesslich|nur|niemals|kann nicht|erzwing\w*)'
                                 r'[\s\w*_`«»„“]{0,12}?'
                                 r'(comfortable|komfortabel|compact|kompakt)', low):
                        self.emit('LAYOUT-007', rel, i, line,
                                  f'плотность привязана к режиму — {line.strip()[:70]}')

    # -- 3a. Правило 22: интерактивное — настоящий контрол -------------------
    def check_controls(self):
        rx = re.compile(r'<(span|div|p|li|a(?![\w-])[^>]*?(?<!href=)\s)[^>]*\bon(click|keydown|keyup)\s*=', re.I)
        for glob in ('*.md', '*.html'):
            for rel, text in self.files(glob):
                if rel.startswith('tools/'):
                    continue
                for i, line in enumerate(text.split('\n'), 1):
                    for m in rx.finditer(line):
                        self.emit('GATE-CONTROL', rel, i, line,
                                  f'«{m.group(0)[:40]}» — правило 22 требует настоящий контрол '
                                  f'(<button>), не обработчик на неинтерактивном элементе')

    # -- 3b. Модель данных: docs/product/data-model.md ------------------------
    def check_data_model(self):
        """Механически проверяемое в модели данных.

        Аудитор нашёл шесть висячих ссылок на типы чтением; это ровно тот же
        класс, что висячие ссылки на токены, и он проверяется машиной.
        """
        rel = 'docs/product/data-model.md'
        dm = self.read(rel)
        if dm is None:
            self.fail('DM-TYPE', rel, '[вакуум] docs/product/data-model.md отсутствует')
            return
        blocks = [(m.group(1), dm[:m.start()].count('\n') + 1)
                  for m in re.finditer(r'```ts\s*\n(.*?)```', dm, re.S)]
        if not blocks:
            self.fail('DM-TYPE', rel, '[вакуум] в модели нет ни одного ts-блока — типы не объявлены')
            return
        defined, generics = set(), set()
        for body, _off in blocks:
            defined |= set(re.findall(r'^\s*(?:export\s+)?(?:interface|type|enum|class)\s+([A-Z][A-Za-z0-9_]*)',
                                      body, re.M))
            defined |= set(re.findall(r'^\s*([A-Z][A-Za-z0-9_]*)\s*(?:<[^>]*>)?\s*\{', body, re.M))
            for g in re.findall(r'<([A-Z][A-Za-z0-9_,\s]*)>', body):
                generics |= {x.strip() for x in g.split(',') if x.strip()}
        # Встроенные типы TypeScript и обозначения внешних стандартов —
        # структурно: они не объявляются моделью и не могут быть висячими.
        BUILTIN = {'Array', 'Record', 'Partial', 'Readonly', 'Pick', 'Omit', 'Map', 'Set',
                   'Date', 'Promise', 'String', 'Number', 'Boolean', 'Object', 'JSON'}
        dangling = {}
        for body, off in blocks:
            for i, line in enumerate(body.split('\n')):
                for m in re.finditer(r'(?::|=|\||<|extends|,)\s*([A-Z][A-Za-z0-9_]*)', line):
                    nm = m.group(1)
                    if (nm in defined or nm in BUILTIN or nm in generics
                            or len(nm) <= 2 or re.search(r'Ids?$', nm)):
                        continue          # `*Id` — непрозрачный идентификатор по конвенции
                    dangling.setdefault(nm, off + i)
        # Отпечаток берётся от ИМЕНИ типа, а не от строки: строка модели
        # переезжает при любой правке выше, а имя — устойчивая идентичность
        # находки. Регистрация выдана каждому имени отдельно, поэтому новая
        # висячая ссылка — новое нарушение, а не «уже известное».
        for nm, ln in sorted(dangling.items(), key=lambda x: x[1]):
            self.emit('DM-TYPE', rel, ln, f'DM-TYPE:{nm}',
                      f'ссылка на необъявленный тип {nm} (модель ссылается, но не определяет)')
        # `Type.field`, названные по имени в тексте: тип обязан существовать
        pairs = set(re.findall(r'`([A-Z][A-Za-z0-9]+)\.([a-z][A-Za-z0-9]*)`', dm))
        pairs |= set(re.findall(r'`([A-Z][A-Za-z0-9]+)\.([a-z][A-Za-z0-9]*)`',
                               self.read('docs/audit/requirements-registry.md') or ''))
        if not pairs:
            self.fail('DM-TYPE-FIELD', rel,
                      '[вакуум] ни одной ссылки вида `Type.field` — проверка непроверяема')
        for ty, fld in sorted(pairs):
            if ty not in defined:
                lineno = next((i for i, l in enumerate(dm.split('\n'), 1)
                               if f'`{ty}.{fld}`' in l), 1)
                self.emit('DM-TYPE-FIELD', rel, lineno, f'DM-TYPE-FIELD:{ty}.{fld}',
                          f'норматив/модель называет `{ty}.{fld}`, но тип {ty} в модели не объявлен')
        # §9: каждый P0 из охвата партии обязан быть упомянут инвариантом
        plan = self.read('docs/audit/remediation-plan.md') or ''
        mb = re.search(r'^## Batch 4[^\n]*\n(.*?)(?=\n## |\Z)', plan, re.S | re.M)
        m9 = re.search(r'^##\s*9\.\s*Инварианты(.*?)(?=\n##\s|\Z)', dm, re.S | re.M)
        if not mb:
            self.fail('DM-INVARIANT', 'remediation-plan.md',
                      '[вакуум] секция «Batch 4» в плане не найдена — охват партии неизвестен')
        elif not m9:
            self.fail('DM-INVARIANT', rel, '[вакуум] раздел «9. Инварианты» в модели не найден')
        else:
            scope_line = re.search(r'Закрывает:\s*(.+)', mb.group(1))
            if not scope_line:
                self.fail('DM-INVARIANT', 'remediation-plan.md',
                          '[вакуум] в секции Batch 4 нет строки «Закрывает: …»')
            else:
                want = set()
                for fam, a, b in re.findall(r'([A-Z][A-Z0-9]*)-(\d{3})\s*[…\-–/]+\s*(?:[A-Z]+-)?(\d{1,3})',
                                            scope_line.group(1)):
                    for n in range(int(a), int(b) + 1):
                        want.add(f'{fam}-{n:03d}')
                want |= set(re.findall(r'\b([A-Z][A-Z0-9]*-\d{3})\b', scope_line.group(1)))
                have = set(re.findall(r'\b([A-Z][A-Z0-9]*-\d{3})\b', m9.group(1)))
                missing = sorted(want - have)
                if missing:
                    ln = dm[:m9.start()].count('\n') + 1
                    self.emit('DM-INVARIANT', rel, ln,
                              'DM-INVARIANT:' + ','.join(missing),
                              f'§9 не содержит инварианта ни для одного из требований охвата '
                              f'Batch 4: {", ".join(missing)} — заявленное покрытие не подтверждено')
        # Кросс-сверка правил округления между двумя артефактами партии
        sp = self.read('docs/product/calculation-spec.md') or ''
        tbl = re.search(r'\|\s*Величина\s*\|[^\n]*Префикс[^\n]*\|\n\|[-\s|]+\|\n((?:\|[^\n]*\n)+)', sp)
        if not tbl:
            self.fail('DM-ROUND', 'calculation-spec.md',
                      '[вакуум] таблица правил округления с колонкой «Префикс ≈» не найдена')
        else:
            for row in tbl.group(1).strip().split('\n'):
                cells = [c.strip() for c in row.strip('|').split('|')]
                if len(cells) < 4:
                    continue
                if 'если показ' not in cells[3]:
                    ln = sp[:tbl.start()].count('\n') + 1
                    self.fail('DM-ROUND', f'calculation-spec.md:{ln}',
                              f'строка «{cells[0]}»: префикс ≈ задан как «{cells[3][:40]}»; '
                              f'data-model.md требует префикс при любом расхождении показа '
                              f'с точным значением (CALC-007) — противоречие между артефактами')
        if '≈' not in dm or not re.search(r'префикс\s*`?≈', dm):
            self.fail('DM-ROUND', rel,
                      'модель не формулирует правило префикса `≈` (CALC-007)')
        # Ссылки на решения: заявление обязано называть номер, номер — существовать
        dec = self.read('docs/product/decisions.md') or ''
        heads = set(re.findall(r'^##\s*D-(\d+)', dec, re.M))
        # Заявление «зафиксировано в decisions.md» проверяется по СМЕЖНОСТИ:
        # глагол-утверждение обязан стоять рядом с самой ссылкой, иначе любое
        # упоминание файла в перечислении становилось ложным срабатыванием.
        claim = re.compile(r'(?:зафиксирован\w*|реш(?:ено|ён\w*|ена|ены)|принят\w*|согласно|'
                           r'по решению|основание)[^.\n]{0,40}`?[\w/.-]*decisions\.md|'
                           r'decisions\.md`?[^.\n]{0,40}(?:зафиксирован\w*|принят\w*|'
                           r'основание|решением)', re.I)
        for r, text in self.files('*.md'):
            if r.startswith('tools/'):
                continue
            for i, line in enumerate(text.split('\n'), 1):
                if 'decisions.md' not in line:
                    continue
                nums = re.findall(r'D-(\d+)', line)
                if not nums:
                    if claim.search(line):
                        self.emit('DM-DECISION', r, i, line,
                                  'ссылка на `decisions.md` как на основание без номера решения — '
                                  'проверить утверждение невозможно')
                    continue
                for n in nums:
                    if n.lstrip('0').zfill(2) not in {h.lstrip('0').zfill(2) for h in heads}:
                        self.emit('DM-DECISION', r, i, line,
                                  f'ссылка на решение D-{n}, которого нет в decisions.md '
                                  f'(есть D-{min(heads, key=int)}…D-{max(heads, key=int)})')

    # -- 3b2. Истинность инвариантов модели, а не покрытие идентификаторами ---
    # Вердикт Codex, класс 6 и пункт 9: `DM-INVARIANT` доказывал только, что ID
    # требований охвата встречаются в §9. Прошли перевёрнутый знак дельты,
    # проценты вместо процентных пунктов, порядок приоритета котировок,
    # `taxBasis = gross` у полного итога и неупорядоченный список в хеше.
    # Здесь проверяется СОДЕРЖАНИЕ: формула, знак, единица, порядок, базис.
    #
    # Каждое правило — (класс, что искать в определении, что обязано быть
    # рядом, что запрещено рядом, объяснение). Определение и инвариант §9
    # сверяются РАЗДЕЛЬНО: верная копия в §9 не имеет права оправдывать
    # испорченное определение (класс 7 вердикта).
    DM_TRUTH = (
        ('absoluteDelta', r'absoluteDelta',
         r'[Ss]ubject\w*\s*[−–-]\s*\w*[Tt]arget',
         r'[Tt]arget\w*\s*[−–-]\s*\w*[Ss]ubject',
         'знак дельты: `absoluteDelta = subject − target`. Перевёрнутый знак '
         'превращает удорожание в экономию во всех дельта-чипах сразу'),
        ('relativeDeltaPercent', r'relativeDeltaPercent',
         r'относительн\w*\s*процент|процент\w*\s*от|relative',
         r'процентн\w+\s+пункт',
         'единица: `relativeDeltaPercent` — относительный процент. Процентные '
         'пункты и проценты не взаимозаменяемы: `± 22 %` → `± 17 %` есть '
         '−5 процентных пунктов, а не −5 %'),
        ('marginDeltaPp', r'marginDeltaPp|Pp\b',
         r'процентн\w+\s+пункт|percentage\s*point',
         r'(?<!не\s)процент\w*\s+от\s+span',
         'единица сужения неопределённости — процентные пункты (суффикс `Pp`)'),
        ('сужение неопределённости', r'[Сс]ужение\s+неопределённости\s+выражается',
         r'процентных\s+пунктах',
         r'выражается\s+в\s+процентах(?!\w)',
         'сужение интервала выражается в процентных пунктах: путь от `±22 %` '
         'к `±13 %` есть `−9` процентных пунктов, и «минус 9 %» утверждает '
         'другое число'),
        ('налоговая база итога', r'входящие\s+в\s+один\s+итог',
         r'`?taxBasis\s*=\s*net`?',
         r'`?taxBasis\s*=\s*(?:gross|brutto)`?',
         'все значения одного итога абсолютно в `taxBasis = net`: две строки '
         'могут добросовестно делить между собой brutto и сложиться под '
         'подписью `Gesamt netto`, где слово `netto` уже произнесено'),
        ('normalizationSnapshotRefs', r'normalizationSnapshotRefs',
         r'упорядоч\w*|ordered|порядк\w*\s+объявлен|стабильн\w+\s+порядк',
         r'произвольн\w+\s+порядк|неупорядоч\w*|порядок\s+не\s+(?:важ|значи)',
         'состав `evaluationContextHash` включает УПОРЯДОЧЕННЫЙ список '
         'снапшотов: при произвольном порядке один и тот же контекст даёт '
         'разные хеши, и повторная оценка перестаёт воспроизводиться'),
    )
    # Упорядоченные перечисления, чей порядок есть приоритет.
    DM_ORDER = (
        ('QuoteEvaluation', ('withdrawn', 'expired', 'valid'),
         'приоритет состояния котировки: отозванная старше истёкшей. '
         'Иначе отозванное предложение снова показывается как «просто истекло»'),
    )

    def check_data_model_truth(self):
        rel = 'docs/product/data-model.md'
        dm = self.read(rel)
        if dm is None:
            self.fail('DM-TRUTH', rel, '[вакуум] модель данных отсутствует')
            return
        rows = dm.split('\n')

        def para_of(idx):
            """Абзац (смежные непустые строки) вокруг позиции — единица смысла."""
            ln = dm[:idx].count('\n')
            a = b = ln
            while a > 0 and rows[a - 1].strip():
                a -= 1
            while b + 1 < len(rows) and rows[b + 1].strip():
                b += 1
            return '\n'.join(rows[a:b + 1]), ln + 1

        # Границы разделов `## …`. `need` ищется в СВОЁМ разделе, а не по всему
        # файлу: инвариант §9 — вторая копия утверждения, и позволить ей
        # закрывать проверку значило бы воспроизвести класс 7 вердикта
        # («правильная копия маскирует испорченное определение»).
        heads = [i for i, l in enumerate(rows) if l.startswith('## ')] + [len(rows)]

        def section_of(idx):
            ln = dm[:idx].count('\n')
            a = max([h for h in heads if h <= ln], default=0)
            b = min([h for h in heads if h > ln], default=len(rows))
            return '\n'.join(rows[a:b])

        NEG = re.compile(r'(?:никогда\s+не|\bне\b|запрещ\w*|вместо|а\s+не|исключ\w*|'
                         r'недопуст\w*|нельзя)[\s,«"`*_]*$', re.I)

        for name, anchor, need, ban, why in self.DM_TRUTH:
            hits = list(re.finditer(anchor, dm))
            if not hits:
                self.fail('DM-TRUTH', rel, f'[вакуум] `{name}` в модели не найден — '
                                           f'истинность инварианта не проверяется: {why}')
                continue
            ok, offenders = False, []
            for m in hits:
                blk, ln = para_of(m.start())
                for b in re.finditer(ban, blk, re.I):
                    # СЕМАНТИКА ОТРИЦАНИЯ (класс 8 вердикта): «никогда не
                    # процентный пункт» есть запрет, а не нарушение. Отрицание
                    # опознаётся по позиции — непосредственно перед формой.
                    if NEG.search(blk[max(0, b.start() - 40):b.start()]):
                        continue
                    offenders.append((ln, b.group(0)))
                if re.search(need, section_of(m.start()), re.I):
                    ok = True
            for ln, frag in offenders:
                self.emit('DM-TRUTH', rel, ln, f'DM-TRUTH:{name}:ban',
                          f'`{name}`: в определении утверждается запрещённая форма '
                          f'«{frag[:40]}» без отрицания. {why}')
            if not ok:
                self.emit('DM-TRUTH', rel, dm[:hits[0].start()].count('\n') + 1,
                          f'DM-TRUTH:{name}:need',
                          f'`{name}`: раздел определения не утверждает требуемого. {why}')

        # Порядок приоритета читается из ПРОЗЫ, не из union типа: `"valid" |
        # "expired" | "withdrawn"` — перечисление допустимых значений, и его
        # порядок ничего не значит. Fenced-блоки поэтому вырезаются.
        prose = re.sub(r'```.*?```', lambda m: '\n' * m.group(0).count('\n'), dm, flags=re.S)
        for name, canon, why in self.DM_ORDER:
            m = re.search(re.escape(name) + r'(.{0,1500})', prose, re.S)
            if not m or not re.search('|'.join(canon), m.group(1)):
                self.fail('DM-TRUTH', rel, f'[вакуум] порядок приоритета `{name}` в прозе '
                                           f'модели не найден — precedence не проверяется')
                continue
            first = []
            for x in re.findall('|'.join(canon), m.group(1)):
                if x not in first:
                    first.append(x)
            if tuple(first[:len(canon)]) != canon:
                self.emit('DM-TRUTH', rel, prose[:m.start()].count('\n') + 1,
                          f'DM-TRUTH:{name}:order',
                          f'`{name}`: порядок {first[:len(canon)]}, канонический '
                          f'{list(canon)}. {why}')

        # Налоговая база полного итога: `net` абсолютно, `gross` — только после
        # явного преобразования (T29). Проверяется рядом с подписью итога.
        for m in re.finditer(r'taxBasis[^\n]{0,120}', dm):
            frag = m.group(0)
            if re.search(r'"gross"', frag) and not re.search(
                    r'преобразован|umgerechnet|только\s+после|explicit|конверт', frag, re.I):
                blk, ln = para_of(m.start())
                if re.search(r'Gesamt netto|Declared Pricing Scope|полн\w+\s+итог', blk):
                    self.emit('DM-TRUTH', rel, ln, 'DM-TRUTH:taxBasis-gross',
                              'итог с полным Declared Pricing Scope допускает '
                              '`taxBasis = "gross"` без явного преобразования: клиент '
                              'сравнивает брутто с нетто, не зная об этом')

    # -- 3b-quater. Кардинальность как ОБЩИЙ класс ----------------------------
    def check_cardinality(self):
        """`DM-CARDINALITY`: количественные границы модели данных.

        Причина, по которой класс общий, а не точечный. Прежде такие границы
        не проверялись вовсе: `DM-TRUTH` идёт по конечному реестру знаков,
        единиц и порядков, а «не более одного `authoritative` на слот» —
        утверждение другого рода. Замена «одного» на «двух» сохраняет номер
        инварианта, его формулировку и все ссылки на него, поэтому проверки
        покрытия идентификаторами такое ослабление не видят по построению
        (M43). Добавлять regex после каждого аудита — работа без конца, а
        одна грамматика читает `= n`, `≤ n`, `≥ n`, непустоту и попарную
        уникальность из ТЕЛА ТИПА, из ЯЧЕЙКИ ТАБЛИЦЫ и из ПУНКТА §9 одинаково.

        Локатор реестра указывает на УТВЕРЖДЕНИЕ, а не на ответ: границу
        извлекает грамматика. Поэтому запись реестра не может «пройти сама
        себя» — она не содержит того, что проверяет.
        """
        rel = 'docs/product/data-model.md'
        txt = self.read(rel)
        if txt is None:
            self.fail('DM-CARDINALITY', rel, '[вакуум] модель данных отсутствует — '
                                             'количественные границы не проверяются')
            return
        for key, loc, canon, why in DM_CARDINALITY:
            hits = list(re.finditer(loc, txt, re.M))
            if not hits:
                self.fail('DM-CARDINALITY', rel,
                          f'[вакуум] утверждение о кардинальности «{key}» в модели не '
                          f'найдено — граница не проверяется: {why}')
                continue
            for m in hits:
                frag = m.group(0)
                ln = txt[:m.start()].count('\n') + 1
                if canon == 'unique':
                    if not _CARD_UNIQUE.search(frag):
                        self.emit('DM-CARDINALITY', rel, ln,
                                  f'DM-CARDINALITY:{key}:no-unique',
                                  f'«{frag.strip()[:70]}» — утверждение о попарной '
                                  f'уникальности снято. {why}')
                    continue
                got = card_parse(frag)
                if got is None:
                    self.emit('DM-CARDINALITY', rel, ln,
                              f'DM-CARDINALITY:{key}:unstated',
                              f'«{frag.strip()[:70]}» — граница не названа, канонически '
                              f'{card_fmt(canon)}. Количественное правило без '
                              f'количества нечем проверить: {why}')
                elif got != canon:
                    self.emit('DM-CARDINALITY', rel, ln,
                              f'DM-CARDINALITY:{key}:{card_fmt(got)}',
                              f'«{frag.strip()[:70]}» объявляет {card_fmt(got)}, '
                              f'канонически {card_fmt(canon)}. {why}')

    # -- 3c. Annahmen: текст, уходящий клиенту --------------------------------
    def check_annahmen(self):
        """`docs/product/t0-fallback-rules.md` — источник текстов Annahmen.

        Клиентская поверхность дороже всех остальных, а до v3 инструмент не
        знал об этом файле вовсе. Два дефекта нашёл человек: класс здания
        объявлялся клиенту выведенным из этажности (CALC-004) и покрытие
        KG 500 объявлялось `nicht enthalten` при фактическом `unknown`
        (R-18/CALC-006). Оба проверяемы структурно.
        """
        rel = 'docs/product/t0-fallback-rules.md'
        txt = self.read(rel)
        if txt is None:
            self.fail('T0-FACT', rel, '[вакуум] источник текстов Annahmen отсутствует')
            return
        rows = txt.split('\n')
        # разбивка на секции `### …`
        heads = [i for i, l in enumerate(rows) if l.startswith('### ')] + [len(rows)]
        if len(heads) < 2:
            self.fail('T0-FACT', rel, '[вакуум] в файле нет секций `### …` — Annahmen не локализуемы')
        annahmen_seen = 0
        for a, b in zip(heads, heads[1:]):
            sec = rows[a:b]
            body = '\n'.join(sec)
            needs_check = 'Prüfung erforderlich' in body
            for k, line in enumerate(sec):
                if '**Annahme:**' not in line:
                    continue
                annahmen_seen += 1
                ln = a + k + 1
                # (1) выведение класса из этажности — прямое нарушение CALC-004
                if re.search(r'(ergibt sich|abgeleitet|folgt|bestimmt|ermittelt)[^.]{0,60}'
                             r'Geschoss|Geschoss\w*[^.]{0,60}'
                             r'(ergibt sich|abgeleitet|folgt|bestimmt)', line) \
                   and re.search(r'Gebäudeklasse|\bGK\b', line):
                    self.emit('T0-FACT', rel, ln, line,
                              'Annahme объявляет Gebäudeklasse выведенной из этажности; '
                              'CALC-004: этажность — только триггер проверки, не доказательство')
                # (2) значение с `Prüfung erforderlich` подаётся как факт
                if needs_check and re.search(r'Gebäudeklasse|\bGK\b', line) and \
                   not re.search(r'nicht bestätigt|Prüfauslöser|noch offen|unbestätigt|'
                                 r'kein Nachweis', line):
                    self.emit('T0-FACT', rel, ln, line,
                              'секция помечена `Prüfung erforderlich`, но Annahme не называет '
                              'значение неподтверждённым — клиенту сообщается факт вместо гипотезы')
        if not annahmen_seen:
            self.fail('T0-FACT', rel, '[вакуум] ни одного блока `**Annahme:**` не найдено')
        # (3) состояние покрытия в Annahme обязано совпадать с фикстурой
        fx = self.read('docs/audit/synthetic-fixtures.md') or ''
        mstate = re.search(r'KG 500[^\n]*?coverage\s*`(\w+)`', fx)
        if not mstate:
            self.fail('T0-COVERAGE', 'synthetic-fixtures.md',
                      '[вакуум] фикстура не объявляет coverage для KG 500 — сверять не с чем')
        else:
            state = mstate.group(1)
            hits = 0
            for i, line in enumerate(rows, 1):
                for m in re.finditer(r'Kostengruppe\s*500', line):
                    hits += 1
                    clause = line[m.start():m.start() + 320]
                    undecided = re.search(r'keine\s+Deckungsentscheidung|weder\s+eingeschlossen'
                                          r'\s+noch\s+ausgeschlossen|unbewertet', clause)
                    decided = re.search(r'nicht\s+enthalten|ausgeschlossen(?!\b\s*und)|'
                                        r'\bist\s+enthalten|eingeschlossen(?!\s+noch)', clause)
                    if state == 'unknown' and (decided and not undecided):
                        self.emit('T0-COVERAGE', rel, i, line,
                                  f'Annahme объявляет покрытие KG 500 решённым, фикстура даёт '
                                  f'coverage `{state}` (R-18/CALC-006): пока состояние неизвестно, '
                                  f'оффер несёт Zwischensumme, а не решение о включении')
                    if state == 'unknown' and not undecided and not decided:
                        self.emit('T0-COVERAGE', rel, i, line,
                                  'Annahme упоминает KG 500, но не называет состояние покрытия')
            if not hits:
                self.fail('T0-COVERAGE', rel,
                          '[вакуум] Annahmen не упоминают Kostengruppe 500 — состояние покрытия '
                          'клиенту не сообщается вовсе (R-18/CALC-006)')

    # -- 3d. Модель выдач, видимости и гейтов --------------------------------
    RU_NUM = {'одного': 1, 'одного условия': 1, 'двух': 2, 'трёх': 3, 'трех': 3,
              'четырёх': 4, 'четырех': 4, 'пяти': 5, 'шести': 6, 'семи': 7,
              'восьми': 8, 'девяти': 9, 'десяти': 10,
              'один': 1, 'два': 2, 'три': 3, 'четыре': 4, 'пять': 5, 'шесть': 6,
              'семь': 7, 'восемь': 8, 'девять': 9, 'десять': 10}

    def check_output_model(self):
        """`docs/product/output-model.md` — охват до v4 был ноль.

        Из десяти мутаций аудитора прошли шесть. Все шесть — структурные:
        нумерация инвариантов, число условий в определении против числа,
        названного инвариантом, состав обязательных полей типа, число
        клиентских профилей в матрице блокировки, связка политики и
        сериализации, денежный спесимен против фикстуры. Ни одна не требует
        понимания текста — только сверки структуры со структурой.
        """
        rel = 'docs/product/output-model.md'
        txt = self.read(rel)
        if txt is None:
            self.fail('OUT-SEQ', rel, '[вакуум] docs/product/output-model.md отсутствует — '
                                      'артефакт партии Batch 6 инструментом не проверяется')
            return
        rows = txt.split('\n')
        profiles, clients = output_profiles(self.root)
        if not profiles:
            self.fail('OUT-PROFILE', 'docs/product/data-model.md',
                      '[вакуум] `type OutputProfile` не прочитан из data-model.md — '
                      'канонические имена профилей неизвестны, и подставлять свою копию '
                      'инструмент не имеет права (второй источник правды)')

        # (1) OUT-SEQ: непрерывность и совпадение порядкового номера с меткой.
        # Мутация `OUT-30 → OUT-31` даёт одновременно дубль и пропуск.
        items = []
        for i, line in enumerate(rows, 1):
            m = re.match(r'^\s*(\d+)\.\s+\*\*OUT-(\d+)\.\*\*', line)
            if m:
                items.append((int(m.group(1)), int(m.group(2)), i, line))
        if not items:
            self.fail('OUT-SEQ', rel, '[вакуум] ни одного инварианта вида `nn. **OUT-nn.**` '
                                      'не найдено — §14 не проверяем')
        seen_lbl, seen_ord = {}, {}
        for ordn, lbl, ln, line in items:
            if ordn != lbl:
                self.emit('OUT-SEQ', rel, ln, f'OUT-SEQ:ord{ordn}/lbl{lbl}',
                          f'порядковый номер {ordn} не совпадает с меткой OUT-{lbl:02d} — '
                          f'ссылка «output-model OUT-{lbl:02d}» указывает не на этот пункт')
            for reg, key, what in ((seen_lbl, lbl, 'метка OUT'), (seen_ord, ordn, 'порядковый номер')):
                if key in reg:
                    self.emit('OUT-SEQ', rel, ln, f'OUT-SEQ:dup-{what}-{key}',
                              f'{what} {key} встречается второй раз (первый — строка {reg[key]})')
                else:
                    reg[key] = ln
        if items:
            lbls = sorted(seen_lbl)
            for n in range(1, max(lbls) + 1):
                if n not in seen_lbl:
                    self.emit('OUT-SEQ', rel, items[0][2], f'OUT-SEQ:gap-{n}',
                              f'в нумерации инвариантов пропущен OUT-{n:02d} '
                              f'(объявлены 1…{max(lbls)}, фактически {len(lbls)} штук)')
            # OUT-REF: ссылка на инвариант, которого нет
            for r2_, t2 in self.files('*.md'):
                if r2_.startswith('tools/'):
                    continue
                for i, line in enumerate(t2.split('\n'), 1):
                    for m in re.finditer(r'\bOUT-(\d{1,3})\b', line):
                        n = int(m.group(1))
                        if n not in seen_lbl:
                            self.emit('OUT-REF', r2_, i, f'OUT-REF:OUT-{n}',
                                      f'ссылка на инвариант OUT-{n:02d}, которого нет в '
                                      f'output-model.md §14 (объявлены OUT-01…OUT-{max(lbls):02d})')

        # (2) OUT-SEND: `sendEnabled` — конъюнкция N условий. Число, названное
        # в определении §9.3, число строк его таблицы и число, названное
        # инвариантом OUT-36, обязаны совпадать. Снятие одного условия из
        # таблицы прошло молча: инвариант продолжал говорить «шести».
        m = re.search(r'`sendEnabled`\s*—\s*конъюнкция\s+([а-яё]+)\s+услови', txt)
        if not m:
            self.fail('OUT-SEND', rel, '[вакуум] §9.3 не формулирует `sendEnabled` как '
                                       'конъюнкцию названного числа условий')
        else:
            declared = self.RU_NUM.get(m.group(1).lower())
            ln_def = txt[:m.start()].count('\n') + 1
            if declared is None:
                self.emit('OUT-SEND', rel, ln_def, 'OUT-SEND:числительное',
                          f'число условий записано словом «{m.group(1)}», которое инструмент '
                          f'не умеет прочитать — утверждение непроверяемо')
            else:
                # таблица условий: строки `| N | … | … |` сразу после определения
                tail = txt[m.end():]
                cut = re.search(r'\n###\s', tail)
                block = tail[:cut.start()] if cut else tail
                nums = [int(x) for x in re.findall(r'^\|\s*(\d+)\s*\|', block, re.M)]
                if not nums:
                    self.fail('OUT-SEND', rel, '[вакуум] таблица условий §9.3 не распознана')
                else:
                    if nums != list(range(1, len(nums) + 1)):
                        self.emit('OUT-SEND', rel, ln_def, 'OUT-SEND:нумерация-таблицы',
                                  f'условия §9.3 пронумерованы {nums} — ожидалась '
                                  f'непрерывная 1…{len(nums)}')
                    if len(nums) != declared:
                        self.emit('OUT-SEND', rel, ln_def, 'OUT-SEND:число-условий',
                                  f'§9.3 называет конъюнкцию {declared} условий, а таблица '
                                  f'содержит {len(nums)} — одно из двух неверно, и кнопка '
                                  f'отправки открывается по неполному набору (EMAIL-001)')
                    mi = re.search(r'\*\*OUT-36\.\*\*[^\n]*конъюнкции\s+([а-яё]+)\s+услови', txt)
                    if not mi:
                        self.fail('OUT-SEND', rel, '[вакуум] OUT-36 не называет число условий '
                                                   '`sendEnabled` — инвариант непроверяем')
                    else:
                        inv = self.RU_NUM.get(mi.group(1).lower())
                        if inv != len(nums):
                            self.emit('OUT-SEND', rel, txt[:mi.start()].count('\n') + 1,
                                      'OUT-SEND:инвариант-против-таблицы',
                                      f'OUT-36 требует конъюнкцию {mi.group(1)} ({inv}) условий, '
                                      f'таблица §9.3 содержит {len(nums)} — инвариант '
                                      f'отчитывается о том, чего в определении нет')

        # (3) OUT-ATTACH: обязательные носители `AttachmentPreflightItem`.
        # Удаление `contentHash` прошло: тип потерял идентичность вложения,
        # а OUT-43 продолжал её требовать.
        NEED = {
            'clientTitle':             'клиентское название (EMAIL-006)',
            'source':                  'неизменяемая ссылка на версию (EMAIL-002)',
            'contentHash':             'хеш байтов — идентичность вложения (EMAIL-002)',
            'generatedAt':             '«когда это посчитано» (EMAIL-002)',
            'visibilityClassification': 'клиентская безопасность (EMAIL-002, R-17)',
            'stalenessState':          'цена в файле = цена в теле (STALE-001)',
            'calculationBindings':     'какой прогон отвечает за числа (§6.2)',
        }
        mt = re.search(r'AttachmentPreflightItem\s*\{(.*?)\n\}', txt, re.S)
        if not mt:
            self.fail('OUT-ATTACH', rel, '[вакуум] тип `AttachmentPreflightItem` не объявлен — '
                                         'OUT-43 требует его состав')
        else:
            body = mt.group(1)
            ln = txt[:mt.start()].count('\n') + 1
            fields = set(re.findall(r'^\s*([a-z][A-Za-z0-9]*)\??\s*:', body, re.M))
            for f, why in sorted(NEED.items()):
                if f not in fields:
                    self.emit('OUT-ATTACH', rel, ln, f'OUT-ATTACH:{f}',
                              f'`AttachmentPreflightItem` не несёт `{f}` — {why}; '
                              f'OUT-43 требует все семь носителей')
                # каждый носитель обязан быть обоснован таблицей §10.1
                elif f'`{f}`' not in txt.split('### 10.1')[-1][:4000]:
                    self.emit('OUT-ATTACH', rel, ln, f'OUT-ATTACH:justify-{f}',
                              f'`{f}` объявлен в типе, но не назван в таблице обоснований '
                              f'§10.1 «Поле · Зачем именно оно · Требование»')
            # снапшот вложения существует только для клиент-безопасного (OUT-48)
            ms = re.search(r'AttachmentSnapshot\s*\{(.*?)\n\}', txt, re.S)
            if not ms:
                self.fail('OUT-ATTACH', rel, '[вакуум] тип `AttachmentSnapshot` не объявлен')
            elif not re.search(r'visibilityClassification\s*:\s*"clientSafe"\s*;', ms.group(1)):
                self.emit('OUT-ATTACH', rel, txt[:ms.start()].count('\n') + 1,
                          'OUT-ATTACH:snapshot-union',
                          '`AttachmentSnapshot.visibilityClassification` перестал быть union '
                          'из одного значения `"clientSafe"` — у внутреннего файла появился '
                          'путь в снапшот (OUT-48)')

        # (4) OUT-R07: матрица блокировки называет ВСЕ пять клиентских профилей.
        # Ослабление до трёх прошло — это прямое ослабление R-07.
        n_client = len(clients or ())
        mm = re.search(r'^\|\s*Категория при[^\n]*\n\|[-\s|]+\|\n((?:\|[^\n]*\n)+)', txt, re.M)
        if not mm:
            self.fail('OUT-R07', rel, '[вакуум] матрица блокировки §7.2 не распознана — '
                                      'R-07 не проверяется')
        else:
            base = txt[:mm.start(1)].count('\n') + 1
            hard = ('compliance', 'scope', 'financial', 'stale', 'privacy', 'security')
            got_rows = 0
            for k, row in enumerate(mm.group(1).strip().split('\n')):
                cells = [c.strip() for c in row.strip('|').split('|')]
                if len(cells) < 2:
                    continue
                cats = set(re.findall(r'`([a-zA-Z]+)`', cells[0]))
                if not (cats & set(hard)):
                    continue
                got_rows += 1
                mw = re.search(r'(?:ровно\s+)?(?:все\s+)?([а-яё]+)\s+клиентск', cells[1])
                if not mw:
                    self.emit('OUT-R07', rel, base + k, 'OUT-R07:' + '+'.join(sorted(cats)),
                              f'строка матрицы блокировки «{cells[0][:40]}» не называет число '
                              f'заблокированных клиентских профилей — R-07 требует все {n_client}')
                    continue
                got = self.RU_NUM.get(mw.group(1).lower())
                if got != n_client:
                    self.emit('OUT-R07', rel, base + k, 'OUT-R07:' + '+'.join(sorted(cats)),
                              f'строка «{cells[0][:40]}» блокирует {mw.group(1)} ({got}) '
                              f'клиентских профилей вместо всех {n_client} — прямое ослабление '
                              f'R-07 (открытый Material Blocker блокирует все клиентские '
                              f'профили без исключения)')
            if got_rows < 3:
                self.fail('OUT-R07', rel, f'[вакуум] в матрице §7.2 найдено {got_rows} строк '
                                          f'жёстких категорий из ожидаемых ≥ 3 '
                                          f'(compliance/scope/financial · stale · privacy/security)')

        # (5) OUT-POLICY: `allowed = false` → `serialization = "omit"`.
        # Разрыв связки означает, что запрещённое поле вправе сериализоваться.
        # Правила формы §5.1 и инвариант OUT-10 проверяются РАЗДЕЛЬНО: связка
        # формулируется в обоих местах, и глобальный поиск по файлу означал,
        # что порча одного из двух покрывается вторым.
        ms51 = re.search(r'^###\s*5\.1\.(.*?)(?=^###\s)', txt, re.S | re.M)
        if not ms51:
            self.fail('OUT-POLICY', rel, '[вакуум] раздел §5.1 «Тип политики» не найден — '
                                         'правила формы FieldOutputPolicy не проверяются')
        else:
            s51 = ms51.group(1)
            ln51 = txt[:ms51.start()].count('\n') + 1
            rx_bind = re.compile(r'`allowed\s*=\s*false`[^\n]{0,60}?требует[^\n]{0,60}?'
                                 r'`serialization\s*=\s*"omit"`')
            if not rx_bind.search(s51):
                self.emit('OUT-POLICY', rel, ln51, 'OUT-POLICY:§5.1-false→omit',
                          '§5.1 не связывает `allowed = false` с `serialization = "omit"`: '
                          'без этой связки запрещённое политикой поле вправе '
                          'сериализоваться (SECURITY-001)')
            if not re.search(r'`allowed\s*=\s*true`[^\n]{0,40}запрещает[^\n]{0,20}`?omit`?', s51):
                self.emit('OUT-POLICY', rel, ln51, 'OUT-POLICY:§5.1-true≠omit',
                          '§5.1 не запрещает `omit` при `allowed = true` — политика вправе '
                          'молча опустить разрешённое поле')
        mi = re.search(r'\*\*OUT-10\.\*\*([^\n]*)', txt)
        if not mi:
            self.fail('OUT-POLICY', rel, '[вакуум] инвариант OUT-10 не найден')
        elif not ('allowed = false' in mi.group(1) and '"omit"' in mi.group(1)):
            self.emit('OUT-POLICY', rel, txt[:mi.start()].count('\n') + 1,
                      'OUT-POLICY:OUT-10',
                      'OUT-10 перестал называть обе стороны связки '
                      '(`allowed = false` → `serialization = "omit"`)')
        # проекция физически не несёт `omit`
        if not re.search(r'"omit"\s*сюда\s*не\s*попадает|//\s*"omit"', txt):
            self.emit('OUT-POLICY', rel, 1, 'OUT-POLICY:projection-omit',
                      '`ProjectedField.serialization` не объявляет, что `"omit"` в проекцию '
                      'не попадает — опущенное поле снова получает представимое состояние')

        # (6) OUT-PROFILE: канонические имена профилей (enum читается из модели).
        # Вакуум enum'а гасит ТОЛЬКО этот блок: остальные классы независимы —
        # изоляция зависимых проверок, пункт 10 вердикта.
        if profiles:
            vocab = set(profiles) | set(PROFILE_VOCAB_OK)
            fx = self.read('docs/audit/synthetic-fixtures.md') or ''
            for name in sorted(set(re.findall(r'\b((?:client|internal)[A-Z][A-Za-z]*)', txt))):
                if name in vocab:
                    continue
                ln = next((i for i, l in enumerate(rows, 1) if name in l), 1)
                extra = ''
                if name not in fx:
                    extra = (f' Заявление о фикстуре устарело: `synthetic-fixtures.md` имени '
                             f'`{name}` не содержит — сверять надо с файлом, а не с памятью.')
                self.emit('OUT-PROFILE', rel, ln, f'OUT-PROFILE:{name}',
                          f'имя `{name}` не является каноническим профилем выдачи '
                          f'(data-model.md §5.11 объявляет {", ".join(profiles)}): '
                          f'по неканоническому имени не сопоставляется ни одна политика '
                          f'видимости.{extra}')
            for p in clients:
                if not re.search(r'###\s*3\.\d+\.\s*`?' + p, txt):
                    self.emit('OUT-PROFILE', rel, 1, f'OUT-PROFILE:missing-{p}',
                              f'§3 «клиентские профили поимённо» не содержит секции профиля '
                              f'`{p}` — профиль без описания политики не имеет')
            # Реестр профилей §2 обязан содержать РОВНО ОДНУ строку на каждое
            # значение enum'а: удаление строки означает профиль без объявленной
            # аудитории, интерактивности и гейта — то есть без политики.
            reg = self._rows_by_header(txt, r'Профиль\s*\|\s*Аудитория')
            if reg is None:
                self.fail('OUT-PROFILE', rel, '[вакуум] таблица реестра профилей §2 '
                                              '(«Профиль · Аудитория · …») не распознана')
            else:
                for p in profiles:
                    if not re.search(r'^\|\s*`' + p + r'`\s*\|', txt, re.M):
                        self.emit('OUT-PROFILE', rel, 1, f'OUT-PROFILE:noreg-{p}',
                                  f'реестр профилей §2 не содержит строки профиля `{p}`, '
                                  f'объявленного enum\'ом data-model.md. Профиль без '
                                  f'объявленной аудитории, интерактивности и гейта политики '
                                  f'не имеет')
                if reg != len(profiles):
                    self.emit('OUT-PROFILE', rel, 1, 'OUT-PROFILE:regcount',
                              f'реестр профилей §2 содержит {reg} строк при {len(profiles)} '
                              f'значениях enum\'а — лишняя строка описывает профиль, '
                              f'которого в модели нет')

        # (6-bis) ГРАНИЦА `allowedActionIds` каждого клиентского профиля (R-06).
        # M36/M37 второй независимой атаки: списки двух профилей вывернуты
        # наизнанку — у наблюдения он стал непустым, у конфигурирования пустым.
        # Прежний `OUT-PROFILE` проверял СЛОВАРЬ ИМЁН и число строк реестра,
        # то есть присутствие профиля, а не его политику; обе противоположные
        # границы проходили. Это ядро MODE-001: разница между «показываем» и
        # «конфигурируем» либо является свойством схемы, либо снова становится
        # вопросом подписи.
        for p, (want, need_words, why) in sorted(OUT_ACTION_POLICY.items()):
            ms = re.search(r'^###\s*3\.\d+\.\s*`?' + p + r'`?(.*?)(?=^###\s|^---|\Z)',
                           txt, re.S | re.M)
            if not ms:
                self.fail('OUT-PROFILE', rel, f'[вакуум] секция профиля `{p}` в §3 не '
                                              f'распознана — граница `allowedActionIds` '
                                              f'не проверяется')
                continue
            body, ln = ms.group(1), txt[:ms.start()].count('\n') + 1
            frags = [m.group(0) for m in re.finditer(r'[^\n]*`allowedActionIds`[^\n]*', body)]
            if not frags:
                self.emit('OUT-PROFILE', rel, ln, f'OUT-PROFILE:actions-silent-{p}',
                          f'секция профиля `{p}` не называет `allowedActionIds` вовсе. '
                          f'R-06 требует, чтобы список действий был свойством профиля: '
                          f'{why}')
                continue
            # Классификация лексическая и в один проход: «непуст» проверяется
            # ПЕРВЫМ, иначе подстрока «пуст» внутри него даёт обратный ответ.
            joined = ' '.join(frags)
            if re.search(r'непуст', joined, re.I):
                got = 'nonempty'
            elif re.search(r'(?<!не)пуст', joined, re.I):
                got = 'empty'
            else:
                got = None
            if got is None:
                self.emit('OUT-PROFILE', rel, ln, f'OUT-PROFILE:actions-unstated-{p}',
                          f'`{p}.allowedActionIds` упомянут, но граница списка не '
                          f'названа: ни «пуст», ни «непуст». {why}')
            elif got != want:
                self.emit('OUT-PROFILE', rel, ln, f'OUT-PROFILE:actions-{p}:{got}',
                          f'`{p}.allowedActionIds` объявлен как «{got}», канонически '
                          f'«{want}» (R-06). {why}')
            else:
                for w in need_words:
                    if not re.search(w, joined, re.I):
                        self.emit('OUT-PROFILE', rel, ln,
                                  f'OUT-PROFILE:actions-{p}:no-{w[:14]}',
                                  f'`{p}.allowedActionIds` больше не характеризуется как '
                                  f'«{w}…»: граница названа верно, но свойство, делающее её '
                                  f'проверяемой, снято. {why}')

        # (6a) OUT-SEND, содержание условий: «шесть строк» — не то же, что
        # «шесть верных условий» (T23, T25). Проверяется ПРЕДИКАТ каждой
        # названной строки и порядок стадий §9.1.
        cond_need = (
            (1, r'получател', r'\bto\b',        'условие получателей обязано требовать ≥ 1 `to`'),
            (2, r'\bтел\w+',  r'preflight',     'условие тела обязано связывать его с preflight'),
            (3, r'локал',     r'missingKeys',   'условие локали обязано требовать пустых `missingKeys`'),
            (4, r'вложени',   r'clientSafe',    'условие вложений обязано требовать `clientSafe` '
                                                '— `internalOnly` в клиентском письме недопустим '
                                                '(EMAIL-002, R-17)'),
            (5, r'preflight', r'resultHash',    'условие preflight обязано требовать воспроизведения '
                                                '`resultHash` (§6.4)'),
            (6, r'разрешен',  r'сервер',        'условие авторизации обязано называть серверную '
                                                'проверку (R-16)'),
        )
        m93 = re.search(r'^###\s*9\.3\.(.*?)(?=^###\s|\Z)', txt, re.S | re.M)
        if not m93:
            self.fail('OUT-SEND', rel, '[вакуум] раздел §9.3 не найден — предикаты условий '
                                       '`sendEnabled` не проверяются')
        else:
            base93 = txt[:m93.start(1)].count('\n') + 1
            cells93 = {}
            for k, line in enumerate(m93.group(1).split('\n')):
                mr = re.match(r'^\|\s*(\d+)\s*\|(.*)$', line)
                if mr:
                    cells93[int(mr.group(1))] = (base93 + k, mr.group(2))
            for num, subj, pred, why in cond_need:
                if num not in cells93:
                    continue          # число строк уже проверено выше
                ln93, body93 = cells93[num]
                if not re.search(subj, body93, re.I):
                    self.emit('OUT-SEND', rel, ln93, f'OUT-SEND:cond{num}-subject',
                              f'условие №{num} §9.3 больше не о том, о чём было: в строке нет '
                              f'предмета «{subj}» — порядок условий переставлен либо условие '
                              f'подменено')
                elif not re.search(pred, body93, re.I):
                    self.emit('OUT-SEND', rel, ln93, f'OUT-SEND:cond{num}-predicate',
                              f'условие №{num} §9.3 не содержит обязательного предиката '
                              f'`{pred}`: {why}')
        # порядок стадий письма (§9.1) против OUT-34 и против README
        STAGES = ('Compose', 'Preflight', 'Confirm & Send', 'Delivery status')
        chain = ' → '.join(STAGES)
        if chain not in txt:
            found = re.search(r'`?(Compose[^\n`]{0,80}Delivery status)`?', txt)
            self.emit('OUT-SEND', rel,
                      txt[:found.start()].count('\n') + 1 if found else 1,
                      'OUT-SEND:stage-order',
                      f'порядок стадий письма не равен каноническому «{chain}» '
                      f'(найдено: «{found.group(1) if found else "ничего"}»). '
                      f'R-09/EMAIL-001: `Confirm & Send` не может стоять перед `Preflight` — '
                      f'иначе подтверждение относится к непроверенному черновику')

        # (6b) OUT-POLICY, импликация разрешений: `permission ∧ ¬allowed ⇒ omit`.
        # Связка «ни одно разрешение не переопределяет allowed = false» (R-16,
        # OUT-11) не проверялась вовсе — T33.
        if ms51:
            if not re.search(r'ни\s+одно\s+разрешение\s+не\s+переопределяет'
                             r'[^\n]{0,30}`allowed\s*=\s*false`', ms51.group(1)):
                self.emit('OUT-POLICY', rel, ln51, 'OUT-POLICY:permission-override',
                          '§5.1 больше не утверждает, что ни одно разрешение не '
                          'переопределяет `allowed = false`. Авторизация и видимость '
                          'независимы (R-16): разрешение, способное открыть запрещённое '
                          'политикой поле, превращает allowlist в рекомендацию')
        mi11 = re.search(r'\*\*OUT-11\.\*\*([^\n]*)', txt)
        if not mi11:
            self.fail('OUT-POLICY', rel, '[вакуум] инвариант OUT-11 не найден')
        elif not re.search(r'ни\s+одно\s+разрешение\s+не\s+переопределяет', mi11.group(1)):
            self.emit('OUT-POLICY', rel, txt[:mi11.start()].count('\n') + 1,
                      'OUT-POLICY:OUT-11',
                      'OUT-11 перестал требовать независимости авторизации и видимости')

        # (6c) OUT-DELIVERY: приоритет исходов доставки выводится ИЗ ТАБЛИЦЫ
        # и сверяется с OUT-39. Прежде правильная фраза инварианта маскировала
        # испорченное определение (T24) — «согласованность дублированных
        # нормативных утверждений», класс 7 вердикта.
        CANON = ('Beschwerde', 'Unzustellbar', 'Zugestellt', 'Gesendet')
        order = [m.group(1) for m in re.finditer(
            r'^\|[^|]*\|\s*`?(' + '|'.join(CANON) + r')`?\s*\|', txt, re.M)]
        if len(order) < len(CANON):
            self.fail('OUT-DELIVERY', rel, f'[вакуум] таблица вывода исхода доставки не '
                                           f'распознана (найдено {len(order)} строк из '
                                           f'{len(CANON)}) — precedence не проверяется')
        else:
            if tuple(order[:len(CANON)]) != CANON:
                ln = next((i for i, l in enumerate(rows, 1) if order[0] in l), 1)
                self.emit('OUT-DELIVERY', rel, ln, 'OUT-DELIVERY:order',
                          f'приоритет исходов доставки в таблице — {order[:len(CANON)]}, '
                          f'канонический — {list(CANON)}. `delivered` выше `complained` '
                          f'означает, что жалоба получателя перестаёт быть текущим исходом '
                          f'(EMAIL-007/EMAIL-008)')
            mi39 = re.search(r'\*\*OUT-39\.\*\*([^\n]*(?:\n(?!\d+\.)[^\n]*)*)', txt)
            if not mi39:
                self.fail('OUT-DELIVERY', rel, '[вакуум] инвариант OUT-39 не найден')
            else:
                inv_order = tuple(x for x in re.findall('|'.join(CANON), mi39.group(1)))
                if inv_order[:len(CANON)] != tuple(order[:len(CANON)]):
                    self.emit('OUT-DELIVERY', rel, txt[:mi39.start()].count('\n') + 1,
                              'OUT-DELIVERY:invariant-vs-table',
                              f'OUT-39 называет порядок {list(inv_order[:len(CANON)])}, '
                              f'таблица §9.6 даёт {order[:len(CANON)]} — верная копия '
                              f'инварианта маскирует испорченное определение')
        # инварианты статусов попытки: требует/запрещает по каждому статусу
        STATUS = {
            'queued':             (set(), {'finishedAt', 'providerMessageId', 'failureCode'}),
            'sending':            (set(), {'finishedAt', 'providerMessageId', 'failureCode'}),
            'acceptedByProvider': ({'finishedAt', 'providerMessageId'}, {'failureCode'}),
            'failed':             ({'finishedAt', 'failureCode'}, {'providerMessageId'}),
        }
        seen_status = 0
        for st, (need, ban) in STATUS.items():
            mr = re.search(r'^\|\s*`' + st + r'`\s*\|([^|]*)\|([^|]*)\|', txt, re.M)
            if not mr:
                continue
            seen_status += 1
            ln = txt[:mr.start()].count('\n') + 1
            got_need = set(re.findall(r'`([a-zA-Z]+)`', mr.group(1)))
            got_ban = set(re.findall(r'`([a-zA-Z]+)`', mr.group(2)))
            if got_need != need or got_ban != ban:
                self.emit('OUT-DELIVERY', rel, ln, f'OUT-DELIVERY:status-{st}',
                          f'`{st}`: требует {sorted(got_need) or "—"} / запрещает '
                          f'{sorted(got_ban) or "—"}; канонически требует {sorted(need) or "—"} '
                          f'/ запрещает {sorted(ban) or "—"}. Статус, требующий '
                          f'`providerMessageId` у неудачи, объявляет провал принятым')
        if seen_status != len(STATUS):
            self.fail('OUT-DELIVERY', rel, f'[вакуум] таблица инвариантов `DeliveryAttempt` '
                                           f'распознана на {seen_status} из {len(STATUS)} '
                                           f'статусов')

        # (6d) OUT-LOCALE: гейт локали — предикаты, а не наличие раздела (T34).
        m83 = re.search(r'^###\s*8\.3\.(.*?)(?=^###\s|^---|\Z)', txt, re.S | re.M)
        if not m83:
            self.fail('OUT-LOCALE', rel, '[вакуум] раздел §8.3 «Правило» локали не найден — '
                                         'LOCALE-001 не проверяется')
        else:
            s83, ln83 = m83.group(1), txt[:m83.start()].count('\n') + 1
            for pat, why in (
                (r'пуст\w*\s*`?missingKeys`?|`missingKeys`[^\n]{0,30}пуст',
                 'клиентская выдача обязана требовать ПУСТЫХ `missingKeys`'),
                (r'`unapprovedKeys`',
                 'клиентская выдача обязана требовать пустых `unapprovedKeys`'),
                (r'целиком\s+в\s+одной\s+локали|одной\s+локали\s+или\s+не\s+генерируется',
                 'артефакт генерируется целиком в одной локали или не генерируется'),
                (r'[Мм]олчаливый\s+фолбэк[^\n]{0,200}?(?:запрещ|не\s+существ|недостиж)|'
                 r'(?:запрещ|недостиж)\w*[^\n]{0,80}?молчаливый\s+фолбэк',
                 'молчаливый фолбэк на немецкий обязан быть запрещён (R-08)')):
                if not re.search(pat, s83):
                    self.emit('OUT-LOCALE', rel, ln83, f'OUT-LOCALE:{pat[:24]}',
                              f'§8.3 не содержит обязательного предиката: {why}. '
                              f'Смешанный по языку артефакт не является состоянием системы, '
                              f'а не «не рекомендуется» (LOCALE-001)')
            if re.search(r'непуст\w*\s*`?missingKeys`?[^\n]{0,40}(?:допус|разреш|вправе)', s83):
                self.emit('OUT-LOCALE', rel, ln83, 'OUT-LOCALE:nonempty-allowed',
                          '§8.3 разрешает клиентскую выдачу при непустых `missingKeys` — '
                          'прямое снятие гейта локали (LOCALE-001)')

        # (7) OUT-MONEY: денежные и удельные спесимены §7.3/§9.7 против фикстуры
        # в Decimal. Порча округления (`≈ 5.824.000` при точном `5.822.936,00`)
        # прошла: в файле не было ни одной проверки арифметики.
        self._specimens('OUT-MONEY', rel, txt)

        # (8) SCHED-D17: десятичный месяц при целом календарном интервале
        self._sched_d17(rel, txt)

        # (9) OUT-COUNT: числительное в прозе против числа строк таблицы,
        # которую оно описывает. Собственные мутации показали, что «семь
        # значений OutputProfile», «шесть групп содержимого вердикта» и «шесть
        # языковых атрибутов» не сверялись ни с чем: удаление строки из таблицы
        # проходило, как и правка самого числительного.
        # Источник факта назван для КАЖДОГО утверждения отдельно: таблица
        # опознаётся по своей шапке, а не «ближайшая ниже». Общая эвристика
        # близости давала ложные срабатывания на перекрёстных ссылках и на
        # списках-абзацах — то есть ровно тот шум, из-за которого проверку
        # потом отключают.
        counted = [
            (r'`OutputProfile`\s*—\s*([А-Яа-яЁё]+)\s+значени', 'значения OutputProfile',
             len(profiles) if profiles else None,
             'enum `type OutputProfile` в data-model.md §5.11'),
            (r'([А-Яа-яЁё]+)\s+из\s+них\s+клиентски', 'клиентские профили',
             len(clients) if clients else None,
             'имена с префиксом `client` в том же enum'),
            (r'перечисляет\s+([А-Яа-яЁё]+)\s+групп\w*\s+содержимого',
             'группы вердикта preflight',
             self._rows_by_header(txt, r'Группа\s+содержимого'),
             'таблица §6.5 «Группа содержимого · Откуда выводится»'),
            (r'([А-Яа-яЁё]+)\s+языковых\s+атрибут', 'языковые атрибуты локали',
             self._rows_by_header(txt, r'Атрибут\s*\|\s*Кому\s+принадлежит'),
             'таблица §8.1 «Атрибут · Кому принадлежит»'),
        ]
        for claim_rx, what, fact, src in counted:
            hits = [(m, self.RU_NUM.get(m.group(1).lower()))
                    for m in re.finditer(claim_rx, txt)]
            hits = [(m, d) for m, d in hits if d is not None]
            if not hits:
                continue
            if fact is None:
                self.fail('OUT-COUNT', rel, f'[вакуум] утверждение «{what}» есть, а источник '
                                            f'({src}) не прочитан — число заявляется, '
                                            f'а не выводится')
                continue
            for m, declared in hits:
                ln = txt[:m.start()].count('\n') + 1
                if declared != fact:
                    self.emit('OUT-COUNT', rel, ln, f'OUT-COUNT:{what}:{declared}',
                              f'проза называет {m.group(1)} ({declared}) — {what}; '
                              f'источник ({src}) даёт {fact}. Сводное число, не выводимое '
                              f'из состава, верно ровно до следующей правки')
        # (10) OUT-EXCL: перечень семейств, исключённых во всех клиентских
        # профилях (§5.4). Удаление строки `Interne Bezugsgröße` прошло —
        # а это прямое снятие R-11 из политики полей.
        m54 = re.search(r'^###\s*5\.4\.(.*?)(?=^###\s|^---|\Z)', txt, re.S | re.M)
        if not m54:
            self.fail('OUT-EXCL', rel, '[вакуум] раздел §5.4 «Семейства полей, исключённые '
                                       'во всех клиентских профилях» не найден')
        else:
            s54, ln54 = m54.group(1), txt[:m54.start()].count('\n') + 1
            for need, why in (
                    (r'марж', 'маржа и база скидки (правило 11, DISCOUNT-006)'),
                    (r'KG-700-Modus', '`KG-700-Modus` (правило 11)'),
                    (r'заметк', 'заметки и их синк-состояние (NOTE-006, D-12, правило 34)'),
                    (r'Interne\s+Bezugsgröße', '`Interne Bezugsgröße` (R-11, правило 39)'),
                    (r'reasonCode', '`reasonCode`/`policyVersion` проблем валидации (R-17)'),
                    (r'preview', 'preview-прогоны и их числа (§6.3)'),
                    (r'устаревш\w+\s+authoritative', 'устаревший прогон (STALE-001, R-18)')):
                if not re.search(need, s54, re.I):
                    self.emit('OUT-EXCL', rel, ln54, f'OUT-EXCL:{need[:20]}',
                              f'§5.4 больше не исключает из клиентских профилей: {why}. '
                              f'Перечень исключений — это и есть allowlist наоборот: '
                              f'исчезнувшая строка означает, что поле поедет в клиентский PDF')

        # (11) OUT-HASH: круговой хеш. `evaluationContextHash` НЕ включает
        # результаты `ValidationIssue`, иначе проблемы находятся оценкой
        # контекста, который они же определяют. Снятие отрицания прошло.
        m64 = re.search(r'^###\s*6\.4\.(.*?)(?=^###\s|^---|\Z)', txt, re.S | re.M)
        mh = re.search(r'`evaluationContextHash`([^\n]*(?:\n(?!\n)[^\n]*){0,4})',
                       m64.group(1)) if m64 else None
        if not m64:
            self.fail('OUT-HASH', rel, '[вакуум] раздел §6.4 «Два хеша и повторная оценка» '
                                       'не найден — круговой хеш не проверяется')
        elif not mh:
            self.fail('OUT-HASH', rel, '[вакуум] `evaluationContextHash` в §6.4 не найден — '
                                       'круговой хеш не проверяется')
        else:
            frag = mh.group(1)
            lnh = txt[:m64.start(1)].count('\n') + m64.group(1)[:mh.start()].count('\n') + 1
            if not re.search(r'не\s+включает', frag):
                self.emit('OUT-HASH', rel, lnh, 'OUT-HASH:circular',
                          '§6.4 больше не утверждает, что `evaluationContextHash` НЕ включает '
                          'ID и результаты `ValidationIssue`. Хеш, включающий их, становится '
                          'круговым: проблемы находятся оценкой контекста, который они же '
                          'определяли бы, и повторная оценка перестаёт что-либо доказывать')

        # (12) OUT-BINDING и (13) OUT-SESSION — классы, которых не существовало.
        self.check_out_binding(rel, txt)
        self.check_out_session(rel, txt)

    # -- 3b-bis. Кардинальность привязок расчёта к выдаче ---------------------
    def check_out_binding(self, rel, txt):
        """`OUT-BINDING`: сколько прогонов отвечает за числа клиентской выдачи.

        Класса не существовало, и M38/M39 прошли именно поэтому. Важна не
        сложность разбора, а ГДЕ ЛЕЖИТ КАНОН: обе мутации испортили таблицу
        §6.2 и соответствующий инвариант OUT-19/20 СОГЛАСОВАННО. Сверка двух
        копий правила между собой дала бы зелёный свет — копии согласны, обе
        неверны. Поэтому канон объявлен в `OUT_BINDING_TABLE` и
        `OUT_BINDING_INVARIANTS` (в инструменте), и каждая копия правила
        сверяется с ним ПО ОТДЕЛЬНОСТИ, а не с соседней копией.
        """
        m = re.search(r'^\|\s*Профиль\s*\|\s*primaryAuthoritative[^\n]*\|\n'
                      r'\|[-:\s|]+\|\n((?:\|[^\n]*\|\n)+)', txt, re.M)
        if not m:
            self.fail('OUT-BINDING', rel, '[вакуум] таблица §6.2 «Правила привязок по '
                                          'профилям» не распознана — кардинальность '
                                          'привязок не проверяется')
        else:
            base = txt[:m.start(1)].count('\n') + 1
            cols = ('primaryAuthoritative', 'preview', 'comparisonAuthoritative')
            seen_groups, seen_profiles = set(), set()
            for k, row in enumerate(m.group(1).strip().split('\n')):
                cells = [c.strip() for c in row.strip('|').split('|')]
                if len(cells) < 2:
                    continue
                names = set(re.findall(r'`([A-Za-z]+)`', cells[0]))
                group = next((g for g, members in OUT_BINDING_GROUPS.items()
                              if names and names <= set(members)), None)
                if group is None:
                    self.emit('OUT-BINDING', rel, base + k,
                              'OUT-BINDING:row:' + ('+'.join(sorted(names)) or 'пусто'),
                              f'строка §6.2 «{cells[0][:60]}» не соответствует ни одной '
                              f'группе профилей: группы объявлены как '
                              f'{ {g: v for g, v in OUT_BINDING_GROUPS.items()} }. '
                              f'Профиль, попавший не в свою строку, получает чужую '
                              f'кардинальность привязок')
                    continue
                seen_groups.add(group)
                seen_profiles |= names
                for i, col in enumerate(cols, 1):
                    canon = OUT_BINDING_TABLE.get((group, col))
                    if canon is None:
                        continue          # comparisonAuthoritative каноном не связан
                    want_bind, want_run = canon
                    cell = cells[i] if i < len(cells) else ''
                    got = card_parse_cell(cell)
                    if got != want_bind:
                        said = (f'даёт {card_fmt(got)} привязок' if got is not None
                                else 'не называет границу числа привязок')
                        self.emit('OUT-BINDING', rel, base + k,
                                  f'OUT-BINDING:{group}:{col}:{card_fmt(got)}',
                                  f'§6.2, {group} · `{col}`: ячейка «{cell[:44]}» {said}, '
                                  f'канонически {card_fmt(want_bind)}. Кардинальность '
                                  f'привязок определяет, какой прогон отвечает за числа '
                                  f'выдачи (§6.2, OUT-18…22)')
                    if want_run is not None:
                        tail = ','.join(re.sub(r'[*_`]', '', cell).split(',')[1:])
                        got_run = card_parse(tail) if 'Run' in tail else None
                        if got_run != want_run:
                            said = (f'равно {card_fmt(got_run)}' if got_run is not None
                                    else 'не названо')
                            self.emit('OUT-BINDING', rel, base + k,
                                      f'OUT-BINDING:{group}:{col}:runid:{card_fmt(got_run)}',
                                      f'§6.2, {group} · `{col}`: число различных Run ID в '
                                      f'ячейке {said}, канонически {card_fmt(want_run)}. '
                                      f'Две версии прогона в одной выдаче дают два разных '
                                      f'итога под одной подписью')
            for g in OUT_BINDING_GROUPS:
                if g not in seen_groups:
                    self.emit('OUT-BINDING', rel, base, f'OUT-BINDING:norow-{g}',
                              f'в таблице §6.2 нет строки группы `{g}` '
                              f'({", ".join(OUT_BINDING_GROUPS[g])}) — профиль без '
                              f'объявленной кардинальности привязок вправе '
                              f'сериализовать любой прогон')
            # Присутствие ГРУППЫ не означает присутствия каждого профиля: строка
            # группы `client` перечисляет четыре имени, и исчезновение одного из
            # них оставляет строку на месте. Профиль, выпавший из таблицы,
            # кардинальности привязок не имеет вовсе.
            for g, members in OUT_BINDING_GROUPS.items():
                for p in members:
                    if p not in seen_profiles:
                        self.emit('OUT-BINDING', rel, base, f'OUT-BINDING:noprofile-{p}',
                                  f'профиль `{p}` не назван ни в одной строке таблицы '
                                  f'§6.2 — для него не объявлено ни числа '
                                  f'authoritative-привязок, ни запрета preview, и '
                                  f'проверить выдачу этого профиля нечем')
        # Та же кардинальность, объявленная инвариантами §14. Проверяется против
        # ТОГО ЖЕ канона, а не против таблицы: иначе согласованная порча обеих
        # копий остаётся зелёной — ровно то, что показали M38/M39.
        for n, anchor, canon, unit, why in OUT_BINDING_INVARIANTS:
            mi = re.search(r'\*\*OUT-%d\.\*\*([^\n]*)' % n, txt)
            if not mi:
                self.fail('OUT-BINDING', rel, f'[вакуум] инвариант OUT-{n} не найден — '
                                              f'кардинальность «{unit}» не проверяется')
                continue
            got, clause = card_in_clause(mi.group(1), anchor)
            ln = txt[:mi.start()].count('\n') + 1
            if got != canon:
                said = (f'объявляет {card_fmt(got)}' if got is not None
                        else 'не называет границу')
                self.emit('OUT-BINDING', rel, ln,
                          f'OUT-BINDING:OUT-{n}:{anchor[:18]}:{card_fmt(got)}',
                          f'OUT-{n} {said} — {unit}; канонически {card_fmt(canon)}. '
                          f'{why}. Придаточное: '
                          f'«{(clause or mi.group(1).strip())[:80]}»')

    # -- 3b-ter. Жизненный цикл открытой клиентской сессии --------------------
    def check_out_session(self, rel, txt):
        """`OUT-SESSION`: сессия клиентского режима как ОДНА машина состояний.

        M40/M41/M42 сняли по одной опоре из трёх — единственность текущего
        вердикта, событие ревалидации, неизменность исторического указателя —
        и каждая порча по отдельности читается как правка прозы. Прежний
        `OUT-R07` знал только матрицу блокировки §7.2 и не заходил в §12 вовсе,
        хотя именно ревалидация является несущей конструкцией принятого
        прочтения R-07 (§1.4): без третьего момента оценки система узнаёт о
        новом блокере уже после разговора.
        """
        # (1) Тип сессии: два указателя, и `current` — ЕДИНСТВЕННЫЙ.
        mt = re.search(r'ClientModeSession\s*\{(.*?)\n\}', txt, re.S)
        if not mt:
            self.fail('OUT-SESSION', rel, '[вакуум] тип `ClientModeSession` не объявлен — '
                                          'жизненный цикл открытой сессии не проверяется')
        else:
            body, lnt = mt.group(1), txt[:mt.start()].count('\n') + 1
            decl = {}
            for mf in re.finditer(r'^\s*([a-z][A-Za-z0-9]*)\??\s*:\s*([^;\n]+);', body, re.M):
                decl[mf.group(1)] = mf.group(2).strip()
            for f, (kind, role) in sorted(OUT_SESSION_FIELDS.items()):
                if f not in decl:
                    self.emit('OUT-SESSION', rel, lnt, f'OUT-SESSION:field-{f}',
                              f'`ClientModeSession` не несёт `{f}` — {role}. Сессия без '
                              f'этого поля не отвечает на вопрос §1.4 «что мы знали, '
                              f'когда открывали экран заказчику»')
                    continue
                if kind == 'single' and re.search(r'\[\s*\]|\bArray\s*<|\bSet\s*<', decl[f]):
                    self.emit('OUT-SESSION', rel, lnt, f'OUT-SESSION:plural-{f}',
                              f'`{f}: {decl[f]}` — массив там, где обязан быть '
                              f'ЕДИНСТВЕННЫЙ указатель ({role}). Несколько одновременно '
                              f'действующих вердиктов означают, что состав проекции '
                              f'зависит от того, какой из них прочитан первым: '
                              f'спорное значение снова вправе стоять в роли '
                              f'подтверждённого (MODE-001, §12.1)')
            # Проза §12.1 обязана объяснять РАЗДЕЛЕНИЕ ролей, а не только его
            # иметь: «один указатель на две роли» — это и есть дефект.
            m121 = re.search(r'`entryPreflightResultId`[^\n]*исторический[^\n]*', txt)
            if not m121:
                self.emit('OUT-SESSION', rel, lnt, 'OUT-SESSION:entry-historical',
                          '§12.1 больше не называет `entryPreflightResultId` историческим '
                          'фактом. Указатель, про который не сказано, что он не '
                          'обновляется, обновят: журнал перестанет отвечать, с каким '
                          'вердиктом человек вошёл')
            elif not re.search(r'не\s+обновля\w*\s+никогда|никогда\s+не\s+обновля', m121.group(0)):
                self.emit('OUT-SESSION', rel, lnt, 'OUT-SESSION:entry-mutable',
                          '§12.1 называет `entryPreflightResultId` историческим, но не '
                          'запрещает его обновление явно — «исторический» без запрета '
                          'является пожеланием')

        # (2) §12.1.1: четыре триггера, и они перечислены, а не «по изменению».
        m1211 = re.search(r'^####\s*12\.1\.1\.(.*?)(?=^###\s|^##\s|\Z)', txt, re.S | re.M)
        inv63 = re.search(r'\*\*OUT-63\.\*\*([^\n]*(?:\n(?!\d+\.)[^\n]*)*)', txt)
        if not m1211:
            self.fail('OUT-SESSION', rel, '[вакуум] раздел §12.1.1 «Третий момент оценки» '
                                          'не найден — триггеры ревалидации не проверяются')
        if not inv63:
            self.fail('OUT-SESSION', rel, '[вакуум] инвариант OUT-63 не найден — '
                                          'ревалидация не имеет проверяемого инварианта')
        for src, name in ((m1211, '§12.1.1'), (inv63, 'OUT-63')):
            if not src:
                continue
            frag = src.group(1)
            ln = txt[:src.start()].count('\n') + 1
            for pat, why in OUT_SESSION_TRIGGERS:
                if not re.search(pat, frag, re.I):
                    self.emit('OUT-SESSION', rel, ln,
                              f'OUT-SESSION:trigger:{name}:{pat[:22]}',
                              f'{name} не называет триггер ревалидации: {why}. Триггеры '
                              f'перечислены, а не «по изменению чего-либо»: '
                              f'исчезнувший триггер — это блокер, о котором сессия '
                              f'узнаёт только на гейте, то есть после разговора')
        # (3) Механика ревалидации: `current` обновляется, `entry` — НЕТ.
        for src, name in ((m1211, '§12.1.1'), (inv63, 'OUT-63')):
            if not src:
                continue
            frag, ln = src.group(1), txt[:src.start()].count('\n') + 1
            # Окно ДВУСТОРОННЕЕ: §12.1.1 ставит глагол после перечисления
            # («…и `lastRevalidatedAt` обновляются»), OUT-63 — до него
            # («обновляет `currentPreflightResultId`, …»). Односторонний хвост
            # объявил бы верную копию испорченной.
            cur = re.search(r'`currentPreflightResultId`', frag)
            win = frag[max(0, cur.start() - 200):cur.end() + 200] if cur else ''
            if not cur or not re.search(r'обновля\w*|получает\s+нов', win):
                self.emit('OUT-SESSION', rel, ln, f'OUT-SESSION:current-static:{name}',
                          f'{name} не утверждает, что ревалидация ОБНОВЛЯЕТ '
                          f'`currentPreflightResultId`. Действующий вердикт, который не '
                          f'обновляется, оставляет на экране заказчика проекцию по '
                          f'устаревшему вердикту (§1.4, OUT-26)')
            ent = [m.group(0) for m in re.finditer(r'[^\n]*`?entry(?:PreflightResultId|'
                                                   r'PolicyVersion)`?[^\n]*', frag)]
            if not ent:
                self.emit('OUT-SESSION', rel, ln, f'OUT-SESSION:entry-absent:{name}',
                          f'{name} не упоминает `entryPreflightResultId` — про '
                          f'исторический указатель не сказано ничего, и его судьба при '
                          f'ревалидации не определена')
                continue
            joined = ' '.join(ent)
            keeps = re.search(r'остаю\w*|остаётся|остаются|без\s+изменени|'
                              r'не\s+меня\w*|не\s+обновля\w*|как\s+были', joined, re.I)
            writes = re.search(r'перезаписыва\w*|переписыва\w*|'
                               r'(?<!не\s)обновляются|(?<!не\s)обновляется', joined, re.I)
            if writes and not keeps:
                self.emit('OUT-SESSION', rel, ln, f'OUT-SESSION:entry-rewritten:{name}',
                          f'{name} утверждает, что ревалидация ПЕРЕЗАПИСЫВАЕТ '
                          f'исторические `entry`-указатели: «{joined.strip()[:80]}». '
                          f'Тогда сессия теряет ответ на вопрос «что мы знали, когда '
                          f'открывали экран заказчику», а ревалидация из чтения '
                          f'превращается в мутацию истории (§1.4, M-4, OUT-54)')
            elif not keeps:
                self.emit('OUT-SESSION', rel, ln, f'OUT-SESSION:entry-unstated:{name}',
                          f'{name} упоминает `entry`-указатели, но не утверждает их '
                          f'неизменности при ревалидации. Неизменность, о которой не '
                          f'сказано, реализована не будет')

        # (4) События журнала §12.2. Ревалидация меняет три поля сессии и состав
        # проекции, поэтому обязана иметь СВОЁ событие (M-4): сессия, в которой
        # блок ушёл из проекции беззвучно, не отличима от сессии, где его не
        # показывали вовсе.
        mev = re.search(r'^\|\s*Событие\s*\|\s*Когда[^\n]*\|\n\|[-:\s|]+\|\n'
                        r'((?:\|[^\n]*\|\n)+)', txt, re.M)
        if not mev:
            self.fail('OUT-SESSION', rel, '[вакуум] таблица событий журнала §12.2 '
                                          '(«Событие · Когда · …») не распознана')
        else:
            base = txt[:mev.start(1)].count('\n') + 1
            rows_ev = mev.group(1).strip().split('\n')
            index = {}
            for k, row in enumerate(rows_ev):
                cells = [c.strip() for c in row.strip('|').split('|')]
                mn = re.search(r'`([\w.]+)`', cells[0]) if cells else None
                if mn:
                    index[mn.group(1)] = (base + k, ' | '.join(cells[1:]))
            for ev, payload_rx, why in OUT_SESSION_EVENTS:
                if ev not in index:
                    self.emit('OUT-SESSION', rel, base, f'OUT-SESSION:event-{ev}',
                              f'журнал §12.2 не содержит строки события `{ev}`: {why}')
                    continue
                lnv, payload = index[ev]
                if not re.search(payload_rx, payload, re.I):
                    self.emit('OUT-SESSION', rel, lnv, f'OUT-SESSION:payload-{ev}',
                              f'событие `{ev}` объявлено, но его полезная нагрузка не '
                              f'несёт обязательного «{payload_rx}»: {why}')
            # Числительное конверта против числа строк той же таблицы: снятие
            # строки события ловится ВТОРЫМ, независимым путём.
            mn = re.search(r'([А-Яа-яЁё]+)\s+перечисленных\s+ниже\s+событий', txt)
            if mn:
                declared = self.RU_NUM.get(mn.group(1).lower())
                if declared is not None and declared != len(index):
                    self.emit('OUT-SESSION', rel, txt[:mn.start()].count('\n') + 1,
                              f'OUT-SESSION:eventcount:{declared}',
                              f'§12.2 называет {mn.group(1)} ({declared}) событий, таблица '
                              f'содержит {len(index)}. Событие, исчезнувшее из таблицы, '
                              f'исчезает из журнала: данные не могут измениться без '
                              f'события (M-4)')

    @staticmethod
    def _rows_by_header(txt, header_rx):
        """Число строк таблицы, опознанной по ШАПКЕ. None — таблицы нет.

        Опора на шапку, а не на близость: шапка называет предмет таблицы и
        меняется только вместе с ним, тогда как «ближайшая ниже таблица»
        зависит от вёрстки абзацев.
        """
        m = re.search(r'^\|[^\n]*' + header_rx + r'[^\n]*\|\n\|[-:\s|]+\|\n'
                      r'((?:\|[^\n]*\|\n)+)', txt, re.M)
        if not m:
            return None
        return len([r for r in m.group(1).strip().split('\n') if r.strip()])

    # -- 3e. Спесимены денег и площадей против фикстуры -----------------------
    RX_MONEY = re.compile(r'(?<![\d.,])(\d{1,3}(?:\.\d{3})+(?:,\d+)?)\s*[  ]?(?:€(?!/)|Euro\b)')
    RX_RATE = re.compile(r'(?<![\d.,])(\d{1,3}(?:\.\d{3})*(?:,\d+)?)\s*[  ]?€/m²')

    def _specimens(self, cls, rel, txt):
        """Каждое денежное и удельное число документа сводится с фикстурой.

        Допустимое множество строится ИЗ `synthetic-fixtures.md` (см. конец
        `_arithmetic`), а не из констант инструмента: иначе проверка сверяла бы
        собственные ожидания с собственными константами. Отсутствие множества
        (фикстура не разобрана) — вакуум, а не молчаливый пропуск.
        """
        if not self.fx:
            self.fail(cls, rel, '[вакуум] величины фикстуры не вычислены — '
                                'сверять спесимены не с чем')
            return
        for i, line in enumerate(txt.split('\n'), 1):
            # Срок и дата завершения — такие же спесимены, как деньги: они
            # уходят клиенту в том же письме. Собственные мутации показали, что
            # ни длительность (`7,283` → `7,285`), ни дата (`19.11.2027` →
            # `19.12.2027`) ни с чем не сверялись.
            # `…?` — усечённая запись точного значения (`7,283333… Monate`):
            # после переписывания README 06.08 цитата точной длительности
            # существовала ТОЛЬКО в этой форме и не попадала под сверку вовсе —
            # selftest показал это неприменимой мутацией, а не пойманной.
            for m in re.finditer(r'(?<![\d,])(\d{1,3}(?:,\d+)?)…?\s*[  ]?Monate', line):
                if de(m.group(1)) not in self.fx['durations']:
                    self.emit(cls, rel, i, f'{cls}:dur:{m.group(1)}',
                              f'длительность {m.group(1)} Monate не сводится ни с одной '
                              f'величиной ScheduleModel фикстуры '
                              f'({", ".join(str(x) for x in sorted(self.fx["durations"]))})')
            for m in re.finditer(r'(?:Fertigstellung|завершения|Abschluss)\s*[:\s]?\s*'
                                 r'(\d{2}\.\d{2}\.\d{4})', line):
                if m.group(1) not in self.fx['dates']:
                    self.emit(cls, rel, i, f'{cls}:date:{m.group(1)}',
                              f'дата завершения {m.group(1)} отсутствует в ScheduleModel '
                              f'фикстуры: подпись длительности обязана стоять рядом с '
                              f'АБСОЛЮТНОЙ датой из модели (D-17, METRIC-004), а не с '
                              f'правдоподобной')
            for m in re.finditer(r'(GK 5 Zeit|GK 4 Zeit|Form MFH|Form Büro|GK 5|GK 4|'
                                 r'EH 55|EH 40)[^\n]{0,30}?(?:×|множител\w+\s*)'
                                 r'(\d,\d+)|×\s*(\d,\d+)\s*\((GK 5 Zeit|GK 4 Zeit|Form MFH|'
                                 r'Form Büro|GK 5|GK 4|EH 55|EH 40)\)', line):
                lbl = m.group(1) or m.group(4)
                val = m.group(2) or m.group(3)
                want = self.fx['factors'].get(lbl)
                if want is not None and de(val) != want:
                    self.emit(cls, rel, i, f'{cls}:factor:{lbl}:{val}',
                              f'множитель драйвера `{lbl}` записан {val}, каталог фикстуры '
                              f'даёт {want}. Стоимостная и срочная таблицы факторов '
                              f'РАЗНЫЕ, и смешение их — та самая ошибка, что завышала '
                              f'Haus B на 100.000 €')
            for rx, pool, what in ((self.RX_RATE, self.fx['rates'], 'удельная величина'),
                                   (self.RX_MONEY, self.fx['exact'] | self.fx['disp'], 'сумма')):
                for m in rx.finditer(line):
                    try:
                        val = de(m.group(1))
                    except Exception:
                        continue
                    if val in pool:
                        continue
                    self.emit(cls, rel, i, f'{cls}:{m.group(1)}',
                              f'{what} {m.group(1)} не сводится ни с одной величиной '
                              f'синтетической фикстуры и её производными (правило проекта 32: '
                              f'число, не сходящееся с собственной фикстурой, — '
                              f'release-blocker)')

    RX_WHOLE_MONTH = re.compile(r'(?<![\d,])(\d{1,3}),0\s*[  ]?Monate?\b')

    def _sched_d17(self, rel, txt):
        """D-17: целый календарный интервал подписывается `n Monate` без `,0`.

        Область — продуктовые и дизайн-документы: там число является
        СПЕСИМЕНОМ, который уйдёт клиенту. Корпус `docs/audit/` цитирует
        формулировку отклонения (`7,0 Monate` в плане и реестре требований) —
        это текст решения, а не подпись длительности.
        """
        for m in self.RX_WHOLE_MONTH.finditer(txt):
            ln = txt[:m.start()].count('\n') + 1
            self.emit('SCHED-D17', rel, ln, f'SCHED-D17:{m.group(1)},0',
                      f'подпись `{m.group(0).strip()}`: D-17 требует целое '
                      f'`{m.group(1)} Monate` там, где интервал является целым числом '
                      f'календарных месяцев; десятичный перевод создаёт ложную точность '
                      f'(R-26). Отклонение сужено до случая несовпадающих дней месяца')
        # ВТОРАЯ ПОЛОВИНА D-17 (вердикт Codex, пункт 5): проверка ловила лишний
        # `,0`, но не ловила ОТСУТСТВИЕ `≈` у нецелого округлённого срока.
        # Признак берётся из самих дат фикстуры, а не из списка величин: `≈`
        # обязателен ровно тогда, когда день месяца у начала и конца интервала
        # НЕ совпадает — тогда показ отличается от точного (CALC-007). При
        # совпадении дня интервал есть целое число календарных месяцев, и
        # префикс был бы ложным утверждением о неточности. Обратное — тоже
        # дефект, и он проверяется здесь же.
        need_prefix = (self.fx or {}).get('dur_needs_prefix') or {}
        # Находки агрегируются ПО ИДЕНТИЧНОСТИ (величина + направление), а все
        # адреса печатаются в сообщении. Иначе одну и ту же подпись, повторённую
        # в четырёх местах, приходилось бы регистрировать записью по файлу и
        # классу — а такая запись маскирует и будущие находки того же класса
        # в том же файле, то есть шире долга (принцип 8).
        agg = {}
        if need_prefix:
            for m in re.finditer(r'(≈\s*)?(?<![\d,])(\d{1,3}(?:,\d+)?)\s*'
                                 r'[\u00a0\u202f ]?Monate', txt):
                val, has = de(m.group(2)), bool(m.group(1))
                if val not in need_prefix:
                    continue
                ln = txt[:m.start()].count('\n') + 1
                if need_prefix[val] and not has:
                    agg.setdefault(('noprefix', m.group(2)), []).append(ln)
                elif not need_prefix[val] and has:
                    agg.setdefault(('falseprefix', m.group(2)), []).append(ln)
        for (kind, shown), lines in sorted(agg.items()):
            where = ', '.join(str(x) for x in lines[:8]) + ('…' if len(lines) > 8 else '')
            if kind == 'noprefix':
                self.emit('SCHED-D17', rel, lines[0], f'SCHED-D17:noprefix:{shown}',
                          f'{len(lines)} мест: `{shown} Monate` без префикса `≈` '
                          f'(строки {where}). У этого интервала день месяца начала и конца '
                          f'НЕ совпадает, показ отличается от точного значения, и CALC-007 '
                          f'требует `≈` вместе с раскрытием точной длительности. Подпись без '
                          f'префикса утверждает точность, которой нет')
            else:
                self.emit('SCHED-D17', rel, lines[0], f'SCHED-D17:falseprefix:{shown}',
                          f'{len(lines)} мест: `≈ {shown} Monate` — префикс у величины, '
                          f'которая от округления не меняется (строки {where}). Интервал есть '
                          f'целое число календарных месяцев (день месяца совпадает), и `≈` — '
                          f'ложное утверждение о неточности (D-17, CALC-007)')

    # -- 4a. Устав как каноническая политика, а не шесть дословных фраз -------
    # Вердикт Codex, класс 8 и пункт 5: `check_governance()` имел три
    # blacklist-паттерна и три обязательных предложения. Прошли: инверсия
    # правила 12 («блокировки при клиенте допустимы»), снятое отрицание запрета
    # скруглений, разворот `.numeric` с выравнивания вправо на влево,
    # ослабление Bold-порога оранжевого с 18,67 px до 18 px.
    #
    # Реестр ниже — ПОЛОЖИТЕЛЬНЫЙ предикат на каждое неприкосновенное правило:
    # что обязано утверждаться (`need`) и что не имеет права утверждаться
    # (`ban`, с учётом отрицания). Проверяется утверждение, а не присутствие
    # строки, поэтому переписанная формулировка правило не теряет, а
    # перевёрнутая — не проходит.
    # Каждая запись: (имя правила, якорь предмета, положительный предикат,
    # ЯДРО запрещённого утверждения, объяснение цены). Ядро — короткая форма
    # без отрицания: отрицание проверяется окном перед ядром, иначе
    # «никогда не перезаписываются» само выглядело бы нарушением.
    CHARTER = (
        ('правило 12 · никаких блокировок при клиенте',
         r'блокиров\w*[^\n]{0,60}клиент|клиент\w*[^\n]{0,40}блокиров',
         r'[Нн]икаких\s+блокиров\w*|не\s+запреты|предупреждения\s+и\s+автодействия',
         r'(?<![\w-])(?:допустим|разрешен|возможн|приемлем)\w*',
         'V1–V11 — предупреждения и автодействия, НЕ запреты. Инверсия этого '
         'правила разрешает запирать поля на глазах заказчика'),
        ('правило 4 · никаких скруглений',
         r'скруглен|border-radius',
         r'[Нн]икаких\s+скруглений|border-radius:\s*0|скруглен\w*\s+запрещ',
         r'(?<![\w-])(?:допустим|разрешен|возможн|приемлем)\w*',
         'прямоугольники и идеальные круги; ненулевой радиус запрещён везде'),
        ('правило 7 · .numeric выравнивается вправо',
         r'\.numeric',
         r'вправо',
         r'(?<![\w-])(?:влево|text-align:\s*left)',
         'числа денег и площадей выравниваются ВПРАВО (tnum): выравнивание '
         'влево ломает сопоставление разрядов в колонке'),
        ('правило 14 · bestätigt не перезаписывается',
         r'bestätigt',
         r'никогда\s+не\s+перезаписыва\w*',
         r'(?<![\w-])перезаписыва\w*',
         'M-1/D-08: повторный анализ не перезаписывает подтверждённое'),
        ('правило 15 · отправленный вариант неизменяем',
         r'[Оо]тправленный\s+вариант',
         r'неизменяем\w*\s+снапшот',
         r'(?<![\w-])(?:изменя|правит|перезапис)\w*',
         'M-3: снапшот отправленного оффера неизменяем'),
        ('правило 13 · нет изменения данных без события',
         r'без\s+события',
         r'не\s+могут\s+измениться\s+без\s+события',
         r'(?<![\w-])могут\s+измениться\s+без\s+события',
         'M-4: данные не могут измениться без события журнала'),
        ('правило 16 · строка без расчётной базы не показывает ноль',
         r'без\s+расчётной\s+базы',
         r'ноль\s+запрещ\w*|никогда\s+не\s+0\s*€|не\s+0\s*€',
         r'(?<![\w-])(?:показыва\w*|допустим\w*)\s*(?:ноль|0\s*€)',
         'R-18: неполнота никогда не показывается как 0 € — ноль есть '
         'утверждение о цене, а не отсутствие данных'),
        ('правило 21 · prefers-reduced-motion гасит всё',
         r'prefers-reduced-motion',
         r'гасит\s+всё|включая\s+счёт\s+чисел',
         r'(?<![\w-])(?:кроме|за\s+исключением|исключая)',
         'правило 21: гасится всё, включая счёт чисел; исключений нет'),
    )

    def check_charter(self):
        rel = 'CLAUDE.md'
        txt = self.read(rel)
        if txt is None:
            self.fail('CLAUDE', rel, '[вакуум] CLAUDE.md отсутствует — устав не проверяется')
            return
        rows = txt.split('\n')
        NEG = re.compile(r'(?:никогда\s+не|\bне\b|запрещ\w*|вместо|а\s+не|нельзя|'
                         r'недопуст\w*|исключ\w*|прежн\w*|отменен\w*|ошибк\w*)[\s,«"`*_—-]*$',
                         re.I)
        for title, anchor, need, ban, why in self.CHARTER:
            hits = [(i, l) for i, l in enumerate(rows, 1) if re.search(anchor, l, re.I)]
            if not hits:
                self.fail('CLAUDE', rel, f'[вакуум] {title}: в уставе нет ни одной строки о '
                                         f'предмете правила — утверждение отсутствует, '
                                         f'а не выполнено. {why}')
                continue
            if not any(re.search(need, l, re.I) for _, l in hits):
                self.emit('CLAUDE', rel, hits[0][0], f'CLAUDE:need:{title}',
                          f'{title}: устав больше не утверждает требуемого. {why}')
            for i, l in hits:
                for m in re.finditer(ban, l, re.I):
                    if NEG.search(l[max(0, m.start() - 40):m.start()]):
                        continue      # это запрет формы, а не её разрешение
                    self.emit('CLAUDE', rel, i, f'CLAUDE:ban:{title}',
                              f'{title}: устав утверждает противоположное — '
                              f'«{m.group(0)[:50]}». {why}')
        # Порог бренд-оранжевого: ДВЕ пары, не одна (T04). Прежняя проверка
        # читала только первое целое `≥ N px` — ветка Bold не читалась вовсе,
        # и ослабление 18,67 → 18 проходило.
        m = re.search(r'#FD5E00([^\n]*)', txt)
        if not m:
            self.fail('CLAUDE', rel, '[вакуум] правило 5 не называет #FD5E00')
        else:
            frag, ln = m.group(1), txt[:m.start()].count('\n') + 1
            pairs = re.findall(r'≥\s*(\d+(?:[.,]\d+)?)\s*px(?:\s*(bold|Bold|Regular))?', frag)
            got = {}
            for val, kind in pairs:
                got[(kind or '').lower() or 'regular'] = de(val)
            # Порог выводится из контраста: 3,10:1 проходит только large text,
            # а large text по WCAG — 24 px Regular либо 18,67 px Bold.
            for kind, want in (('regular', D('24')), ('bold', D('18.67'))):
                if kind not in got:
                    self.emit('CLAUDE', rel, ln, f'CLAUDE:threshold-{kind}',
                              f'правило 5 не называет порог кегля для варианта {kind}: '
                              f'при контрасте {fmt_ratio(contrast(CLR["accent"], CLR["white"]))}'
                              f':1 WCAG допускает только large text — ≥ 24 px Regular '
                              f'И ≥ 18,67 px Bold, обе ветки обязательны')
                elif got[kind] != want:
                    self.emit('CLAUDE', rel, ln, f'CLAUDE:threshold-{kind}',
                              f'правило 5: порог {kind} записан {got[kind]} px, WCAG large '
                              f'text требует {want} px. Ослабление порога делает оранжевый '
                              f'текст нечитаемым при контрасте '
                              f'{fmt_ratio(contrast(CLR["accent"], CLR["white"]))}:1')
        # Согласованность устава с реализацией (T17): правило `.numeric`
        # проверяется НЕ только по CSS-факту, но и по совпадению утверждений.
        css = self.read('design-system/tokens.css') or ''
        mn = re.search(r'\.numeric\s*\{([^}]*)\}', css)
        if mn:
            impl_right = 'right' in mn.group(1)
            says_right = bool(re.search(r'\.numeric[^\n]{0,80}вправо|вправо[^\n]{0,40}\.numeric|'
                                        r'`\.numeric`[^\n]{0,40}вправо', txt))
            if impl_right != says_right:
                self.emit('CLAUDE', rel, 1, 'CLAUDE:numeric-consistency',
                          f'устав и реализация расходятся о выравнивании `.numeric`: '
                          f'tokens.css выравнивает {"вправо" if impl_right else "НЕ вправо"}, '
                          f'CLAUDE.md утверждает {"вправо" if says_right else "иное"}. '
                          f'Правильный объект реализации не доказывает правильного правила')

    # -- 4. CLAUDE.md и decisions.md: отменённые правила ----------------------
    def check_governance(self):
        claude = self.read('CLAUDE.md') or ''
        for pat, why in [(r'hit-зону 32 px', 'R-04 требует 44×44'),
                         (r'9 типов', 'D-11 v2: четыре типизированные оси'),
                         (r'Bezugsfläche\s*=\s*Σ\s*WFL', 'R-11 запрещает WFL+NUF как клиентскую метрику')]:
            if re.search(pat, claude):
                self.fail('CLAUDE', 'CLAUDE.md', f'действует отменённое правило ({why})')
        # Присутствие неприкосновенных инвариантов (M-1/M-3/M-4, D-08).
        for need, why in [
                (r'`bestätigt`-значения и Festlegungen никогда не перезаписываются',
                 'M-1/D-08: повторный анализ не перезаписывает подтверждённое'),
                (r'Отправленный вариант — неизменяемый снапшот', 'M-3'),
                (r'Данные не могут измениться без события', 'M-4')]:
            if not re.search(need, claude):
                self.fail('CLAUDE', 'CLAUDE.md',
                          f'снят инвариант: «{need[:48]}…» ({why})')
        # Порог крупного текста для бренд-оранжевого выводится из контраста
        # 3,10:1 (проходит только large text) — величина не произвольная.
        m = re.search(r'#FD5E00[^\n]*?≥\s*(\d+)\s*px', claude)
        if not m:
            self.fail('CLAUDE', 'CLAUDE.md',
                      '[вакуум] правило 5 не называет порог кегля для #FD5E00')
        elif m.group(1) != '24':
            self.fail('CLAUDE', 'CLAUDE.md',
                      f'порог оранжевого текста {m.group(1)} px; при контрасте '
                      f'{fmt_ratio(contrast(CLR["accent"], CLR["white"]))}:1 WCAG допускает '
                      f'только large text — ≥ 24 px Regular (или ≥ 18,67 px Bold)')
        decisions = self.read('docs/product/decisions.md') or ''
        for bad, why in [(r'\*\*D-11\*\* Gebäudetyp — первая ось \(9 типов', 'D-11 отменён v2'),
                         (r'\*\*D-14\*\* комплексы зданий, Bezugsfläche WFL\+NUF', 'D-14 отменён v2')]:
            if re.search(bad, decisions):
                self.fail('DECISIONS', 'decisions.md', f'индекс описывает отменённую версию ({why})')

    # -- 5. План: отметка против текста ---------------------------------------
    def check_plan(self):
        rel = 'docs/audit/remediation-plan.md'
        plan = self.read(rel) or ''
        neg = re.compile(r'(не выполнен|не подтвержд|не реализован|не начат|перенос\w*|'
                         r'сдвин\w*|отложен|остаётся откры|ожидает вердикта|частично|'
                         r'не сделан|не закрыт|позже|следующ\w+\s+(квартал|батч|batch)|'
                         r'до Batch\s*\d|в Batch\s*\d)', re.I)
        done = re.compile(r'(?<!не )(выполнено|сделано|закрыто|принято аудитором)\b', re.I)
        for i, line in enumerate(plan.split('\n'), 1):
            if line.lstrip().startswith('- [x]') and neg.search(line):
                self.emit('PLAN', rel, i, line,
                          f'пункт помечен [x], но текст говорит об обратном — {line.strip()[:80]}')
            if line.lstrip().startswith('- [ ]') and done.search(line):
                self.emit('PLAN', rel, i, line,
                          f'пункт помечен [ ], но текст заявляет выполнение — {line.strip()[:80]}')
            if re.search(r'A11Y-001\s+закрыт(?!ым)', line) and not line.lstrip().startswith('>'):
                self.emit('PLAN', rel, i, line, 'живое утверждение о закрытии A11Y-001')

    # -- 6. PII / артефакты ----------------------------------------------------
    def check_privacy(self):
        """PII: детекторы КЛАССА, а не список известных спесименов.

        v2 был чёрным списком: любое новое имя, адрес, IBAN или телефон
        проходил насквозь, как и обфускация `t.mueller [at] …`, как и та же
        PII, переложенная в `.css`, `.ts`, `.svg` или в сам каталог `tools/`.
        Конвенция RFC 2606 была инвертирована: `…@example.org` считался
        production-доменом, а `…@zbi.example` — безопасным.
        """
        email_rx = re.compile(r'[\w.+-]+@([\w-]+(?:\.[\w-]+)*\.[A-Za-z]{2,})')
        # RFC 2606 / RFC 6761: зарезервированы под документацию и тесты.
        SAFE_DOM = ('example.com', 'example.org', 'example.net',
                    'test', 'invalid', 'localhost')

        def safe(dom):
            dom = dom.lower()
            return (dom == 'example' or dom.endswith('.example')
                    or dom in SAFE_DOM
                    or any(dom.endswith('.' + d) for d in SAFE_DOM))

        # Зарезервированное пространство документации — то же по смыслу, что
        # RFC 2606 для доменов, только для немецких адресов и имён:
        # Muster* / Beispiel* / Example* не бывают настоящими. Это структурная
        # конвенция, а не список слов-исключений: она объявлена здесь и
        # применяется только к попаданию детектора КЛАССА, не к спесименам.
        DOC_NAMESPACE = re.compile(r'muster|beispiel|example', re.I)
        # Детекторы класса. Ловят то, чего в списке спесименов нет и быть
        # не может: любой немецкий IBAN, любой телефон, любой индекс+город,
        # любую улицу с номером дома, любую обфускацию адреса скобками.
        klass = [
            ('IBAN', re.compile(r'\bDE\d{2}[ ]?(?:\d{4}[ ]?){4}\d{2}\b|\bDE\d{20}\b')),
            ('немецкий телефон', re.compile(
                r'\+\s?49[\s\-/().]*\d[\d\s\-/().]{6,}|'
                r'(?:Tel|Telefon|Mobil|Fax|Handy)\.?\s*:?\s*\+?\d[\d\s\-/().]{6,}')),
            ('индекс + город', re.compile(r'(?<!\d)\d{5}\s+[A-ZÄÖÜ][a-zäöüß]{2,}')),
            ('улица + номер дома', re.compile(
                r'[A-ZÄÖÜ][a-zäöüß]+(?:stra(?:ß|ss)e|str\.|weg|allee|platz|gasse|ring)\s*\d{1,4}\b')),
            ('обфускация адреса', re.compile(
                r'[A-Za-z0-9._+-]+\s*(?:\[|\()\s*at\s*(?:\]|\))\s*[A-Za-z0-9.-]+'
                r'\s*(?:(?:\[|\()\s*dot\s*(?:\]|\))|\.)\s*[A-Za-z]{2,}', re.I)),
        ]
        # Остаточный список известных спесименов страхует значения, у которых
        # класса нет (project-ID, номер заказа, фамилия). Собран из частей —
        # см. _j(): скан покрывает и tools/, а исходник со спесименом внутри
        # срабатывал бы на себя.
        pii_pats = [_j('Pank', 'stra'), r'Parkstra\w*e\s*5\d', _j('Beethoven', 'str'),
                    r'\b' + _j('Z', 'BI') + r'\b',
                    r'colophon-order-\d+', r'[Oo]rder\s*49043', r'\bGER-\d{5}\b',
                    r'M\.\s*Weber']
        spec_pats = [r'1[\s.  ]969,67', r'3[\s.  ]682[\s.  ]000',
                     r'1[\s.  ]685,49', r'665,75']  # реальные спесимены — только design-system/*
        seen = False
        for glob in ('*.md', '*.json', '*.html', '*.css', '*.ts', '*.tsx',
                     '*.svg', '*.txt', '*.py'):
            for rel, text in self.files(glob):
                seen = True
                own_tool = rel.startswith('tools/')
                for i, line in enumerate(text.split('\n'), 1):
                    for m in email_rx.finditer(line):
                        if not safe(m.group(1)):
                            self.emit('PRIVACY-001', rel, i, line,
                                      f'e-mail с production-доменом «{m.group(0)}» '
                                      f'(RFC 2606: безопасны example.com/.org/.net и *.example)')
                    for name, rx in klass:
                        for m in rx.finditer(line):
                            if DOC_NAMESPACE.search(m.group(0)):
                                continue   # зарезервированное имя документации
                            self.emit('PRIVACY-001', rel, i, line,
                                      f'PII класса «{name}»: {m.group(0)[:40]}')
                    if own_tool:
                        # В самом инструменте список спесименов не применяется:
                        # он и есть список спесименов. Детекторы класса выше
                        # работают и здесь, поэтому реальная PII не пройдёт.
                        continue
                    for pat in pii_pats:
                        if re.search(pat, line):
                            self.emit('PRIVACY-001', rel, i, line,
                                      f'production-like значение по паттерну «{pat}»')
                    if rel.startswith('design-system/'):
                        for pat in spec_pats:
                            if re.search(pat, line):
                                self.emit('PRIVACY-001', rel, i, line,
                                          'реальный спесимен (ставка/площадь) вне синтетической фикстуры')
        if not seen:
            self.fail('PRIVACY-001', 'repo', '[вакуум] PII-скан не нашёл ни одного файла')
        # A11Y-001 в отгружаемом HTML: пред-ремедиационные цвета
        for rel, text in self.files('*.html'):
            for i, line in enumerate(text.split('\n'), 1):
                if re.search(r'#(?:FD5E00|fd5e00|E05400|e05400)', line):
                    self.emit('ARTIFACT-A11Y', rel, i, line,
                              'пред-ремедиационный цвет действия в отгружаемом HTML (A11Y-001)')

    # -- 7. Арифметика: фикстура + каталог, всё из файлов ----------------------
    def _pair_after(self, cls, desc, tail, expect):
        """Пара «точное значение · показ» после знака `=` — по СТРУКТУРЕ.

        CALC-007 требует хранить точное значение и показывать округлённое с
        префиксом `≈`. Структура, на которую опирается разбор: до первого `€`
        стоят одно или два числа; последнее — показ, предыдущее (если есть) —
        точное. Слова «точно», «показ», «нетто», их порядок, разметка и
        переносы строк не участвуют: именно привязка к формулировке дважды за
        сессию превращала сверку в вакуум.
        """
        m = re.search(r'(≈)?\s*\+?\s*([\d][\d.]*(?:,\d+)?)\s*[  ]?€', tail)
        if not m:
            self.fail(cls, desc, f'[вакуум] {desc}: после формулы нет величины со знаком € — '
                                 f'сверить показ не с чем')
            return
        shown = de(m.group(2))
        nums = re.findall(r'(?<![\d.,])([\d][\d.]*(?:,\d+)?)', tail[:m.start()])
        exact = de(nums[-1]) if nums else None
        if exact is None:
            self.emit(cls, 'docs/product/calculation-spec.md', 1, f'{cls}:{desc}:no-exact',
                      f'{desc}: назван только показ {m.group(2)} € без точного значения — '
                      f'CALC-007 требует хранить и показывать точное рядом')
        else:
            self.eq(cls, f'{desc}: точное значение', exact, expect)
            self.eq(cls, f'{desc}: показ (до 1.000 €)', shown, r1000(exact))
            if shown != exact and not m.group(1):
                self.emit(cls, 'docs/product/calculation-spec.md', 1,
                          f'{cls}:{desc}:no-prefix',
                          f'{desc}: показ {m.group(2)} отличается от точного {exact}, '
                          f'но префикс `≈` отсутствует (CALC-007)')
        self.eq(cls, f'{desc}: показ = округление ожидаемого', shown, r1000(expect))

    def check_arithmetic(self):
        # ИЗОЛЯЦИЯ ЗАВИСИМЫХ ПРОВЕРОК (вердикт Codex, пункты 2 и 10).
        # Прежде `Vacuum` перехватывался вокруг ВСЕЙ `_arithmetic()`, а
        # публикация `self.fx` стояла в её конце. Один сломавшийся extractor —
        # контрольный пример R-01 в calculation-spec, который другой владелец
        # правил по вердикту, — обрывал конвейер, и `OUT-MONEY`/`RM-FIXTURE`
        # обвиняли ДВА КОРРЕКТНЫХ ФАЙЛА, которые никто не портил. Ложное
        # обвинение корректного файла хуже пропуска: оно тратит партию на
        # поиск дефекта, которого нет.
        # Теперь величины фикстуры извлекаются отдельным extractor'ом, который
        # читает ТОЛЬКО synthetic-fixtures.md и не зависит ни от спеки, ни от
        # сроков, ни от неопределённости.
        self._publish_fx()
        try:
            self._arithmetic()
        except Vacuum:
            pass

    # -- 7a. Независимый extractor величин фикстуры ---------------------------
    def _publish_fx(self):
        """`self.fx` из `synthetic-fixtures.md` — независимо от прочих проверок.

        Каждая величина берётся своим шаблоном; отсутствие ЛЮБОЙ из ядровых
        (итоги, площади, ставка каталога) означает, что сверять цитаты не с
        чем, и это называется одним вакуумом с ИМЕНЕМ несработавшего шаблона,
        а не молчанием и не обвинением цитирующих файлов.
        """
        fx = self.read('docs/audit/synthetic-fixtures.md')
        if fx is None:
            self.fail('CALC-FIXTURE', 'synthetic-fixtures.md',
                      '[вакуум] синтетическая фикстура отсутствует — ни одна цитата '
                      'денежных величин не проверяется')
            return
        miss = []

        def one(name, pattern, group=1, flags=0):
            m = re.search(self._soften(pattern), fx, flags)
            if not m:
                miss.append(name)
                return None
            try:
                return de(m.group(group))
            except Exception:
                miss.append(name)
                return None

        v = {
            'k': one('K_base', r'K_base = ([\d.]+) €'),
            'gk5': one('F_gk GK 5', r'F_gk:.*?GK 5 = ([\d,]+)'),
            'gk4': one('F_gk GK 4', r'F_gk:.*?GK 4 = ([\d,]+)'),
            'gk13': one('F_gk GK 1–3', r'F_gk: GK 1–3 = ([\d,]+)'),
            'eh55': one('F_energie EH 55', r'F_energie: EH 55 = ([\d,]+)'),
            'eh40': one('F_energie EH 40', r'F_energie:.*?EH 40 = ([\d,]+)'),
            'buero': one('F_form_büro', r'F_form_büro = ([\d,]+)'),
            'ug_rate': one('ставка UG', r'UG vollausbau \+ TG = [\d.]+ \+ [\d.]+ = ([\d.]+) €'),
            'ug_a': one('UG vollausbau', r'UG vollausbau \+ TG = ([\d.]+) \+'),
            'ug_b': one('TG-Zuschlag', r'UG vollausbau \+ TG = [\d.]+ \+ ([\d.]+) ='),
            'gk5z': one('F_gk_zeit GK 5', r'F_gk_zeit:.*?GK 5 = ([\d,]+)'),
            'gk4z': one('F_gk_zeit GK 4', r'F_gk_zeit:.*?GK 4 = ([\d,]+)'),
            'mfhz': one('F_form_zeit MFH', r'F_form_zeit: MFH = ([\d,]+)'),
            'bueroz': one('F_form_zeit Büro', r'F_form_zeit:.*?Büro = ([\d,]+)'),
            'A': one('итог Haus A', r'\*\*Zwischensumme der kalkulierten Positionen\*\* \| '
                                    r'\*\*([\d.,]+)\*\*'),
            'B': one('итог Haus B', r'\(EH 55\) = ([\d.,]+)`'),
            'G': one('итог Komplex', r'\| Zwischensumme der kalkulierten Positionen \| '
                                     r'([\d.,]+) \|'),
            'basis': one('строка Basis', r'\| Basis: [\d.,]+ × [\d.]+ \| ([\d.,]+) \|'),
            'gk_add': one('вклад GK 5', r'Gebäudeklasse 5 \(× [\d,]+\) \| \+ ([\d.,]+)'),
            'eh_add': one('вклад EH 55', r'Energiestandard EH 55 \(× [\d,]+\) \| \+ ([\d.,]+)'),
            'ug_add': one('вклад UG', r'Untergeschoss inkl\. Tiefgarage \([\d.,]+ × [\d.,]+\) '
                                      r'\| \+ ([\d.,]+)'),
            'kg3': one('KG 300', r'KG 300 `([\d.,]+)`'),
            'kg4': one('KG 400', r'KG 400 `([\d.,]+)`'),
            'kg7': one('KG 700', r'KG 700 `([\d.,]+)`'),
            'tot40': one('итог EH 40', r'\+ [\d.]+ = ([\d.,]+)` → ≈ `[\d.,]+ €`'),
            'noug': one('итог Ohne UG', r'[−-] [\d.]+ = ([\d.,]+)` → ≈ `[\d.,]+ €`'),
            'disc': one('точный итог со скидкой', r'× 0,\d+ = ([\d.,]+)` →'),
            'rab': one('ставка Rabatt', r'Rabatt ([\d,]+) %'),
            'wfl': one('WFL', r'\| WFL nach WoFlV \| ([\d.,]+)'),
            # Кандидат 2 объявленного конфликта DEMO-CONF-0001: тот же слот
            # WFL, другое значение. Без него удельная величина при кандидате 2
            # читается как «не сводится с фикстурой», хотя фикстура её
            # объявляет дословно. Пробел нашёл агент, правивший контракты, и
            # правильно НЕ стал удалять объявленное число, чтобы получить
            # зелёный отчёт: это была бы подгонка объекта под инструмент.
            'wfl_alt': one('WFL кандидат 2 конфликта DEMO-CONF-0001',
                           r'При кандидате 2 \| `[\d.]+ / ([\d.,]+) ='),
            'nuf': one('NUF', r'\| NUF nach DIN 277 \| [\d.,—-]+ (?:m²)? *\| ([\d.,]+)'),
            'bgf_a': one('BGF ober A', r'\| BGF oberirdisch \| ([\d.,]+)'),
            'bgf_b': one('BGF ober B', r'\| BGF oberirdisch \| [\d.,]+ (?:m²)? *\| ([\d.,]+)'),
            'rs_a': one('BGF R\\+S A', r'\| BGF R\+S \| ([\d.,]+)'),
            'rs_b': one('BGF R\\+S B', r'\| BGF R\+S \| [\d.,]+ (?:m²)? *\| ([\d.,]+)'),
            'ug_area': one('BGF unterirdisch', r'\| BGF unterirdisch \| ([\d.,]+)'),
            'we': one('Wohneinheiten', r'\| Wohneinheiten \| (\d+)'),
            'sum_ober': one('Σ BGF ober', r'\| Σ BGF \*\*oberirdisch\*\* \| ([\d.,]+)'),
            'sum_rs': one('Σ BGF R\\+S', r'\| Σ BGF \*\*R\+S\*\*[^|]*\| ([\d.,]+)'),
            'ib': one('Interne Bezugsgröße', r'Interne Bezugsgröße[^|]*\| ([\d.,]+) m²'),
            'reg': one('Regionalfaktor', r'Regionalfaktor `Musterland` ([\d,]+)'),
        }
        core = ('k', 'A', 'B', 'G', 'wfl', 'nuf', 'bgf_a', 'bgf_b', 'sum_ober', 'sum_rs',
                'ib', 'we', 'rs_a', 'rab', 'disc')
        if any(v[k] is None for k in core):
            self.fail('CALC-FIXTURE', 'synthetic-fixtures.md',
                      f'[вакуум] в фикстуре не прочитаны величины: {", ".join(sorted(miss))} — '
                      f'сверка цитат в README и output-model не выполняется. Это дефект '
                      f'ШАБЛОНА извлечения, а не цитирующих файлов')
            return
        exact = {v[k] for k in ('basis', 'gk_add', 'eh_add', 'ug_add', 'A', 'kg3', 'kg4',
                                'kg7', 'tot40', 'noug', 'B', 'G', 'disc') if v[k] is not None}
        exact |= {v['tot40'] - v['A'], v['A'] - v['noug'], v['A'] - v['disc']}
        if v['reg'] is not None:
            exact.add(r1000(v['A'] * (v['reg'] - 1)))
        disp = {r1000(x) for x in exact} | {r1(x) for x in exact} | {D('1000')}
        if None not in (v['kg3'], v['kg4'], v['kg7']):
            disp.add(r1000(v['kg3']) + r1000(v['kg4']) + r1000(v['kg7']))
        pairs = [(v['A'], v['wfl']), (v['A'], v['rs_a']), (v['A'], v['bgf_a']),
                 (v['A'], v['we']), (v['B'], v['nuf']), (v['B'], v['bgf_b']),
                 (v['G'], v['sum_ober']), (v['G'], v['sum_rs']), (v['G'], v['ib'])]
        if v['tot40'] is not None:
            pairs.append((v['tot40'], v['wfl']))
        if v['noug'] is not None:
            pairs.append((v['noug'], v['wfl']))
        if v.get('wfl_alt') is not None:
            # Тот же числитель, знаменатель альтернативного кандидата слота.
            pairs.append((v['A'], v['wfl_alt']))
        rates = {r1(n / d) for n, d in pairs} | {r2(n / d) for n, d in pairs}
        rates |= {x for x in (v['k'], v['ug_rate'], v['ug_a'], v['ug_b']) if x is not None}
        wfl_rates = [r2(x / v['wfl']) for x in (v['A'], v['tot40'], v['noug']) if x is not None]
        for a_ in wfl_rates:
            for b_ in wfl_rates:
                if a_ != b_:
                    rates |= {r1(abs(a_ - b_)), r2(abs(a_ - b_))}
        for d_ in (v['tot40'] - v['A'] if v['tot40'] else None,
                   v['A'] - v['noug'] if v['noug'] else None,
                   v['ug_add'], v['gk_add'], v['eh_add']):
            if d_ is not None:
                rates |= {r1(abs(d_) / v['wfl']), r2(abs(d_) / v['wfl'])}
        # Сроки и даты фикстуры — для сверки спесименов расписания
        # Длительности: и отображаемые, и СЫРЫЕ. Сырое значение в фикстуре
        # пишется усечённым (`7,283333…`), а цитирующий файл вправе привести его
        # с меньшей точностью (`7,283`) — поэтому хранится и набор усечений.
        durations = {de(x) for x in re.findall(r'(\d+(?:,\d+)?)\s*[  ]?Monate', fx)}
        raws = {de(x) for x in re.findall(r'=\s*(\d+,\d+)', fx)}
        durations |= raws
        for r_ in raws:
            for prec in range(1, 7):
                durations.add(r_.quantize(D(1).scaleb(-prec), rounding=ROUND_DOWN))
                durations.add(r_.quantize(D(1).scaleb(-prec), rounding=ROUND_HALF_UP))
        dates = set(re.findall(r'\b\d{2}\.\d{2}\.\d{4}\b', fx))
        # Нужен ли префикс `≈` у подписи длительности — выводится ИЗ ДАТ строки
        # расписания: совпадает день месяца → интервал целый, префикс запрещён;
        # не совпадает → показ отличается от точного, префикс обязателен (D-17).
        needs = {}
        for row in re.finditer(r'^\|[^|\n]*\|\s*(\d{2})\.(\d{2})\.(\d{4})\s*\|\s*'
                               r'\**(\d{2})\.(\d{2})\.(\d{4})\**\s*\|\s*\**≈?\s*'
                               r'(\d+(?:,\d+)?)\s*[\u00a0\u202f ]?Monate', fx, re.M):
            d1, d2, shown = row.group(1), row.group(4), de(row.group(7))
            needs[shown] = (d1 != d2)
        # Объявленные КОНФЛИКТЫ значений: id, оба кандидата, дельта. Нужны,
        # чтобы спесимен конфликт-резолвера ссылался на существующее СОСТОЯНИЕ,
        # а не собирался из двух независимо объявленных величин (вердикт Codex).
        conflicts = {}
        for mc in re.finditer(r'`(DEMO-CONF-\d+)`(.*?)(?=\n###\s|\Z)', fx, re.S):
            blk = mc.group(2)
            cands = re.findall(r'Кандидат\s*\d[^|]*\|\s*`?([\d.,]+)\s*m²', blk)
            if len(cands) >= 2:
                conflicts[mc.group(1)] = tuple(de(x) for x in cands[:2])
        factors = {}
        for lbl, key in (('GK 5 Zeit', 'gk5z'), ('GK 4 Zeit', 'gk4z'), ('Form MFH', 'mfhz'),
                        ('GK 5', 'gk5'), ('GK 4', 'gk4'), ('EH 55', 'eh55'),
                        ('EH 40', 'eh40'), ('Form Büro', 'buero')):
            if v[key] is not None:
                factors[lbl] = v[key]
        self.fx = dict(v)
        self.fx.update({'exact': exact, 'disp': disp, 'rates': rates, 'durations': durations,
                        'dates': dates, 'factors': factors, 'dur_needs_prefix': needs,
                        'conflicts': conflicts, 'rabatt': v['rab'],
                        'discount_exact': v['disc'],
                        'areas': {v[k] for k in ('wfl', 'nuf', 'bgf_a', 'bgf_b', 'rs_a', 'rs_b',
                                                 'ug_area', 'sum_ober', 'sum_rs', 'ib')
                                  if v[k] is not None}})

    def _arithmetic(self):
        fx = self.read('docs/audit/synthetic-fixtures.md') or ''
        sp = self.read('docs/product/calculation-spec.md') or ''
        C, F, S, U = 'CALC-CATALOG', 'CALC-FIXTURE', 'CALC-SCHEDULE', 'CALC-UNCERT'

        # каталог фикстуры
        k_fx = de(self.grab(fx, r'K_base\s*=\s*([\d.\s]+?)\s*€', C, 'фикстура: K_base').group(1))
        g = self.grab(fx, r'F_gk:\s*GK\s*1–3\s*=\s*([\d,]+)\s*·\s*GK\s*4\s*=\s*([\d,]+)\s*·\s*GK\s*5\s*=\s*([\d,]+)',
                      C, 'фикстура: строка F_gk')
        gk13_fx, gk4_fx, gk5_fx = de(g.group(1)), de(g.group(2)), de(g.group(3))
        g = self.grab(fx, r'F_energie:\s*EH\s*55\s*=\s*([\d,]+)\s*·\s*EH\s*40\s*=\s*([\d,]+)',
                      C, 'фикстура: строка F_energie')
        eh55_fx, eh40_fx = de(g.group(1)), de(g.group(2))
        buero_fx = de(self.grab(fx, r'F_form_büro\s*=\s*([\d,]+)', C, 'фикстура: F_form_büro').group(1))
        g = self.grab(fx, r'UG vollausbau \+ TG\s*=\s*([\d.\s]+?)\s*\+\s*([\d.\s]+?)\s*=\s*([\d.\s]+?)\s*€',
                      C, 'фикстура: ставка UG')
        ug_a, ug_b, ug_rate = de(g.group(1)), de(g.group(2)), de(g.group(3))
        self.eq(C, 'фикстура: UG-сумма 1.100+90', ug_a + ug_b, ug_rate)
        g = self.grab(fx, r'F_gk_zeit:\s*GK\s*3\s*=\s*([\d,]+)\s*·\s*GK\s*4\s*=\s*([\d,]+)\s*·\s*GK\s*5\s*=\s*([\d,]+)',
                      C, 'фикстура: строка F_gk_zeit')
        gk4z_fx, gk5z_fx = de(g.group(2)), de(g.group(3))
        g = self.grab(fx, r'F_form_zeit:\s*MFH\s*=\s*([\d,]+)\s*·\s*Büro\s*=\s*([\d,]+)',
                      C, 'фикстура: строка F_form_zeit')
        mfhz_fx, bueroz_fx = de(g.group(1)), de(g.group(2))

        # каталог calculation-spec
        k_sp = de(self.grab(sp, r'K_base[^=\n]*=\s*([\d\s.]+?)\s*€', C, 'спека: K_base').group(1))
        g = self.grab(sp, r'GK ⚙\s*\|\s*GK\s*1–3\s*([\d,]+)\s*·\s*GK\s*4\s*([\d,]+)\s*·\s*GK\s*5\s*([\d,]+)',
                      C, 'спека: строка GK')
        gk13_sp, gk4_sp, gk5_sp = de(g.group(1)), de(g.group(2)), de(g.group(3))
        g = self.grab(sp, r'GEG\s*1,00\s*·\s*EH\s*55\s*([\d,]+)\s*·\s*EH\s*40\s*([\d,]+)',
                      C, 'спека: строка Energiestandard')
        eh55_sp, eh40_sp = de(g.group(1)), de(g.group(2))
        buero_sp = de(self.grab(sp, r'Büro\s*([\d,]+)\s*·\s*Gewerbe', C, 'спека: Büro в Gebäudetyp').group(1))
        ugv_sp = de(self.grab(sp, r'UG vollausbau ⚙\s*\|\s*([\d\s.]+?)\s*€', C, 'спека: UG vollausbau').group(1))
        tg_sp = de(self.grab(sp, r'Tiefgarage-Zuschlag ⚙\s*\|\s*\+\s*([\d\s.]+?)\s*€', C, 'спека: TG-Zuschlag').group(1))
        g = self.grab(sp, r'F_gk_zeit:\s*GK1\s*[\d,]+\s*·\s*GK2\s*[\d,]+\s*·\s*GK3\s*([\d,]+)\s*·\s*GK4\s*([\d,]+)\s*·\s*GK5\s*([\d,]+)',
                      C, 'спека: строка F_gk_zeit')
        gk4z_sp, gk5z_sp = de(g.group(2)), de(g.group(3))
        mfhz_sp = de(self.grab(sp, r'F_typ_zeit:[^\n]*MFH\s*([\d,]+)', S, 'спека: MFH zeit').group(1))
        plan_sp = de(self.grab(sp, r'planung\((\d+)', S, 'спека: planung(n)').group(1))
        stag_sp = de(self.grab(sp, r'stagger\((\d+)', S, 'спека: stagger(n)').group(1))

        # перекрёстная сверка каталогов (мутация «GK 4 = 1,00 → 1,05» ловится здесь)
        for desc, a, b in [('K_base', k_fx, k_sp), ('F_gk 1–3', gk13_fx, gk13_sp),
                           ('F_gk4 (стоимость)', gk4_fx, gk4_sp), ('F_gk5 (стоимость)', gk5_fx, gk5_sp),
                           ('F_eh55', eh55_fx, eh55_sp), ('F_eh40', eh40_fx, eh40_sp),
                           ('F_form_büro', buero_fx, buero_sp), ('ставка UG vollausbau', ug_a, ugv_sp),
                           ('TG-Zuschlag', ug_b, tg_sp), ('F_gk4_zeit', gk4z_fx, gk4z_sp),
                           ('F_gk5_zeit', gk5z_fx, gk5z_sp), ('F_mfh_zeit', mfhz_fx, mfhz_sp)]:
            if a != b:
                self.fail(C, f'каталог: {desc}', f'фикстура {a} ≠ calculation-spec {b}')

        # площади
        def area(label, col):
            m = self.grab(fx, r'\|\s*' + label + r'\s*\|\s*([\d.,—-]+)(?:\s*m²)?\s*\|\s*([\d.,—-]+)(?:\s*m²)?\s*\|',
                          F, f'фикстура: площадь {label}')
            return de(m.group(col))
        bgf_a = area('BGF oberirdisch', 1); bgf_b = area('BGF oberirdisch', 2)
        ug_area = area('BGF unterirdisch', 1)
        rs_a = area(r'BGF R\+S', 1); rs_b = area(r'BGF R\+S', 2)
        wfl = area('WFL nach WoFlV', 1); nuf = area('NUF nach DIN 277', 2)
        we = de(self.grab(fx, r'\|\s*Wohneinheiten\s*\|\s*(\d+)\s*\|', F, 'фикстура: WE').group(1))
        self.eq(F, 'BGF R+S Haus A = ober + UG', rs_a, bgf_a + ug_area)
        self.eq(F, 'BGF R+S Haus B = ober', rs_b, bgf_b)

        # Haus A: строки драйверов
        g = self.grab(fx, r'\|\s*Basis:\s*([\d.,]+)\s*×\s*([\d.]+)\s*\|\s*([\d.,]+)\s*\|', F, 'фикстура: строка Basis')
        self.eq(F, 'Basis = BGF_A × K_base (входы строки)', (de(g.group(1)), de(g.group(2))), (bgf_a, k_fx))
        basis = de(g.group(3))
        self.eq(F, 'Basis-произведение', basis, bgf_a * k_fx)
        g = self.grab(fx, r'\|\s*Gebäudeklasse 5 \(×\s*([\d,]+)\)\s*\|\s*\+\s*([\d.,]+)\s*\|\s*≈\s*([\d.,]+)\s*€', F, 'фикстура: строка GK 5')
        self.eq(F, 'фактор строки GK5 = каталожному', de(g.group(1)), gk5_fx)
        gk_add = de(g.group(2))
        self.eq(F, 'вклад GK 5', gk_add, basis * (gk5_fx - 1))
        self.eq(F, 'отображение вклада GK 5', de(g.group(3)), r1000(gk_add))
        g = self.grab(fx, r'\|\s*Energiestandard EH 55 \(×\s*([\d,]+)\)\s*\|\s*\+\s*([\d.,]+)\s*\|\s*≈\s*([\d.,]+)\s*€', F, 'фикстура: строка EH 55')
        self.eq(F, 'фактор строки EH55 = каталожному', de(g.group(1)), eh55_fx)
        eh_add = de(g.group(2))
        self.eq(F, 'вклад EH 55', eh_add, (basis + gk_add) * (eh55_fx - 1))
        g = self.grab(fx, r'\|\s*Untergeschoss inkl\. Tiefgarage \(([\d.,]+)\s*×\s*([\d.,]+)\)\s*\|\s*\+\s*([\d.,]+)\s*\|', F, 'фикстура: строка UG')
        self.eq(F, 'входы строки UG', (de(g.group(1)), de(g.group(2))), (ug_area, ug_rate))
        ug_add = de(g.group(3))
        self.eq(F, 'вклад UG', ug_add, ug_area * ug_rate)
        g = self.grab(fx, r'\|\s*\*\*Zwischensumme der kalkulierten Positionen\*\*\s*\|\s*\*\*([\d.,]+)\*\*\s*\|\s*\*\*≈\s*([\d.,]+)\s*€\*\*\s*\|', F, 'фикстура: итог Haus A')
        A = de(g.group(1))
        self.eq(F, 'итог Haus A = сумма драйверов', A, basis + gk_add + eh_add + ug_add)
        self.eq(F, 'итог Haus A = формула', A, bgf_a * k_fx * gk5_fx * eh55_fx + ug_area * ug_rate)
        self.eq(F, 'отображение итога Haus A', de(g.group(2)), r1000(A))
        g = self.grab(fx, r'`([\d.,]+)\s*\+\s*([\d.,]+)\s*\+\s*([\d.,]+)\s*\+\s*([\d.,]+)\s*=\s*([\d.,]+)`', F, 'фикстура: строка сверки драйверов')
        vals = [de(g.group(i)) for i in range(1, 6)]
        self.eq(F, 'сверка драйверов', sum(vals[:4]), vals[4])
        self.eq(F, 'сверка драйверов = итогу', vals[4], A)

        # KG-разбивка
        g = self.grab(fx, r'vereinfacht (\d+)/(\d+)/(\d+)', F, 'фикстура: доли KG')
        s3, s4, s7 = (de(g.group(i)) / 100 for i in range(1, 4))
        self.eq(F, 'доли KG дают 100 %', s3 + s4 + s7, D('1'))
        g = self.grab(fx, r'KG 300 `([\d.,]+)` → ≈ `([\d.,]+)` · KG 400 `([\d.,]+)` → ≈ `([\d.,]+)` · KG 700 `([\d.,]+)` → ≈ `([\d.,]+)`', F, 'фикстура: строки KG')
        kg3, kg3d, kg4, kg4d, kg7, kg7d = (de(g.group(i)) for i in range(1, 7))
        self.eq(F, 'KG 300 точное', kg3, A * s3)
        self.eq(F, 'KG 400 точное', kg4, A * s4)
        self.eq(F, 'KG 700 точное', kg7, A * s7)
        self.eq(F, 'KG сумма = итог', kg3 + kg4 + kg7, A)
        for d, e, n in ((kg3d, kg3, '300'), (kg4d, kg4, '400'), (kg7d, kg7, '700')):
            self.eq(F, f'KG {n} отображение', d, r1000(e))

        # удельные Haus A
        def rate(pattern, num, den, has2dp=True):
            m = self.grab(fx, pattern, F, f'фикстура: удельная {pattern[:40]}')
            disp = de(m.group(1))
            self.eq(F, f'числитель удельной ({pattern[:30]})', de(m.group(2)), num)
            self.eq(F, f'знаменатель удельной ({pattern[:30]})', de(m.group(3)), den)
            if has2dp:
                self.eq(F, f'точное 2dp ({pattern[:30]})', de(m.group(4)), r2(num / den))
            self.eq(F, f'отображение удельной ({pattern[:30]})', disp, r1(num / den))
        rate(r'`≈\s*([\d.,]+)\s*€/m² WFL nach WoFlV`\s*—\s*`([\d.,]+)\s*/\s*([\d.,]+)`\s*=\s*([\d.,]+)', A, wfl)
        rate(r'`≈\s*([\d.,]+)\s*€/m² BGF R\+S`\s*—\s*`([\d.,]+)\s*/\s*([\d.,]+)`\s*=\s*([\d.,]+)', A, rs_a)
        rate(r'`≈\s*([\d.,]+)\s*€/m² BGF oberirdisch`\s*—\s*`([\d.,]+)\s*/\s*([\d.,]+)`\s*=\s*([\d.,]+)', A, bgf_a)
        m = self.grab(fx, r'`≈\s*([\d.,]+)\s*€ je Wohneinheit`\s*—\s*`([\d.,]+)\s*/\s*(\d+)`', F, 'фикстура: € je WE')
        self.eq(F, '€ je WE входы', (de(m.group(2)), de(m.group(3))), (A, we))
        self.eq(F, '€ je WE отображение', de(m.group(1)), r1(A / we))

        # Regionalfaktor: «дал бы ≈ X € на блок Bauwerk»
        m = self.grab(fx, r'Regionalfaktor `Musterland` ([\d,]+)[^\n]*дал бы ≈\s*([\d.,]+)\s*€', F, 'фикстура: строка Regionalfaktor')
        reg = de(m.group(1))
        self.eq(F, 'эффект Regionalfaktor', de(m.group(2)), r1000(A * (reg - 1)))

        # EH 40
        m = self.grab(fx, r'`([\d.,]+)\s*×\s*([\d,]+)\s*\+\s*([\d.,]+)\s*=\s*([\d.,]+)`\s*→\s*≈\s*`([\d.,]+)\s*€`\s*·\s*дельта к Basis `\+\s*([\d.,]+)`\s*→\s*≈\s*\*\*\+\s*([\d.,]+)\s*€\s*\(\+\s*([\d.,]+)\s*%\)\*\*\s*·\s*`≈\s*([\d.,]+)\s*€/m² WFL(?: nach WoFlV)?`', F, 'фикстура: строка EH 40')
        sub, f40, add, tot40 = de(m.group(1)), de(m.group(2)), de(m.group(3)), de(m.group(4))
        self.eq(F, 'EH40: база = Basis×GK5', sub, basis * gk5_fx)
        self.eq(F, 'EH40: фактор = каталожному', f40, eh40_fx)
        self.eq(F, 'EH40: добавка = UG', add, ug_add)
        self.eq(F, 'EH40: произведение', tot40, sub * f40 + add)
        self.eq(F, 'EH40: отображение', de(m.group(5)), r1000(tot40))
        self.eq(F, 'EH40: точная дельта', de(m.group(6)), tot40 - A)
        self.eq(F, 'EH40: отображение дельты', de(m.group(7)), r1000(tot40 - A))
        self.eq(F, 'EH40: процент дельты', de(m.group(8)), r2((tot40 - A) / A * 100))
        self.eq(F, 'EH40: €/m² WFL', de(m.group(9)), r1(tot40 / wfl))
        m = self.grab(fx, r'KG точные: `([\d.,]+)\s*/\s*([\d.,]+)\s*/\s*([\d.,]+)`', F, 'фикстура: KG EH40')
        self.eq(F, 'EH40 KG 300', de(m.group(1)), tot40 * s3)
        self.eq(F, 'EH40 KG 400', de(m.group(2)), tot40 * s4)
        self.eq(F, 'EH40 KG 700', de(m.group(3)), tot40 * s7)

        # Ohne UG
        m = self.grab(fx, r'`([\d.,]+)\s*[−-]\s*([\d.,]+)\s*=\s*([\d.,]+)`\s*→\s*≈\s*`([\d.,]+)\s*€`\s*·\s*дельта \*\*[−-]\s*([\d.,]+)\s*€\*\*\s*·\s*`≈\s*([\d.,]+)\s*€/m² WFL(?: nach WoFlV)?`', F, 'фикстура: строка Ohne UG')
        self.eq(F, 'OhneUG: уменьшаемое = итог A', de(m.group(1)), A)
        self.eq(F, 'OhneUG: вычитаемое = вклад UG', de(m.group(2)), ug_add)
        noug = de(m.group(3))
        self.eq(F, 'OhneUG: разность', noug, A - ug_add)
        self.eq(F, 'OhneUG: отображение', de(m.group(4)), r1000(noug))
        self.eq(F, 'OhneUG: дельта', de(m.group(5)), ug_add)
        self.eq(F, 'OhneUG: €/m² WFL', de(m.group(6)), r1(noug / wfl))

        # Haus B
        m = self.grab(fx, r'`([\d.,]+)\s*×\s*([\d.]+)\s*×\s*([\d,]+)\s*\(Form Büro\)\s*×\s*([\d,]+)\s*\(GK 4\)\s*×\s*([\d,]+)\s*\(EH 55\)\s*=\s*([\d.,]+)`\s*→\s*≈\s*\*\*([\d.,]+)\s*€\*\*', F, 'фикстура: строка Haus B')
        ins = (de(m.group(1)), de(m.group(2)), de(m.group(3)), de(m.group(4)), de(m.group(5)))
        self.eq(F, 'Haus B: входы = каталогу', ins, (bgf_b, k_fx, buero_fx, gk4_fx, eh55_fx))
        B = de(m.group(6))
        self.eq(F, 'Haus B: произведение', B, bgf_b * k_fx * buero_fx * gk4_fx * eh55_fx)
        self.eq(F, 'Haus B: отображение', de(m.group(7)), r1000(B))
        rate(r'`≈\s*([\d.,]+)\s*€/m² NUF nach DIN 277`\s*—\s*`([\d.,]+)\s*/\s*([\d.,]+)`\s*=\s*([\d.,]+)', B, nuf)
        # Строк «€/m² BGF oberirdisch» в фикстуре две — Haus A и Haus B.
        # Прежде выбор нужной делался условием `if числитель == B:` — при порче
        # числителя проверка молча пропускалась вместо провала (нарушение
        # принципа 1 и 6). Теперь строка выбирается ПОЗИЦИЕЙ (последняя),
        # а числитель сверяется безусловно.
        rx_ober = re.compile(r'`≈\s*([\d.,]+)\s*€/m² BGF oberirdisch`\s*—\s*'
                             r'`([\d.,]+)\s*/\s*([\d.,]+)`\s*=\s*([\d.,]+)\n')
        ober_rows = list(rx_ober.finditer(fx))
        if len(ober_rows) < 2:
            self.fail(F, 'фикстура: €/m² BGF Haus B',
                      f'[вакуум] ожидались две строки «€/m² BGF oberirdisch» '
                      f'(Haus A и Haus B), найдено {len(ober_rows)}')
        else:
            m = ober_rows[-1]
            self.eq(F, 'Haus B €/m² BGF: числитель', de(m.group(2)), B)
            self.eq(F, 'Haus B €/m² BGF: знаменатель', de(m.group(3)), bgf_b)
            self.eq(F, 'Haus B €/m² BGF: 2dp', de(m.group(4)), r2(B / bgf_b))
            self.eq(F, 'Haus B €/m² BGF: отображение', de(m.group(1)), r1(B / bgf_b))

        # Komplex
        m = self.grab(fx, r'\|\s*Zwischensumme der kalkulierten Positionen\s*\|\s*([\d.,]+)\s*\|\s*≈\s*([\d.,]+)\s*€\s*\|', F, 'фикстура: итог Komplex')
        G = de(m.group(1))
        self.eq(F, 'Komplex = A + B', G, A + B)
        self.eq(F, 'Komplex отображение', de(m.group(2)), r1000(G))
        m = self.grab(fx, r'\|\s*Σ BGF \*\*oberirdisch\*\*\s*\|\s*([\d.,]+)\s*m²', F, 'фикстура: Σ BGF ober')
        sum_ober = de(m.group(1))
        self.eq(F, 'Σ BGF ober = A + B', sum_ober, bgf_a + bgf_b)
        m = self.grab(fx, r'\|\s*Σ BGF \*\*R\+S\*\*[^|]*\|\s*([\d.,]+)\s*m²', F, 'фикстура: Σ BGF R+S')
        sum_rs = de(m.group(1))
        self.eq(F, 'Σ BGF R+S', sum_rs, rs_a + rs_b)
        m = self.grab(fx, r'\*\*≈\s*([\d.,]+)\s*€/m² BGF oberirdisch\*\*[^|]*\|\s*([\d.,]+)\s*/\s*([\d.,]+)\s*=\s*([\d.,]+)\s*\|', F, 'фикстура: клиентская база Komplex')
        self.eq(F, 'Komplex €/m² ober: числитель', de(m.group(2)), G)
        self.eq(F, 'Komplex €/m² ober: знаменатель', de(m.group(3)), sum_ober)
        self.eq(F, 'Komplex €/m² ober: 2dp', de(m.group(4)), r2(G / sum_ober))
        self.eq(F, 'Komplex €/m² ober: отображение', de(m.group(1)), r1(G / sum_ober))
        m = self.grab(fx, r'`≈\s*([\d.,]+)\s*€/m² BGF R\+S`[^|]*\|\s*([\d.,]+)\s*/\s*([\d.,]+)\s*=\s*([\d.,]+)\s*\|', F, 'фикстура: вторичная ставка Komplex')
        self.eq(F, 'Komplex €/m² R+S: числитель', de(m.group(2)), G)
        self.eq(F, 'Komplex €/m² R+S: знаменатель', de(m.group(3)), sum_rs)
        self.eq(F, 'Komplex €/m² R+S: 2dp', de(m.group(4)), r2(G / sum_rs))
        self.eq(F, 'Komplex €/m² R+S: отображение', de(m.group(1)), r1(G / sum_rs))
        m = self.grab(fx, r'Interne Bezugsgröße[^|]*\|\s*([\d.,]+)\s*m²[^|·]*·\s*([\d.,]+)\s*/\s*([\d.,]+)\s*=\s*\*\*([\d.,]+)\*\*\s*\|\s*≈\s*([\d.,]+)\s*€/m²', F, 'фикстура: Interne Bezugsgröße')
        ib = de(m.group(1))
        self.eq(F, 'Interne Bezugsgröße = WFL + NUF', ib, wfl + nuf)
        self.eq(F, 'Interne: числитель', de(m.group(2)), G)
        self.eq(F, 'Interne: знаменатель', de(m.group(3)), ib)
        self.eq(F, 'Interne: 2dp', de(m.group(4)), r2(G / ib))
        self.eq(F, 'Interne: отображение', de(m.group(5)), r1(G / ib))

        # скидка
        rab = de(self.grab(fx, r'Rabatt\s*([\d,]+)\s*%', F, 'фикстура: ставка Rabatt').group(1))
        m = self.grab(fx, r'`([\d.,]+)\s*×\s*([\d,]+)\s*=\s*([\d.,]+)`\s*→\s*отображение\s*`≈\s*([\d.,]+)\s*€`[^\n]*exakter Rechenwert\s*([\d.,]+)\s*€', F, 'фикстура: строка скидки')
        self.eq(F, 'скидка: база = точный итог A', de(m.group(1)), A)
        self.eq(F, 'скидка: множитель = 1 − Rabatt', de(m.group(2)), 1 - rab / 100)
        exact = de(m.group(3))
        self.eq(F, 'скидка: произведение', exact, A * (1 - rab / 100))
        self.eq(F, 'скидка: отображение', de(m.group(4)), r1000(exact))
        self.eq(F, 'скидка: exakter Rechenwert совпадает', de(m.group(5)), exact)

        # сроки — один ScheduleModel
        m = self.grab(fx, r'\|\s*Planung\s*\|[^|]*\|[^|]*\|\s*([\d,]+)\s*Monate', S, 'фикстура: строка Planung')
        planung = de(m.group(1))
        self.eq(S, 'Planung = planung(n) из спеки', planung, plan_sp)
        # Строки Bauzeit разбираются СТРУКТУРНО: подпись длительности, база
        # `5 + (BGF − 1.000)/N`, множители через `×`, сырое значение после `=`,
        # округлённое после `→`. Прежняя редакция требовала дословной вёрстки
        # (`= 7,283 → 7,5`); правка по CALC-007 добавила префикс `≈`, слова
        # «округление 0,5 →» и многоточие усечения — и сверка сроков стала
        # вакуумом. Тот же класс, что дважды до этого.
        def bauzeit(label, form_label, zeit_label, area, f_form, f_gk, extra=''):
            m = self.grab(fx, r'\|\s*' + label + r'\s*\|[^|]*\|[^|]*\|\s*≈?\s*([\d,]+)\s*'
                              r'Monate ab OKBP\s*\|([^|]*' + extra + r'[^|]*)\|',
                          S, f'фикстура: Bauzeit {label}')
            shown, cell = de(m.group(1)), m.group(2)
            mb = self.grab(cell, r'5\s*\+\s*\(?\s*([\d.,]+)\s*(?:[−–-]\s*([\d.,]+)\s*)?\)?\s*/'
                                 r'\s*([\d.,]+)', S, f'фикстура: база срока {label}')
            num = de(mb.group(1)) - (de(mb.group(2)) if mb.group(2) else D('0'))
            self.eq(S, f'{label}: BGF-числитель формулы', num, area - 1000)
            facs = [de(x) for x in re.findall(r'×\s*([\d,]+)', cell)]
            self.eq(S, f'{label}: формула использует каталожные факторы',
                    tuple(sorted(facs)), tuple(sorted((f_form, f_gk))))
            raw_l = 5 + num / de(mb.group(3))
            for x in facs:
                raw_l *= x
            mraw = self.grab(cell, r'=\s*([\d,]+)', S, f'фикстура: сырой срок {label}')
            got = de(mraw.group(1))
            # Значение может быть усечено многоточием — сверяем по его точности.
            prec = len(mraw.group(1).split(',')[1]) if ',' in mraw.group(1) else 0
            if abs(got - raw_l.quantize(D(1).scaleb(-prec), rounding=ROUND_HALF_UP)) \
                    > D('0.0000001') and abs(got - raw_l) >= D(1).scaleb(-prec):
                self.fail(S, f'фикстура: Bauzeit {label}',
                          f'сырой срок записан {mraw.group(1)}, формула даёт {raw_l}')
            self.eq(S, f'{label}: округление к 0,5 и подпись', shown, r05(raw_l))
            # Округлённое значение внутри самой формулы (после последнего `→`)
            # обязано совпадать и с формулой, и с подписью колонки: иначе
            # ячейка показывает один расчёт, а колонка — другой.
            arrows = re.findall(r'→\s*(?:округление[^→]*?→\s*)?([\d,]+)', cell)
            if not arrows:
                self.fail(S, f'фикстура: Bauzeit {label}',
                          '[вакуум] округлённое значение срока после `→` не найдено')
            else:
                self.eq(S, f'{label}: округление в формуле', de(arrows[-1]), r05(raw_l))
                self.eq(S, f'{label}: формула и подпись колонки совпадают',
                        de(arrows[-1]), shown)
            return shown, raw_l

        d_a, raw = bauzeit('Haus A', 'Form MFH', 'GK 5 Zeit', bgf_a, mfhz_fx, gk5z_fx)
        d_b, raw_b = bauzeit('Haus B', 'Form Büro', 'GK 4 Zeit', bgf_b, bueroz_fx, gk4z_fx,
                             extra=r'Staffelstart')
        m = self.grab(fx, r'\|\s*Haus B\s*\|[^|]*\|[^|]*\|[^|]*\|[^|]*Staffelstart \+ (\d+)',
                      S, 'фикстура: Staffelstart Haus B')
        stag = de(m.group(1))
        self.eq(S, 'Staffelstart = stagger(n) из спеки', stag, stag_sp)
        m = self.grab(fx, r'\|\s*\*\*Projekt\*\*\s*\|[^|]*\|[^|]*\|\s*\*\*([\d,]+)\s*Monate\*\*', S, 'фикстура: строка Projekt')
        self.eq(S, 'Projekt = max(start+dauer)', de(m.group(1)),
                max(planung + d_a, planung + stag + d_b))

        # неопределённость в процентных пунктах
        pts = re.findall(r'\|\s*`±\s*(\d+)\s*%`\s*\|', fx)
        deltas = re.findall(r'`[−-](\d+)`\s*процентн', fx)
        if len(pts) < 3 or len(deltas) < 2:
            self.fail(U, 'фикстура', '[вакуум] таблица Schätzunsicherheit не распознана')
        else:
            u = [D(p) for p in pts[:3]]
            d = [D(x) for x in deltas[:2]]
            self.eq(U, 'сужение шаг 1', u[0] - d[0], u[1])
            self.eq(U, 'сужение шаг 2', u[1] - d[1], u[2])
            # безусловно: отсутствие строки «Итого» — вакуум, не пропуск
            m = self.grab(fx, r'Итого `[−-](\d+)`', U, 'фикстура: итоговое сужение')
            self.eq(U, 'итоговое сужение', D(m.group(1)), u[0] - u[2])

        # Публикация `self.fx` живёт в `_publish_fx()` — отдельном extractor'е,
        # читающем ТОЛЬКО фикстуру. Здесь её больше нет намеренно: вакуум любого
        # шаблона ниже не имеет права обнулять сверку цитат в README и
        # output-model (вердикт Codex, пункты 2 и 10 — два ложных обвинения
        # корректных файлов из одного сломавшегося парсера).

        # ── контрольный пример calculation-spec §6 (Referenzprojekt R-01) ────
        # Разбор СТРУКТУРНЫЙ, не по формулировке. Прежняя редакция ждала
        # `= **<число> €`; вердикт аудитора по CALC-007 добавил в ту же строку
        # точное значение и префикс (`= точно 3.681.809,272225, показ
        # **≈ 3.682.000 € нетто**`) — и сверка ДЕНЕГ перестала выполняться
        # целиком: `grab` бросал вакуум, `self.fx` не строился, и два самых
        # дорогих класса (`RM-FIXTURE`, `OUT-MONEY`) печатали «не смог
        # проверить» вместо сверки. Это второй случай за сессию: привязка
        # к словам вместо привязки к структуре.
        # Структура, на которую можно опираться: цепочка множителей, знак `=`,
        # затем одно или два числа, последнее из которых стоит перед `€`.
        # Слова «точно», «показ», «нетто», их порядок и разметка не участвуют.
        row = self.grab(sp, r'^\|\s*Referenzprojekt R-01\s*\|([^\n]*)$', 'CALC-SPEC',
                        'спека: строка Referenzprojekt R-01', re.M).group(1)
        mf = self.grab(row, r'([\d.,]+)\s*×\s*([\d.,]+)\s*×\s*([\d,]+)\s*×\s*([\d,]+)\s*\+\s*'
                            r'([\d.,]+)\s*×\s*([\d.,]+)\s*=',
                       'CALC-SPEC', 'спека: формула Bauwerk в R-01')
        f = [de(mf.group(i)) for i in range(1, 7)]
        bauwerk = f[0] * f[1] * f[2] * f[3] + f[4] * f[5]
        self.eq('CALC-SPEC', 'R-01: факторы каталожные', (f[1], f[2], f[3], f[5]),
                (k_sp, gk5_sp, eh55_sp, ugv_sp + tg_sp))
        self._pair_after('CALC-SPEC', 'R-01: Bauwerk', row[mf.end():], bauwerk)
        mb = self.grab(row, r'Berlin\s*([\d,]+)', 'CALC-SPEC', 'спека: регфактор Berlin в R-01')
        self._pair_after('CALC-SPEC', 'R-01: эффект регфактора', row[mb.end():],
                         bauwerk * (de(mb.group(1)) - 1))
        # Срок: структура — база `5 + (BGF − 1.000)/N`, множители через `×`,
        # сырое значение после `=`, целая подпись перед `Monate`.
        mz = self.grab(row, r'Bauzeit:([^|]*?)(\d+(?:,\d+)?)\s*[  ]?Monate',
                       'CALC-SPEC', 'спека: Bauzeit R-01')
        seg, label = mz.group(1), de(mz.group(2))
        m2 = self.grab(seg, r'5\s*\+\s*\(?\s*([\d.,]+)\s*[−–-]\s*([\d.,]+)\s*\)?\s*/\s*([\d.,]+)',
                       'CALC-SPEC', 'спека: база срока R-01')
        facs = [de(x) for x in re.findall(r'×\s*([\d,]+)', seg)]
        if not facs:
            self.fail('CALC-SPEC', 'спека: Bauzeit R-01',
                      '[вакуум] в формуле срока R-01 нет ни одного множителя `× N`')
            facs = [D('1')]
        raw_z = 5 + (de(m2.group(1)) - de(m2.group(2))) / de(m2.group(3))
        for x in facs:
            raw_z *= x
        self.eq('CALC-SPEC', 'R-01: BGF в формуле срока = BGF расчёта', de(m2.group(1)), f[0])
        if gk5z_sp not in facs:
            self.fail('CALC-SPEC', 'спека: Bauzeit R-01',
                      f'формула срока R-01 использует множители {facs}; каталожного фактора '
                      f'GK 5 ({gk5z_sp}) среди них нет')
        mr = re.search(r'=\s*([\d,]+)', seg)
        if not mr:
            self.fail('CALC-SPEC', 'спека: Bauzeit R-01',
                      '[вакуум] сырое значение срока R-01 (после `=`) не найдено')
        elif abs(de(mr.group(1)) - raw_z) >= D('0.000001'):
            self.fail('CALC-SPEC', 'спека: Bauzeit R-01',
                      f'сырой срок записан {mr.group(1)}, формула даёт {raw_z}')
        self.eq('CALC-SPEC', 'R-01: округление к 0,5 и целая подпись (D-17)',
                label, r05(raw_z))

    # -- 8. Индексы в шапках документов (tools/check_indices.py) --------------
    def check_index(self):
        """Гейт устаревших индексов. Вызов реален, а не заявлен в докстринге.

        `check_indices.py` до v3 утверждал «Вызывается из tools/verify.py»,
        при том что `grep check_indices tools/verify.py` давал ноль.
        """
        try:
            import importlib.util
            spec = importlib.util.spec_from_file_location(
                '_all3_check_indices', pathlib.Path(__file__).resolve().parent / 'check_indices.py')
            mod = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(mod)
            findings = mod.run(self.root)
        except Exception as exc:                       # инструмент сломан
            self.fail('INDEX', 'tools/check_indices.py',
                      f'гейт индексов не выполнен — инструмент сломан: {exc!r}')
            return
        for rel, lineno, msg in findings:
            text = self.read(rel) or ''
            rows = text.split('\n')
            line = rows[lineno - 1] if 0 < lineno <= len(rows) else ''
            self.emit('INDEX', rel, lineno, line, msg)

    # -- 9. Честность самого инструмента --------------------------------------
    def check_tool_registry(self):
        src = pathlib.Path(__file__).resolve().read_text(encoding='utf-8')
        declared = set(CHECK_CLASSES)
        if len(declared) != len(CHECK_CLASSES):
            self.fail('TOOL-REGISTRY', 'CHECK_CLASSES', 'реестр содержит дубликаты имён')
        for cls in sorted(self._classes):
            if cls not in declared:
                self.fail('TOOL-REGISTRY', 'CHECK_CLASSES',
                          f'класс «{cls}» зарегистрировал вывод, но не объявлен в CHECK_CLASSES')
        body = src.split('CHECK_CLASSES = (', 1)[-1].split(')\n', 1)[-1]
        for cls in declared:
            if f"'{cls}'" not in body and f'"{cls}"' not in body:
                self.fail('TOOL-REGISTRY', 'CHECK_CLASSES',
                          f'класс «{cls}» объявлен в реестре, но нигде не используется')

    def check_token_exists(self):
        """Каждый var(--x) из кода обязан существовать в tokens.css.

        Введено 06.08 вместе с передачей `tokens.css` второму инструменту
        (PROTOCOL §2-bis). Размен «автор системы владеет токенами» безопасен
        ровно постольку, поскольку сломанная ссылка обнаруживается прогоном,
        а не глазами: переименование токена в системе без правки кода — это
        молча пропавший стиль, худший вид поломки, потому что сборка зелёная.

        Проверяется существование ИМЕНИ, а не значения: значение — предмет
        дизайна, имя — контракт между системой и реализацией.
        """
        css = self.read('design-system/tokens.css') or ''
        # Без якоря строки: tokens.css объявляет по нескольку токенов в
        # строке («--space-7: 48px; --space-8: 64px;»), и якорь видел бы
        # только первый. Ложные срабатывания на `var(--x)` невозможны: там
        # за именем идёт «)», а не «:».
        declared = set(re.findall(r'(--[\w-]+)\s*:', css))
        if not declared:
            self.fail('TOKEN-EXISTS', 'design-system/tokens.css',
                      'ни одного объявленного токена не найдено — проверка потеряла предмет')
            return
        for glob in ('*.tsx', '*.ts'):
            for rel, text in self.files(glob):
                if rel.startswith('tools/') or '__tests__' in rel:
                    continue
                for i, line in enumerate(text.split('\n'), 1):
                    for used in re.findall(r'var\((--[\w-]+)', line):
                        if used not in declared:
                            self.emit('TOKEN-EXISTS', rel, i, line,
                                      f'токен «{used}» используется в коде, но не объявлен '
                                      f'в design-system/tokens.css — стиль пропадёт молча')

    def check_ds_class_exists(self):
        """Каждый класс `a3-*` из кода обязан существовать в components.css.

        Второй замок той же двери, что TOKEN-EXISTS. Дизайн-система владеет
        видом компонента, приложение ссылается на её классы по имени — и имя
        является контрактом. Опечатка в нём или переименование класса в
        системе не ломают сборку: элемент просто теряет оформление и
        выглядит «почти правильно». Это худший режим отказа, потому что он
        проходит и типизацию, и тесты, и беглый взгляд.

        Проверяется существование ИМЕНИ. Соответствие разметки требуемой
        структуре (`.a3-drivers > .a3-drv > .a3-val`) отсюда не видно и
        остаётся за визуальной сверкой — заявлять обратное значило бы
        закрыть пункт, не закрыв риск.
        """
        css = self.read('design-system/components.css')
        if css is None:
            self.fail('DS-CLASS-EXISTS', 'design-system/components.css',
                      'единый файл классов не найден — приложение ссылается в пустоту')
            return
        declared = set(re.findall(r'\.(a3-[\w-]+)', css))
        if not declared:
            self.fail('DS-CLASS-EXISTS', 'design-system/components.css',
                      'ни одного класса a3-* не объявлено — проверка потеряла предмет')
            return
        for glob in ('*.tsx', '*.ts'):
            for rel, text in self.files(glob):
                if rel.startswith('tools/') or '__tests__' in rel:
                    continue
                for i, line in enumerate(text.split('\n'), 1):
                    for used in re.findall(r'(?<![\w-])(a3-[\w-]+)', line):
                        if used not in declared:
                            self.emit('DS-CLASS-EXISTS', rel, i, line,
                                      f'класс «{used}» используется в коде, но не объявлен '
                                      f'в design-system/components.css — оформление пропадёт молча')

    def check_dc_coverage(self):
        """DC-COVERAGE (предупреждения): корень группы взят, дочерние — нет.

        Машинная ловля класса «почти правильно», который ревью № 13 находило
        глазами (дефект 17): компонент берёт корневой класс системы, а
        дочернюю структуру из перечня `Classes:` собирает утилитами или не
        собирает вовсе — и тихо разваливается при следующей правке CSS.

        ПРЕДУПРЕЖДЕНИЕ, а не нарушение: перечень `Classes:` включает и
        опциональные вариант-классы (a3-phase-ausbau, a3-hb-sub), чью
        обязательность знает контракт, а не этот детектор. Предупреждение —
        это адрес для сверки, зелёный прогон им не покупается.
        """
        css = self.read('design-system/components.css')
        if css is None:
            return
        parts = []
        for glob in ('*.tsx', '*.ts'):
            for rel, text in self.files(glob):
                if rel.startswith('src/') and '__tests__' not in rel:
                    parts.append(text)
        used = set(re.findall(r'(?<![\w-])(a3-[\w-]+)', '\n'.join(parts)))
        for m in re.finditer(
                r'/\*\s*(DC-[\d/a-zA-Z· -]+?)\.\s*Structure:.*?Classes:\s*(.+?)\*/',
                css, re.S):
            name = ' '.join(m.group(1).split())
            classes = re.findall(r'\.(a3-[\w-]+)', m.group(2))
            taken = [c for c in classes if c in used]
            missing = [c for c in classes if c not in used]
            if taken and missing:
                self.warn.append(
                    f'{WARN_DC_COVERAGE}: {name} — группа в прототипе, из перечня '
                    f'Classes: не взяты {", ".join("." + c for c in missing)} '
                    f'(обязательность — за контрактом)')

    def check_no_visual_utility(self):
        """NO-VISUAL-UTILITY (предупреждения): утилита перекрашивает контракт.

        Граница, объявленная при переводе на единый источник: **система
        владеет видом компонента, приложение — композицией страницы.**
        Отступ между блоками и место в сетке принадлежат странице; цвет,
        типографика, паддинг и бордер внутри компонента — системе.

        Совмещение `a3-*` с визуальной утилитой на одном элементе ломает
        границу молча: пока значения совпадают, экран выглядит правильно, а
        при правке системы утилита остаётся и переопределяет её — компонент
        расходится с витриной, не сломавшись.

        ПРЕДУПРЕЖДЕНИЕ, а не нарушение: часть совмещений законна (утилита
        композиции, доборный класс на элементе-хосте). Предупреждение даёт
        адрес для решения, зелёный прогон им не покупается.
        """
        # Визуальные утилиты: цвет, типографика, паддинг, бордер, скругление,
        # тень. Отступы (m-*), сетка и размеры — композиция, не вид.
        visual = re.compile(
            r'^(?:'
            r'text-(?:text-\w+|body|small|caption|heading-\d|display\w*|left|right|center)'
            r'|bg-\w[\w-]*'
            r'|border(?:-[trblxy])?(?:-(?:border-\w+|selected|contrast|hairline|\d+))?$'
            r'|p[trblxy]?-\d'
            r'|font-(?:bold|medium|regular)'
            r'|rounded\S*|shadow\S*'
            r')$')
        # Типографические примитивы (SmallText, PageHeader, заголовок,
        # lede, имя) владеют РОЛЬЮ текста: кегль, начертание, цвет. Место
        # текста на странице — её дело, поэтому паддинг и выравнивание на
        # них нарушением границы не являются. Различение введено после
        # разбора первых находок: единое правило обвиняло композицию.
        typography = {'a3-cap', 'a3-hero-title', 'a3-lede', 'a3-meta', 'a3-nm',
                      'a3-sub', 'a3-t-body', 'a3-t-cap', 'a3-t-small'}
        role_only = re.compile(
            r'^(?:text-(?:text-\w+|body|small|caption|heading-\d|display\w*)'
            r'|bg-\w[\w-]*|font-(?:bold|medium|regular))$')
        for rel, text in self.files('*.tsx'):
            if not rel.startswith('src/') or '__tests__' in rel:
                continue
            for i, line in enumerate(text.split('\n'), 1):
                for m in re.finditer(r'className="([^"]*)"', line):
                    toks = m.group(1).split()
                    a3 = [x for x in toks if x.startswith('a3-')]
                    rx = role_only if a3 and set(a3) <= typography else visual
                    bad = [x for x in toks if rx.match(x)]
                    if a3 and bad:
                        self.warn.append(
                            f'{WARN_NO_VISUAL_UTILITY}: {rel}:{i} — {", ".join(a3)} '
                            f'несёт визуальные утилиты {", ".join(bad)}: вид '
                            f'принадлежит системе, странице — композиция')

    def check_gallery_single_source(self):
        """GALLERY-SINGLE-SOURCE: у галереи нет собственной разметки образцов.

        Механизм решения D-28. Прежде образец существовал дважды — рукописной
        разметкой в витрине и второй рукописной разметкой в QA-галерее, — и
        «дизайн-система поставляет компоненты» оставалось намерением:
        сравнить две ручные разметки было нечем. Детекторы классов проверяют
        одну треть компонента из трёх и по построению этого не видят.

        Проверка держит ровно одно свойство: **экран галереи обходит реестр
        и ничего не рисует сам**. Как только в нём появляется собственный
        специмен, вторая витрина возрождается — а начинается это всегда с
        одного «временного» блока.
        """
        gallery = self.read('src/design-system/Gallery.tsx')
        screen = self.read('src/screens/Grundlagen.tsx')
        registry = self.read('src/design-system/registry.tsx')
        if gallery is None or screen is None or registry is None:
            self.fail('GALLERY-SINGLE-SOURCE', 'src/design-system/registry.tsx',
                      'реестр специменов, галерея или QA-страница отсутствуют — '
                      'решение D-28 требует всех трёх: объявление, показ и '
                      'страница, которая ничего не объявляет сама')
            return
        # QA-страница вправе показывать галерею и диагностику — и только.
        for i, line in enumerate(screen.split('\n'), 1):
            if 'Specimen' in line and 'design-system' not in line:
                self.fail('GALLERY-SINGLE-SOURCE',
                          f'src/screens/Grundlagen.tsx:{i}',
                          'на QA-странице снова объявляется специмен; образец '
                          'объявляется только в src/design-system/registry.tsx '
                          '(D-28) — иначе возвращается вторая витрина')
        # Галерея рисует ОПРАВУ образца, но не его содержимое: содержимое
        # приходит функцией `render` из реестра.
        if 'SPECIMEN_GROUPS' not in gallery:
            self.fail('GALLERY-SINGLE-SOURCE', 'src/design-system/Gallery.tsx',
                      'галерея не обходит реестр — значит рисует образцы сама')
        for token in ('<Button', '<SegmentedControl', '<RadioCardGroup',
                      '<NumericField', '<Skeleton', '<ProvenanceChip'):
            if token in gallery:
                self.fail('GALLERY-SINGLE-SOURCE', 'src/design-system/Gallery.tsx',
                          f'галерея строит {token[1:]} сама; образец обязан '
                          f'приходить из реестра функцией render')

    # -- архитектурное управление Design System -----------------------------
    def _check_ds_dependencies(self):
        """GOV-DS-DEP: канонический UI не зависит от продукта или QA."""
        canonical = {self._path_key(path) for path in CANONICAL_DS_MODULES}
        for rel in CANONICAL_DS_MODULES:
            source = self.read(rel)
            if source is None:
                self.fail(
                    'GOV-DS-DEP', rel,
                    '[вакуум] модуль из CANONICAL_DS_MODULES отсутствует; '
                    'переименование требует атомарно обновить явный манифест')
                continue
            raw_lines = source.split('\n')
            references = self._module_references(self._mask_comments(source))
            for _, _, specifier, lineno, _ in references:
                if specifier in CANONICAL_DS_EXTERNAL_DEPS:
                    continue
                target = self._module_target(rel, specifier)
                if target in canonical or target in CANONICAL_DS_SHARED_MODULES:
                    continue
                line = raw_lines[lineno - 1] if lineno <= len(raw_lines) else ''
                self.emit(
                    'GOV-DS-DEP', rel, lineno, line,
                    f'канонический модуль импортирует «{specifier}» вне замороженной '
                    'границы; Design System не зависит от Sales Platform/QA. '
                    'Перенести продуктовую композицию к потребителю либо предложить '
                    'общую возможность канонически')

    def _check_qa_boundary(self):
        """GOV-QA-BOUNDARY: QA Foundation рендерит канон, но не экспортирует UI."""
        canonical = {self._path_key(path) for path in CANONICAL_DS_MODULES}
        qa = {self._path_key(path) for path in QA_FOUNDATION_MODULES}
        for rel in QA_FOUNDATION_MODULES:
            if self.read(rel) is None:
                self.fail(
                    'GOV-QA-BOUNDARY', rel,
                    '[вакуум] модуль из QA_FOUNDATION_MODULES отсутствует; '
                    'граница не может молча потерять переименованный узел')

        for glob in ('*.ts', '*.tsx'):
            for rel, source in self.files(glob):
                if not rel.startswith('src/') or '__tests__' in rel.split('/'):
                    continue
                importer = self._path_key(rel)
                raw_lines = source.split('\n')
                references = self._module_references(self._mask_comments(source))
                for _, kind, specifier, lineno, _ in references:
                    target = self._module_target(rel, specifier)
                    if target in qa and importer not in qa and (importer, target) != QA_ROUTE_EDGE:
                        line = raw_lines[lineno - 1] if lineno <= len(raw_lines) else ''
                        self.emit(
                            'GOV-QA-BOUNDARY', rel, lineno, line,
                            f'продуктовый модуль импортирует QA Foundation «{specifier}»; '
                            'единственная внешняя грань — App → Grundlagen. Импортировать '
                            'канонический компонент напрямую, не через QA')
                    if kind == 'export' and importer in canonical | qa:
                        line = raw_lines[lineno - 1] if lineno <= len(raw_lines) else ''
                        self.emit(
                            'GOV-QA-BOUNDARY', rel, lineno, line,
                            f'barrel re-export «{specifier}» создаёт второй публичный вход; '
                            'потребитель обязан импортировать конкретный канонический модуль')

    def _retired_source_files(self):
        """Ровно авторские поверхности, где снятый путь может снова заработать."""
        selected = {}
        for glob in ('*.ts', '*.tsx', '*.css', '*.json'):
            for rel, source in self.files(glob):
                if rel.startswith('src/'):
                    selected[rel] = source
                elif (rel.startswith('design-system/') and rel.count('/') == 1
                      and rel.endswith('.css')):
                    selected[rel] = source
        for rel in ('vite.config.ts', 'vitest.config.ts', 'tsconfig.json',
                    'tailwind.config.ts'):
            source = self.read(rel)
            if source is not None:
                selected[rel] = source
        return sorted(selected.items())

    def _check_retired_paths(self):
        """GOV-RETIRED-PATH: снятые входы не возвращаются под прежним именем."""
        retired = (
            ('@ds', re.compile(r'(?<![\w-])@ds(?:/|\b)'),
             '70ba769', 'использовать конкретный канонический файл/React-модуль без alias'),
            ('ALL_SPECIMENS', re.compile(r'\bALL_SPECIMENS\b'),
             '70ba769', 'использовать COMPONENT_REGISTRY или SPECIMEN_GROUPS'),
            ('DataStateKey', re.compile(r'\bDataStateKey\b'),
             '70ba769', 'импортировать DataStateKind из components/DataStates'),
            ('UncertaintyBadge/UncertaintyBand',
             re.compile(r'\bUncertainty(?:Badge|Band)\b'),
             '70ba769', 'использовать единый EstimateUncertaintyBadge'),
            ('HIT', re.compile(r'\bHIT\b'),
             '70ba769', 'использовать канонический контроль и его hit-target контракт'),
            ('qa.notBuilt', re.compile(r'\bqa\.notBuilt\b'),
             'cf7a7bf', 'брать состояние возможностей из реестра специменов'),
        )
        for rel, source in self._retired_source_files():
            suffix = pathlib.PurePosixPath(rel).suffix
            clean = self._mask_comments(source, line_comments=suffix not in ('.css', '.json'))
            raw_lines = source.split('\n')
            clean_lines = clean.split('\n')

            if re.search(r'/Uncertainty(?:Badge|Band)\.(?:ts|tsx)$', '/' + rel):
                self.emit(
                    'GOV-RETIRED-PATH', rel, 1, raw_lines[0] if raw_lines else '',
                    'снятый модуль UncertaintyBadge/UncertaintyBand возвращён '
                    '(удалён 70ba769); использовать EstimateUncertaintyBadge')

            for lineno, (line, raw_line) in enumerate(
                    zip(clean_lines, raw_lines), 1):
                for name, pattern, commit, alternative in retired:
                    if pattern.search(line):
                        self.emit(
                            'GOV-RETIRED-PATH', rel, lineno, raw_line,
                            f'снятый вход «{name}» вернулся (удалён {commit}); '
                            f'{alternative}')
                if rel != 'src/design-system/motion.ts' and re.search(
                        r'\buseReducedMotion\b', line):
                    self.emit(
                        'GOV-RETIRED-PATH', rel, lineno, raw_line,
                        'локальный/прямой useReducedMotion снят в 70ba769; '
                        'использовать useSemanticMotion из design-system/motion')
                if suffix == '.css' and re.search(
                        r'(?<![\w-])\.circle(?![\w-])', line):
                    self.emit(
                        'GOV-RETIRED-PATH', rel, lineno, raw_line,
                        'общий CSS helper .circle снят в 70ba769; круг принадлежит '
                        'конкретному каноническому a3-* компоненту')
                if suffix in ('.ts', '.tsx') and 'className' in line and re.search(
                        r'(?<![\w-])circle(?![\w-])', line):
                    self.emit(
                        'GOV-RETIRED-PATH', rel, lineno, raw_line,
                        'className «circle» ссылается на снятый helper (70ba769); '
                        'использовать класс конкретного канонического компонента')

    def _check_vo_t4_capabilities(self):
        """GOV-CAPABILITY: VO-T4 lifecycle is explicit and source-proven.

        A registry specimen proves a canonical shape, not a product adoption.
        This small manifest therefore requires each ACTIVE capability to name
        a real product use, while downstream-only capability approvals carry
        named owners and an expiry date. The separate ownership scan prevents
        a second WorkflowStepper family from returning under a new consumer.
        """
        rel = 'design-system/capability-governance.json'
        raw = self.read(rel)
        if raw is None:
            self.fail('GOV-CAPABILITY', rel,
                      'VO-T4 capability manifest is absent; ACTIVE adoption and downstream approval cannot be verified')
            return
        try:
            manifest = json.loads(raw)
        except json.JSONDecodeError as exc:
            self.fail('GOV-CAPABILITY', rel,
                      f'VO-T4 capability manifest is invalid JSON: {exc.msg}')
            return
        capabilities = manifest.get('capabilities') if isinstance(manifest, dict) else None
        if not isinstance(capabilities, list):
            self.fail('GOV-CAPABILITY', rel,
                      'manifest must contain a capabilities list')
            return
        expected = {
            'canvas', 'paper', 'stage', 'stage-deep', 'media-frame',
            'workflow-stepper', 'legacy-workflow-stepper', 'date-field',
            'stepper', 'composition-bar', 'metric-hierarchy', 'structure-type',
            'warning', 'continuity', 'direction', 'reveal', 'state', 'stagger-list',
            # VR3-01 (backlog 1dedc823): the project-readiness family. Ten
            # capabilities declared in src/design-system/registry.tsx and
            # consumed by src/screens/ProjectHome.tsx.
            'semantic-status', 'authority-trace', 'metric-readout',
            'processing-job', 'document-row', 'prerequisite-state',
            'action-gate', 'project-readiness', 'conflict-resolver',
            'question-queue',
        }
        by_id = {}
        for entry in capabilities:
            if not isinstance(entry, dict) or not isinstance(entry.get('id'), str):
                self.fail('GOV-CAPABILITY', rel,
                          'every capability needs a unique string id')
                continue
            cap_id = entry['id']
            if cap_id in by_id:
                self.fail('GOV-CAPABILITY', rel,
                          f'capability «{cap_id}» is declared more than once')
            by_id[cap_id] = entry
        missing = expected - set(by_id)
        unexpected = set(by_id) - expected
        if missing:
            self.fail('GOV-CAPABILITY', rel,
                      f'manifest omits approved lifecycle entries: {", ".join(sorted(missing))}')
        if unexpected:
            self.fail('GOV-CAPABILITY', rel,
                      f'manifest has unapproved lifecycle entries: {", ".join(sorted(unexpected))}')

        today = datetime.date.today()
        registry_only = ('src/design-system/registry.tsx', 'src/design-system/Gallery.tsx', 'src/screens/Grundlagen.tsx')
        for cap_id, entry in by_id.items():
            disposition = entry.get('disposition')
            if disposition not in {'ACTIVE', 'APPROVED_DOWNSTREAM', 'RETIRED'}:
                self.fail('GOV-CAPABILITY', rel,
                          f'«{cap_id}» has invalid disposition «{disposition}»')
                continue
            if disposition == 'ACTIVE':
                consumers = entry.get('productConsumers')
                if not isinstance(consumers, list) or not consumers:
                    self.fail('GOV-CAPABILITY', rel,
                              f'ACTIVE «{cap_id}» has no real product consumer; a registry or Foundations specimen does not count')
                    continue
                for consumer in consumers:
                    if not isinstance(consumer, dict):
                        self.fail('GOV-CAPABILITY', rel,
                                  f'ACTIVE «{cap_id}» has malformed product consumer metadata')
                        continue
                    path, pattern = consumer.get('path'), consumer.get('pattern')
                    if not isinstance(path, str) or not isinstance(pattern, str):
                        self.fail('GOV-CAPABILITY', rel,
                                  f'ACTIVE «{cap_id}» consumer needs path and pattern')
                        continue
                    if path in registry_only or path.startswith('src/design-system/'):
                        self.fail('GOV-CAPABILITY', rel,
                                  f'ACTIVE «{cap_id}» claims Design System/Foundation «{path}» as product adoption')
                        continue
                    source = self.read(path)
                    if source is None or pattern not in source:
                        self.fail('GOV-CAPABILITY', rel,
                                  f'ACTIVE «{cap_id}» consumer «{path}» no longer proves pattern «{pattern}»')
            elif disposition == 'APPROVED_DOWNSTREAM':
                owners, expiry = entry.get('owners'), entry.get('expiresAt')
                if not isinstance(owners, list) or not all(isinstance(owner, str) and owner for owner in owners):
                    self.fail('GOV-CAPABILITY', rel,
                              f'APPROVED_DOWNSTREAM «{cap_id}» lacks named downstream owners')
                if not isinstance(expiry, str):
                    self.fail('GOV-CAPABILITY', rel,
                              f'APPROVED_DOWNSTREAM «{cap_id}» lacks expiry metadata')
                    continue
                try:
                    expiry_date = datetime.date.fromisoformat(expiry)
                except ValueError:
                    self.fail('GOV-CAPABILITY', rel,
                              f'APPROVED_DOWNSTREAM «{cap_id}» has invalid expiry «{expiry}»')
                else:
                    if expiry_date < today:
                        self.fail('GOV-CAPABILITY', rel,
                                  f'APPROVED_DOWNSTREAM «{cap_id}» expired on {expiry}; renew or retire it explicitly')
            elif entry.get('productConsumers'):
                self.fail('GOV-CAPABILITY', rel,
                          f'RETIRED «{cap_id}» must not retain product consumer claims')

        canonical = self.read('src/design-system/WorkflowStepper.tsx') or ''
        if 'export function WorkflowStepper' not in canonical:
            self.fail('GOV-CAPABILITY', 'src/design-system/WorkflowStepper.tsx',
                      'canonical WorkflowStepper owner is absent')
        consumers = []
        # VR3-01: `OpportunityCard.tsx` was retired with the four-stage
        # project card; the second real consumer is now the project shell.
        # This tuple is the explicit manifest the module docstring requires
        # to move atomically with such a rename.
        for source_rel in ('src/components/Sidebar.tsx', 'src/screens/ProjectHome.tsx'):
            source = self.read(source_rel) or ''
            if "from '../design-system/WorkflowStepper'" in source and '<WorkflowStepper' in source:
                consumers.append(source_rel)
        if len(consumers) != 2:
            self.fail('GOV-CAPABILITY', 'src/design-system/WorkflowStepper.tsx',
                      'canonical WorkflowStepper must have the two real consumers (Sidebar and ProjectHome), not registry-only adoption')
        for source_rel, source in self.files('*.tsx'):
            if source_rel == 'src/design-system/WorkflowStepper.tsx':
                continue
            clean = self._mask_comments(source)
            if re.search(r'\b(?:export\s+)?(?:function|const)\s+WorkflowStepper\b', clean):
                self.emit('GOV-CAPABILITY', source_rel, 1, source.split('\n')[0],
                          'a second WorkflowStepper owner returned; consume src/design-system/WorkflowStepper.tsx instead')
            if (source_rel.startswith('src/') and '__tests__' not in source_rel
                    and re.search(r'(?<![\w-])a3-(?:wf|chapters)(?![\w-])', clean)):
                self.emit('GOV-CAPABILITY', source_rel, 1, source.split('\n')[0],
                          'retired workflow/chapters CSS ownership returned; use the canonical a3-wfs family')

    def _check_governance_tokens(self):
        """GOV-TOKEN: только узкие, измеримо надёжные случаи сырого вида."""
        color = re.compile(
            r'#[0-9a-fA-F]{3,8}\b|(?<![\w-])'
            r'(?:rgba?|hsla?|lab|lch|oklab|oklch|color)\s*\([^)]*\)', re.I)
        gradient = re.compile(
            r'(?<![\w-])(?:repeating-)?(?:linear|radial|conic)-gradient\s*'
            r'\([^)]*\)', re.I)

        css_sources = {}
        components = self.read('design-system/components.css')
        if components is None:
            self.fail(
                'GOV-TOKEN', 'design-system/components.css',
                '[вакуум] файл канонических component-стилей отсутствует')
        else:
            css_sources['design-system/components.css'] = components
        for rel, source in self.files('*.css'):
            if rel.startswith('src/'):
                css_sources[rel] = source

        for rel, source in sorted(css_sources.items()):
            clean = self._mask_comments(source, line_comments=False)
            raw_lines = source.split('\n')
            for lineno, line in enumerate(clean.split('\n'), 1):
                match = color.search(line) or gradient.search(line)
                if match:
                    self.emit(
                        'GOV-TOKEN', rel, lineno, raw_lines[lineno - 1],
                        f'сырой цвет/градиент «{match.group(0)}» обходит tokens.css; '
                        'использовать семантический var(--token), а новый primitive '
                        'объявлять только в каноническом слое токенов')

        for glob in ('*.ts', '*.tsx'):
            for rel, source in self.files(glob):
                if not rel.startswith('src/') or '__tests__' in rel.split('/'):
                    continue
                clean = self._mask_comments(source)
                raw_lines = source.split('\n')
                sentinel_lines = RUNTIME_COLOR_SENTINELS.get(rel, {})
                for lineno, line in enumerate(clean.split('\n'), 1):
                    sentinels = sentinel_lines.get(line.strip(), frozenset())
                    for match in color.finditer(line):
                        literal = match.group(0)
                        if literal in sentinels:
                            continue
                        self.emit(
                            'GOV-TOKEN', rel, lineno, raw_lines[lineno - 1],
                            f'цветовой литерал «{literal}» в production TypeScript '
                            'обходит семантические токены; использовать var(--token) '
                            'через канонический CSS/component API')

        class_name = re.compile(
            r'className\s*=\s*(?:\{\s*)?(?:'
            r'\"(?P<double>(?:\\.|[^\"\\])*)\"|'
            r"'(?P<single>(?:\\.|[^'\\])*)'|"
            r'`(?P<template>(?:\\.|[^`\\])*)`)\s*\}?', re.S)
        arbitrary = re.compile(
            r'(?<!\S)(?:[\w-]+:)*[\w-]+-\[(?P<body>[^\]]*)\]')
        raw_length = re.compile(
            r'(?<![\w.])[-+]?(?:\d+(?:\.\d+)?|\.\d+)(?:px|rem)\b', re.I)
        for rel, source in self.files('*.tsx'):
            if not rel.startswith('src/') or '__tests__' in rel.split('/'):
                continue
            clean = self._mask_comments(source)
            raw_lines = source.split('\n')
            for match in class_name.finditer(clean):
                group = next(name for name in ('double', 'single', 'template')
                             if match.group(name) is not None)
                body = match.group(group)
                for value in arbitrary.finditer(body):
                    arbitrary_body = value.group('body')
                    if not (re.search(r'#[0-9a-fA-F]{3,8}\b', arbitrary_body)
                            or raw_length.search(arbitrary_body)):
                        continue
                    absolute = match.start(group) + value.start()
                    lineno = clean.count('\n', 0, absolute) + 1
                    self.emit(
                        'GOV-TOKEN', rel, lineno, raw_lines[lineno - 1],
                        f'Tailwind arbitrary value «{value.group(0)}» содержит raw '
                        'hex/px/rem; использовать канонический token/класс. '
                        'Структурные arbitrary values без сырого значения не запрещены')

    def check_design_system_governance(self):
        """Четыре механических границы принятой post-cleanup архитектуры."""
        self._check_ds_dependencies()
        self._check_qa_boundary()
        self._check_retired_paths()
        self._check_vo_t4_capabilities()
        self._check_governance_tokens()

    def check_option_images(self):
        """OPT-IMAGE (предупреждения): покрытие карточек опций изображениями.

        Замок построен ДО поставки (задание № 18) намеренно — так же, как
        сборщик словаря знал о поставке № 3 до её появления: проверка,
        написанная после приёмки, проверяет то, что уже принято.

        Пока манифеста нет, класс не молчит: он объявляет отсутствие
        покрытия как известное состояние. Когда манифест появится,
        предупреждениями станут ПРОПУСКИ — значения фикстуры без файла и
        файлы без значения.
        """
        man = self.read('design-system/assets/options/manifest.json')
        fx = self.read('src/fixtures/derived-prototype.json')
        if fx is None:
            return
        try:
            data = json.loads(fx)
        except Exception:
            return
        values = set()
        for sec in ('kg300', 'kg400', 'zertifikate', 'configurationMode', 'scopeBoundaries'):
            for g in data.get(sec, {}).get('groups', []):
                for c in g.get('choices', []):
                    values.add((g['id'], c['value']))
            # Снятая группа, чьи изображения ПЕРЕЕХАЛИ на ось уровня Building,
            # остаётся законным владельцем своих файлов. Соответствие
            # объявлено в фикстуре полем `valueMap`, а не выводится из
            # совпадения имён: иначе первое же переименование варианта
            # молча превратило бы живое изображение в сироту. Условие —
            # именно объявление: без `imagesMovedTo` файлы остаются сиротами
            # и предупреждение работает как прежде.
            for key, removed in data.get(sec, {}).items():
                if not key.startswith('$removed_') or not isinstance(removed, dict):
                    continue
                if not removed.get('imagesMovedTo'):
                    continue
                gid = (removed.get('former') or {}).get('id')
                if not gid:
                    continue
                for v in (removed.get('valueMap') or {}).values():
                    values.add((gid, v))
        if man is None:
            self.warn.append(
                f'{WARN_OPT_IMAGE}: манифест изображений отсутствует — '
                f'{len(values)} карточек опций без картинки (задание № 18 '
                f'у Codex); подключение ждёт поставки')
            return
        try:
            entries = json.loads(man)
        except Exception:
            self.warn.append(f'{WARN_OPT_IMAGE}: манифест не разбирается как JSON')
            return
        declared = {(e.get('group'), e.get('value')) for e in entries}
        missing = sorted(values - declared)
        extra = sorted(declared - values)
        for g, v in missing:
            self.warn.append(
                f'{WARN_OPT_IMAGE}: {g}/{v} — значение каталога без изображения '
                f'в манифесте')
        for g, v in extra:
            self.warn.append(
                f'{WARN_OPT_IMAGE}: {g}/{v} — изображение без значения в каталоге '
                f'(переименование варианта?)')
        for e in entries:
            f = e.get('file')
            # Существование ДВОИЧНОГО файла проверяется файловой системой,
            # а не чтением как текста: `read()` декодирует UTF-8 и падает на
            # первом же байте картинки. Поймано поставкой № 18 — замок,
            # написанный до неё, рухнул на ней самой.
            if f and not (self.root / 'design-system/assets/options' / f).exists():
                self.warn.append(
                    f'{WARN_OPT_IMAGE}: файл {f} объявлен манифестом, но отсутствует')

    # -- запуск ----------------------------------------------------------------
    def run(self, *, include_governance=True):
        self.check_tokens()
        self.check_token_exists()
        self.check_ds_class_exists()
        self.check_dc_coverage()
        self.check_no_visual_utility()
        self.check_option_images()
        self.check_gallery_single_source()
        if include_governance:
            self.check_design_system_governance()
        self.check_css()
        self.check_css_effective()
        self.check_contrast()
        self.check_gates()
        self.check_r24_prose()
        self.check_units()
        self.check_readme()
        self.check_copy()
        self.check_controls()
        self.check_data_model()
        self.check_data_model_truth()
        self.check_cardinality()
        self.check_annahmen()
        self.check_charter()
        self.check_governance()
        self.check_plan()
        self.check_privacy()
        # Арифметика идёт ПЕРЕД проверками цитат: она публикует величины
        # фикстуры, с которыми сводятся спесимены README и output-model.
        self.check_arithmetic()
        self.check_output_model()
        self.check_readme_contracts()
        self.check_core_contracts()
        self.check_readme_numbers()
        self.check_index()
        # ALLOW подавляет по МЕСТУ, а не по содержанию: дословный дубль
        # allow-строки, дописанный как новое нарушение, подавлялся бы той же
        # записью. Запись, сработавшая больше одного раза, — нарушение.
        for key, n in sorted(self._used_allow.items()):
            if n > 1:
                self.fail('ALLOW-DUP', f'{key[0]}',
                          f'ALLOW-запись {key[1]}/{key[2]} подавила {n} РАЗНЫХ строк '
                          f'(строки {sorted(self._allow_hits[key])}) — исключение выдано одной строке, '
                          f'а не содержимому; дубль обязан быть виден')
        for key, n in sorted(self._used_known.items()):
            if n > 1:
                self.fail('ALLOW-DUP', f'{key[0]}',
                          f'KNOWN_OPEN-запись {key[1]}/{key[2]} покрыла {n} РАЗНЫХ строк '
                          f'(строки {sorted(self._known_hits[key])}) — регистрация выдана одной строке')
        # неиспользованные записи реестров — предупреждение (уборка)
        for key in ALLOW:
            if key not in self._used_allow and (self.root / key[0]).exists():
                self.warn.append(f'allowlist-запись не сработала (строка изменилась/исчезла?): {key}')
        for key in KNOWN_OPEN:
            if key not in self._used_known and (self.root / key[0]).exists():
                self.warn.append(f'KNOWN_OPEN-запись не сработала (нарушение исправлено?): {key}')
        for key in KNOWN_OPEN_FILE:
            if key not in self._used_known_file and (self.root / key[0]).exists():
                self.warn.append(f'KNOWN_OPEN_FILE-запись не сработала (класс закрыт в файле?): {key}')
        for (rel, cls), n in sorted(self._quoted.items()):
            self.warn.append(f'цитата норматива по построению: {rel} · {cls} · {n} строк '
                             f'вида «| <ID> | …» — {EXTRACTED_SOURCES[rel]}')
        for cls in KNOWN_OPEN_CLASS:
            if cls not in self._used_known_class:
                self.warn.append(f'KNOWN_OPEN_CLASS-запись не сработала (класс закрыт целиком?): {cls}')
        self.check_tool_registry()
        return self


# ───────────────────────── selftest ─────────────────────────────────────────

def _bump_control_total(text: str) -> str:
    """Порча ПОКАЗА контрольного итога §6 независимо от вёрстки числа.

    Прежняя редакция требовала формы `= **3 682 000`; правка по вердикту
    CALC-007 добавила «точно …, показ **≈ …», и мутация стала неприменимой —
    то есть класс остался непроверенным, а selftest этого не различал.
    Теперь привязка к самому числу, а не к тому, что стоит перед ним.
    """
    new, n = re.subn(r'3([\s.\u00a0\u202f])682([\s.\u00a0\u202f])000(\s*[\u00a0\u202f ]?€)',
                     r'3\g<1>692\g<2>000\g<3>', text, count=1)
    if not n:
        raise AssertionError('показ контрольного итога 3.682.000 € не найден')
    return new


def _bump_nuf_rate(text: str) -> str:
    """Порча удельной ставки NUF независимо от пробела перед знаком евро."""
    new, n = re.subn(r'≈\s*2\.089(\s*)€/m² NUF', r'≈ 2.189\g<1>€/m² NUF', text, count=1)
    if not n:
        raise AssertionError('ставка 2.089 €/m² NUF не найдена')
    return new



def _sub(pattern, repl, flags=0, count=1):
    """Мутация регуляркой. Существует потому, что `output-model.md` и README
    переписываются другими владельцами параллельно: мутация, привязанная к
    дословной строке, становится «неприменимой» от переноса абзаца, и selftest
    молча терял бы класс. Неприменимость по-прежнему валит selftest —
    но теперь только когда исчезла сама КОНСТРУКЦИЯ, а не её вёрстка."""
    def go(text: str) -> str:
        new, n = re.subn(pattern, repl, text, count=count, flags=flags)
        if not n:
            raise AssertionError(f'конструкция не найдена: {pattern[:60]}')
        return new
    return go


def _drop_line(pattern, flags=0):
    """Удаление первой строки, подходящей под шаблон (снятие условия/поля)."""
    def go(text: str) -> str:
        rows = text.split('\n')
        rx = re.compile(pattern, flags)
        for i, line in enumerate(rows):
            if rx.search(line):
                return '\n'.join(rows[:i] + rows[i + 1:])
        raise AssertionError(f'строка не найдена: {pattern[:60]}')
    return go


def _insert_contract(text: str) -> str:
    """Вставка контракта с денежным спесименом без провенанса перед §2.7."""
    marker = '### 2.7'
    if marker not in text:
        raise AssertionError('раздел §2.7 не найден — границы §2.6 неизвестны')
    block = (
        '### DC-99 · `LeakMetricTile` — Leck-Kachel\n\n'
        '**Анатомия:** `root` → `value`.\n\n'
        '**Состояния — взаимодействие:** `default` · `hover` · `focus` · `pressed` ·\n'
        '`selected` — notApplicableReason: плитка не является выбором из набора ·\n'
        '`disabled` / `readOnly` — notApplicableReason: плитка ничего не редактирует.\n\n'
        '**Состояния — данные:**\n'
        '`loading` — считается · `empty` — данных нет · `partial` — часть входов ·\n'
        '`ready` — готово: `≈ 3.818.000 €` · `error` — упало · `stale` — устарело ·\n'
        '`permission` — роли недоступно.\n\n'
        '**Токены:** `--color-text-primary`.\n\n---\n\n')
    return text.replace(marker, block + marker, 1)


def _dup_allowed_line(text: str) -> str:
    """Дословный дубль строки, исключённой ALLOW, дописанный как новый пункт.

    Аудитор показал: ALLOW подавлял по содержанию строки, поэтому дубль
    исключённой строки подавлялся той же записью. Мутация воспроизводит это
    буквально — берётся первая же строка файла, чей отпечаток есть в ALLOW.
    """
    rows = text.split('\n')
    for line in rows:
        for (rel, cls, h) in ALLOW:
            if rel.endswith('remediation-plan.md') and fp(line) == h and line.strip():
                return text + '\n' + line + '\n'
    raise AssertionError('в файле не найдено ни одной ALLOW-строки для дубля')



