def finding_key(cls, where, msg):
    """Стабильный отпечаток ВСЕЙ находки: класс · файл · текст.

    Дефект, найденный Codex в собственном сравнении selftest (пункт 12 второго
    вердикта): база вычиталась по паре `(класс, адрес)` БЕЗ отпечатка и текста.
    Новая находка того же класса на том же адресе, но с другим содержанием,
    ошибочно скрывалась базовой — то есть живой детектор объявлялся слепым, а
    слепой мог быть объявлен живым.

    Номер строки из ключа ВЫБРОШЕН намеренно, и это не ослабление, а вторая
    половина того же исправления: мутация вида «удалить строку» сдвигает
    нумерацию всего, что ниже, и базовая находка вернулась бы в дельту как
    новая — то есть промах засчитался бы поимкой. Идентичность находки — это
    класс, файл и содержание сообщения (принцип 11), а номер строки — адрес,
    который переживает не всякую правку прозы. Отпечаток строки `(fp=…)` из
    текста убирается: он уже участвует в содержании через само сообщение и
    меняется от типографской правки.
    """
    file_ = where.rsplit(':', 1)[0] if re.search(r':\d+$', where) else where
    body = re.sub(r'\s*\(fp=[0-9a-f]+\)\s*$', '', msg)
    return cls, file_, body


def selftest():
    """Мутационная самопроверка. Три исхода считаются РАЗДЕЛЬНО.

    ЧТО ЭТО ЧИСЛО ЗНАЧИТ. Самопроверка, собранная из НАЙДЕННЫХ дефектов,
    измеряет живость конкретных детекторов, а не покрытие. Единственная мера
    покрытия — независимый набор, придуманный НЕ АВТОРОМ ИНСТРУМЕНТА. Полный
    проход здесь и 0/43 на независимой атаке — совместимые результаты, и
    разница между ними и есть покрытие, которого нет.

    Вердикт Codex, пункт 11: прежняя редакция фиксировала грязную базу и
    продолжала все случаи, а для негативной мутации считала ложным
    срабатыванием ЛЮБОЙ `got_new`, а не дельту к базе. Итог «133/144» смешивал
    три разных исхода — живой детектор, неприменимую мутацию и грязную базу —
    и не был доказательством ни одного из них. Заявленный счёт, который нельзя
    прочитать однозначно, — это тот же дефект, что «0 новых нарушений» на файле
    с нулевым охватом.
    """
    print('SELFTEST: копирую репозиторий во временный каталог и порчу копии…')
    missed, inapplicable, false_pos = [], [], []
    with tempfile.TemporaryDirectory(prefix='all3-verify-selftest-') as tmp:
        tmp = pathlib.Path(tmp)
        base = tmp / 'clean'
        base.mkdir()
        for rel in ['CLAUDE.md']:
            shutil.copy2(ROOT / rel, base / rel)
        for d in ['design-system', 'docs']:
            shutil.copytree(ROOT / d, base / d,
                            ignore=shutil.ignore_patterns('*.png', '*.woff2', 'fonts'))
        # 0. База. Каждый случай сравнивается с ДЕЛЬТОЙ к ней, а не с нулём:
        # иначе чужая незакрытая правка в момент прогона обвиняет негативные
        # мутации в ложном срабатывании, которого они не совершали.
        # GOV-* читает `src/**`; этот старый документный harness намеренно
        # копирует только CLAUDE/design-system/docs. Его не расширяем второй
        # несовместимой моделью дерева: двусторонние GOV-пробы живут в
        # `tools/selftest_governance.py` и входят в `npm run verify`.
        v0 = Verifier(base).run(include_governance=False)
        base_keys = {finding_key(c, w, m) for c, w, m in v0.new}
        if v0.new:
            print(f'\n⚠ SELFTEST: база НЕ ЧИСТАЯ — {len(v0.new)} новых нарушений в '
                  f'немутированной копии. Счёт ниже считается ДЕЛЬТОЙ к базе, поэтому '
                  f'остаётся достоверным, но само это состояние обязано быть закрыто:')
            for c, w, m in v0.new:
                print(f'    · [{c}] {w} — {m[:90]}')
        for idx, entry in enumerate(MUTATIONS):
            desc, rel, mut, expect = entry[0], entry[1], entry[2], entry[3]
            where = entry[4] if len(entry) > 4 else 'new'
            case = tmp / f'case{idx}'
            shutil.copytree(base, case)
            p = case / rel
            text = p.read_text(encoding='utf-8') if p.exists() else ''
            if callable(mut):
                try:
                    p.write_text(mut(text), encoding='utf-8')
                except AssertionError as exc:
                    inapplicable.append((desc, f'{exc}'))
                    shutil.rmtree(case)
                    continue
            elif isinstance(mut, tuple):
                old, new_s = mut
                if old not in text:
                    inapplicable.append((desc, f'«{old[:50]}» не найдено в {rel}'))
                    shutil.rmtree(case)
                    continue
                p.write_text(text.replace(old, new_s, 1), encoding='utf-8')
            else:
                p.parent.mkdir(parents=True, exist_ok=True)
                p.write_text((text + '\n' if text else '') + mut + '\n', encoding='utf-8')
            v = Verifier(case).run(include_governance=False)
            # Дельта к базе, а не абсолютное множество: находка, которая была и
            # без мутации, ничего о детекторе не доказывает и никого не обвиняет.
            # Ключ — ВСЯ находка (`finding_key`), а не пара «класс + адрес»:
            # иначе новая находка того же класса на том же адресе скрывается
            # базовой, и слепой класс отчитывается живым.
            delta = [(c, w, m) for c, w, m in v.new
                     if finding_key(c, w, m) not in base_keys]
            got_new = {c for c, _, _ in delta}
            got_known = {c for c, _, _, _ in v.known}
            if expect is None:
                if got_new:
                    false_pos.append((desc, f'{sorted(got_new)} — '
                                            f'{delta[0][1]}: {delta[0][2][:70]}'))
            elif where == 'known':
                if not (got_known & expect):
                    missed.append((desc, f'не зарегистрирована; ожидались {sorted(expect)} '
                                         f'среди известных открытых, получено {sorted(got_known)}'))
            elif not (got_new & expect):
                missed.append((desc, f'ожидались {sorted(expect)}, новые классы сверх базы: '
                                     f'{sorted(got_new) or "ни одного"}'))
            shutil.rmtree(case)
        # Структурная проба TOOL-REGISTRY: класс, не объявленный в реестре,
        # обязан валить прогон. Файлами это не мутируется — проверяется прямо.
        probe = Verifier(base)
        probe.fail('НЕЗАРЕГИСТРИРОВАННЫЙ-КЛАСС', 'проба', 'проверка двусторонности реестра')
        probe.check_tool_registry()
        registry_ok = any(c == 'TOOL-REGISTRY' for c, _, _ in probe.new)
    total = len(MUTATIONS)
    caught = total - len(missed) - len(inapplicable) - len(false_pos)
    print(f'\nSELFTEST · {total} мутаций. Исходы считаются РАЗДЕЛЬНО:')
    print(f'  поймано (детектор жив)      : {caught}')
    print(f'  НЕ поймано (слепой класс)   : {len(missed)}')
    print(f'  мутация неприменима         : {len(inapplicable)}')
    print(f'  негатив дал новую находку   : {len(false_pos)}')
    print(f'  база немутированной копии   : {len(v0.new)} новых нарушений '
          f'(счёт выше — дельта к ней)')
    print(f'  двусторонность CHECK_CLASSES: {"да" if registry_ok else "НЕТ"}')
    if missed:
        print('\nСЛЕПЫЕ КЛАССЫ — мутация прошла насквозь:')
        for desc, msg in missed:
            print(f'  ✗ {desc}: {msg}')
    if inapplicable:
        print('\nНЕПРИМЕНИМЫЕ МУТАЦИИ — конструкция исчезла из файла. Это НЕ доказательство '
              'живого детектора: класс остался непроверенным.')
        for desc, msg in inapplicable:
            print(f'  ? {desc}: {msg}')
    if false_pos:
        print('\nЛОЖНЫЕ СРАБАТЫВАНИЯ на негативных мутациях:')
        for desc, msg in false_pos:
            print(f'  ! {desc}: {msg}')
    if missed or inapplicable or false_pos or not registry_ok:
        print('\nSELFTEST: ПРОВАЛ. Оригиналы не тронуты.')
        return 2
    print('\nSELFTEST: каждый документный класс реестра ловит свою мутацию. '
          'Оригиналы не тронуты.')
    return 0


# ───────────────────────── main ─────────────────────────────────────────────

def main():
    ap = argparse.ArgumentParser(description='Проверяльщик инвариантов All3 Sales Platform')
    ap.add_argument('--strict', action='store_true',
                    help='известные открытые нарушения тоже валят сборку (гейт релиза)')
    ap.add_argument('--selftest', action='store_true',
                    help='мутационная самопроверка документных детекторов; '
                         'GOV-* проверяет tools/selftest_governance.py')
    args = ap.parse_args()

    if args.selftest:
        sys.exit(selftest())

    v = Verifier(ROOT).run()
    bar = '=' * 72
    print(f'{bar}\nПРОВЕРКА ИНВАРИАНТОВ · новых нарушений: {len(v.new)} · '
          f'из них ПРОВЕРОК НЕ ВЫПОЛНЕНО: {len(v.vacuum)} · '
          f'известных открытых: {len(v.known)} · предупреждений: {len(v.warn)}\n{bar}')
    if v.vacuum:
        # Отдельная секция и первой: это дефект инструмента, а не документа.
        print('\n' + '‼' * 36)
        print('ПРОВЕРКА НЕ ВЫПОЛНЕНА — инструмент не смог сверить, а не сверил и не нашёл.')
        print('Это дефект ИНСТРУМЕНТА: молчаливая сверка хуже отсутствующей, потому что')
        print('зелёный отчёт по ней читают как доказательство. Починить паттерн, не документ.')
        print('‼' * 36)
        for c, w, m in v.vacuum:
            print(f'  ‼ [{c}] {w} — {m}')
    other = [x for x in v.new if x not in v.vacuum]
    if other:
        print('\nНОВЫЕ НАРУШЕНИЯ (валят сборку):')
        for cls in sorted({c for c, _, _ in other}):
            print(f'\n[{cls}]')
            for c, w, m in other:
                if c == cls:
                    print(f'  ✗ {w} — {m}')
    if v.known:
        print('\n⚠ ИЗВЕСТНЫЕ ОТКРЫТЫЕ НАРУШЕНИЯ — зарегистрированы, НЕ замаскированы;')
        print('  отслеживаются планом ремедиации, валят запуск с --strict:')
        for c, w, m, ref in v.known:
            print(f'  ! [{c}] {w} — {m[:90]}\n      → {ref}')
    for w in v.warn:
        print(f'  ⚠ {w}')
    if not v.new and not v.known:
        print('\n✓ Все инварианты выполнены, открытых нарушений нет.')
    elif not v.new:
        print(f'\n✓ Новых нарушений нет. {len(v.known)} известных открытых — см. выше.')
    sys.exit(1 if (v.new or (args.strict and v.known)) else 0)

if __name__ == '__main__':
    main()
